window.LV=[];window.BANK=[];function H(lv,cat,t){BANK.push({lv:lv,cat:cat,t:t});}
LV.push({id:"A1",name:"Başlangıç",units:[
{t:"Selamlaşma ve nezaket",s:"Hallo, danke, bitte",
g:`<p>Almancada her harf okunur, kural çok düzenlidir: <b>ei</b> → <i>ay</i> (nein = nayn), <b>ie</b> → <i>i:</i> (Sie = zi:), <b>eu</b> → <i>oy</i> (Freut mich = froyt miş), <b>sch</b> → <i>ş</i>, <b>w</b> → <i>v</i>, <b>z</b> → <i>ts</i>.</p><p>Hitap ikiye ayrılır: tanımadığın, yaşça büyük ya da resmi biri için <b>Sie</b> (büyük harfle), arkadaş ve aile için <b>du</b>.</p><div class="tw"><table><tr><th>Durum</th><th>Resmi</th><th>Samimi</th></tr><tr><td>Merhaba</td><td>Guten Tag</td><td>Hallo</td></tr><tr><td>Nasılsınız?</td><td>Wie geht es Ihnen?</td><td>Wie geht's?</td></tr><tr><td>Hoşça kal</td><td>Auf Wiedersehen</td><td>Tschüss</td></tr><tr><td>Teşekkürler</td><td>Vielen Dank</td><td>Danke</td></tr></table></div><span class="n"><b>Bitte</b> hem "lütfen" hem "rica ederim" hem de "buyurun" demektir. Avusturya'da selam için çoğu zaman <b>Grüß Gott</b> ya da <b>Servus</b> duyarsın.</span>`,
w:[
["Hallo","merhaba","halo","Hallo, wie geht's?","Merhaba, nasılsın?"],
["Guten Morgen","günaydın","gu:tın morgın","Guten Morgen, Frau Weber!","Günaydın Bayan Weber!"],
["Guten Tag","iyi günler / merhaba","gu:tın ta:k","Guten Tag, Herr Schmidt.","Merhaba Bay Schmidt."],
["Guten Abend","iyi akşamlar","gu:tın a:bınt","Guten Abend, alle zusammen!","Herkese iyi akşamlar!"],
["Gute Nacht","iyi geceler","gu:te naht","Gute Nacht und schlaf gut!","İyi geceler, iyi uykular!"],
["Tschüss","hoşça kal (samimi)","çüs","Tschüss, bis morgen!","Hoşça kal, yarın görüşürüz!"],
["Auf Wiedersehen","hoşça kalın (resmi)","auf vi:dırze:ın","Auf Wiedersehen und danke!","Hoşça kalın, teşekkürler!"],
["danke","teşekkürler","danke","Danke für die Hilfe.","Yardım için teşekkürler."],
["bitte","lütfen / rica ederim","bite","Einen Kaffee, bitte.","Bir kahve lütfen."],
["Entschuldigung","affedersiniz / özür dilerim","entşuldigung","Entschuldigung, wo ist der Bahnhof?","Affedersiniz, istasyon nerede?"],
["ja","evet","ya:","Ja, natürlich.","Evet, tabii ki."],
["nein","hayır","nayn","Nein, danke.","Hayır, teşekkürler."]],
p:[
["Guten Tag, wie geht es Ihnen?","Merhaba, nasılsınız?"],
["Sehr gut, danke. Und Ihnen?","Çok iyiyim, teşekkürler. Ya siz?"],
["Entschuldigung, ich verstehe das nicht.","Affedersiniz, bunu anlamıyorum."],
["Können Sie das bitte wiederholen?","Bunu tekrar edebilir misiniz lütfen?"],
["Sprechen Sie bitte langsamer.","Lütfen daha yavaş konuşun."]]},

{t:"Kendini tanıtma",s:"ich heiße, ich komme aus, ich wohne in",
g:`<p>Kendini tanıtmanın temel kalıpları:</p><div class="tw"><table><tr><th>Kalıp</th><th>Anlam</th></tr><tr><td>Ich heiße …</td><td>Adım …</td></tr><tr><td>Ich bin …</td><td>Ben …(y)im</td></tr><tr><td>Ich komme aus …</td><td>…'liyim (…den geliyorum)</td></tr><tr><td>Ich wohne in …</td><td>…'de oturuyorum</td></tr><tr><td>Ich bin … Jahre alt.</td><td>… yaşındayım</td></tr></table></div><p>Almancada <b>fiil her zaman cümlenin ikinci öğesidir</b>: Ich <b>wohne</b> in Istanbul. / In Istanbul <b>wohne</b> ich.</p><span class="n">Tanışınca resmi ortamda <b>Freut mich</b> (memnun oldum) ya da <b>Sehr angenehm</b> dersin. "Türkiye'den" derken artikel gerekir: aus <b>der</b> Türkei.</span>`,
w:[
["heißen","adı … olmak","hay:sın","Ich heiße Mahsun.","Adım Mahsun."],
["der Name","ad, isim","de:r na:me","Wie ist Ihr Name?","Adınız nedir?"],
["kommen","gelmek","komın","Ich komme aus der Türkei.","Türkiye'denim."],
["wohnen","oturmak, ikamet etmek","vo:nın","Ich wohne in Istanbul.","İstanbul'da oturuyorum."],
["alt","yaşlı / … yaşında","alt","Ich bin dreißig Jahre alt.","Otuz yaşındayım."],
["das Jahr","yıl","das ya:r","Ich lerne seit einem Jahr Deutsch.","Bir yıldır Almanca öğreniyorum."],
["verheiratet","evli","ferhayra:tıt","Ich bin verheiratet.","Evliyim."],
["ledig","bekâr","le:diş","Er ist noch ledig.","O hâlâ bekâr."],
["Freut mich","memnun oldum","froyt miş","Freut mich, Sie kennenzulernen.","Sizinle tanıştığıma memnun oldum."],
["Herr","Bay","her","Das ist Herr Becker.","Bu Bay Becker."],
["Frau","Bayan / kadın / eş","frau","Frau Müller ist Lehrerin.","Bayan Müller öğretmen."],
["die Adresse","adres","di: adrese","Wie ist Ihre Adresse?","Adresiniz nedir?"]],
p:[
["Wie heißen Sie?","Adınız ne?"],
["Ich heiße Mahsun und komme aus der Türkei.","Adım Mahsun, Türkiye'denim."],
["Woher kommst du?","Nerelisin?"],
["Wo wohnen Sie?","Nerede oturuyorsunuz?"],
["Wie alt bist du?","Kaç yaşındasın?"]]},

{t:"Sayılar 0–20",s:"null'dan zwanzig'e",
g:`<p>0–12 arası sayılar ayrı kelimedir. 13–19 ise <b>birler + zehn</b> diye kurulur: drei<b>zehn</b> (13), vier<b>zehn</b> (14).</p><div class="tw"><table><tr><th>Sayı</th><th>Almanca</th><th>Okunuş</th></tr><tr><td>0</td><td>null</td><td>nul</td></tr><tr><td>1 / 2 / 3</td><td>eins / zwei / drei</td><td>ayns / tsvay / dray</td></tr><tr><td>4 / 5 / 6</td><td>vier / fünf / sechs</td><td>fi:r / fünf / zeks</td></tr><tr><td>7 / 8 / 9</td><td>sieben / acht / neun</td><td>zi:bın / aht / noyn</td></tr><tr><td>10 / 11 / 12</td><td>zehn / elf / zwölf</td><td>tse:n / elf / tsvölf</td></tr><tr><td>16 / 17</td><td>sechzehn / siebzehn</td><td>zeştse:n / zi:ptse:n</td></tr></table></div><span class="n">Dikkat: 16 = sech<b>zehn</b> (s düşer), 17 = sieb<b>zehn</b> (en düşer). Telefonda 2 ile 3 karışmasın diye <b>zwo</b> da denir.</span>`,
w:[
["eins","bir","ayns","Ich habe eins.","Bende bir tane var."],
["zwei","iki","tsvay","Zwei Kaffee, bitte.","İki kahve lütfen."],
["drei","üç","dray","Ich habe drei Kinder.","Üç çocuğum var."],
["vier","dört","fi:r","Wir sind vier Personen.","Dört kişiyiz."],
["fünf","beş","fünf","Das kostet fünf Euro.","Bu beş euro."],
["sechs","altı","zeks","Ich stehe um sechs auf.","Altıda kalkarım."],
["sieben","yedi","zi:bın","Zimmer sieben, bitte.","Yedi numaralı oda lütfen."],
["acht","sekiz","aht","Der Kurs beginnt um acht.","Kurs sekizde başlıyor."],
["neun","dokuz","noyn","Ich arbeite ab neun.","Dokuzdan itibaren çalışıyorum."],
["zehn","on","tse:n","Zehn Minuten, bitte.","On dakika lütfen."],
["zwölf","on iki","tsvölf","Es ist zwölf Uhr.","Saat on iki."],
["zwanzig","yirmi","tsvantsiş","Ich warte zwanzig Minuten.","Yirmi dakika bekliyorum."]],
p:[
["Wie ist Ihre Telefonnummer?","Telefon numaranız nedir?"],
["Meine Nummer ist null, fünf, drei, zwei.","Numaram sıfır, beş, üç, iki."],
["Wie viele Personen sind Sie?","Kaç kişisiniz?"],
["Haben Sie ein Zimmer für zwei Personen?","İki kişilik bir odanız var mı?"],
["Ich habe zwei Brüder und eine Schwester.","İki erkek kardeşim ve bir kız kardeşim var."]]},

{t:"sein fiili ve meslekler",s:"ich bin, du bist, er ist",
g:`<p><b>sein</b> = olmak. Almancanın en önemli fiilidir ve düzensizdir; ezberlenmesi gerekir.</p><div class="tw"><table><tr><th>Kişi</th><th>sein</th><th>Örnek</th></tr><tr><td>ich</td><td>bin</td><td>Ich bin Ingenieur.</td></tr><tr><td>du</td><td>bist</td><td>Du bist müde.</td></tr><tr><td>er / sie / es</td><td>ist</td><td>Sie ist Ärztin.</td></tr><tr><td>wir</td><td>sind</td><td>Wir sind hier.</td></tr><tr><td>ihr</td><td>seid</td><td>Ihr seid nett.</td></tr><tr><td>sie / Sie</td><td>sind</td><td>Sind Sie Lehrer?</td></tr></table></div><p>Meslek söylerken <b>artikel kullanılmaz</b>: Ich bin Lehrer (Ben bir öğretmenim değil, "öğretmenim").</p><span class="n">Kadın meslek adları çoğunlukla <b>-in</b> alır: der Lehrer → die Lehrer<b>in</b>, der Arzt → die Ärzt<b>in</b>.</span>`,
w:[
["sein","olmak","zayn","Ich bin Ingenieur.","Mühendisim."],
["der Ingenieur","mühendis","de:r injenyö:r","Mein Bruder ist auch Ingenieur.","Erkek kardeşim de mühendis."],
["der Arzt","doktor (erkek)","de:r artst","Der Arzt kommt gleich.","Doktor birazdan geliyor."],
["die Krankenschwester","hemşire","di: krankınşvestır","Meine Frau ist Krankenschwester.","Eşim hemşire."],
["der Lehrer","öğretmen (erkek)","de:r le:rır","Der Lehrer spricht langsam.","Öğretmen yavaş konuşuyor."],
["der Student","üniversite öğrencisi","de:r ştudent","Ich bin kein Student mehr.","Artık öğrenci değilim."],
["der Kellner","garson","de:r kelnır","Der Kellner ist sehr freundlich.","Garson çok güler yüzlü."],
["der Verkäufer","satış elemanı","de:r ferkoyfır","Der Verkäufer hilft mir.","Satış elemanı bana yardım ediyor."],
["der Beruf","meslek","de:r beru:f","Was sind Sie von Beruf?","Mesleğiniz nedir?"],
["müde","yorgun","mü:de","Ich bin heute sehr müde.","Bugün çok yorgunum."],
["krank","hasta","krank","Sie ist krank.","O hasta."],
["hier","burada","hi:r","Wir sind hier.","Buradayız."]],
p:[
["Was sind Sie von Beruf?","Mesleğiniz nedir?"],
["Ich bin SAP-Berater von Beruf.","Mesleğim SAP danışmanlığı."],
["Bist du Student?","Öğrenci misin?"],
["Wir sind nicht aus Deutschland.","Almanya'dan değiliz."],
["Das ist meine Kollegin.","Bu benim (kadın) iş arkadaşım."]]},

{t:"haben fiili",s:"ich habe, du hast, er hat",
g:`<p><b>haben</b> = sahip olmak. Sahiplik, aç olmak, zamanı olmak ve geçmiş zaman yapımında kullanılır.</p><div class="tw"><table><tr><th>Kişi</th><th>haben</th></tr><tr><td>ich</td><td>habe</td></tr><tr><td>du</td><td>hast</td></tr><tr><td>er / sie / es</td><td>hat</td></tr><tr><td>wir</td><td>haben</td></tr><tr><td>ihr</td><td>habt</td></tr><tr><td>sie / Sie</td><td>haben</td></tr></table></div><p>Türkçede "var" dediğimiz pek çok yapı Almancada <b>haben</b> ile kurulur: Ich <b>habe</b> Hunger (açım), Ich <b>habe</b> Zeit (vaktim var).</p><span class="n"><b>haben</b>'den sonra gelen isim nesne (Akkusativ) olur: ein → <b>einen</b> (eril): Ich habe <b>einen</b> Bruder.</span>`,
w:[
["haben","sahip olmak","ha:bın","Ich habe eine Frage.","Bir sorum var."],
["der Hunger","açlık","de:r hungır","Ich habe Hunger.","Açım."],
["der Durst","susuzluk","de:r durst","Hast du Durst?","Susadın mı?"],
["die Zeit","zaman, vakit","di: tsayt","Ich habe heute keine Zeit.","Bugün vaktim yok."],
["die Frage","soru","di: fra:ge","Haben Sie eine Frage?","Bir sorunuz var mı?"],
["das Auto","araba","das auto","Wir haben ein Auto.","Bir arabamız var."],
["die Wohnung","daire, ev","di: vo:nung","Sie hat eine schöne Wohnung.","Güzel bir dairesi var."],
["das Handy","cep telefonu","das hendi","Hast du dein Handy?","Telefonun yanında mı?"],
["die Idee","fikir","di: ide:","Ich habe eine Idee.","Bir fikrim var."],
["die Lust","istek, heves","di: lust","Hast du Lust auf Kino?","Sinemaya gitmek ister misin?"],
["der Termin","randevu","de:r termi:n","Ich habe morgen einen Termin.","Yarın bir randevum var."],
["die Angst","korku","di: angst","Er hat Angst vor Hunden.","Köpeklerden korkuyor."]],
p:[
["Haben Sie ein Zimmer frei?","Boş odanız var mı?"],
["Ich habe keine Ahnung.","Hiçbir fikrim yok."],
["Hast du heute Abend Zeit?","Bu akşam vaktin var mı?"],
["Wir haben ein Problem.","Bir sorunumuz var."],
["Ich habe Kopfschmerzen.","Başım ağrıyor."]]},

{t:"Artikeller ve nesneler",s:"der, die, das, ein, eine",
g:`<p>Almancada her ismin üç cinsiyetten biri vardır ve <b>isimler hep büyük harfle</b> yazılır. Kelimeyi <b>artikeliyle birlikte</b> öğren.</p><div class="tw"><table><tr><th></th><th>Belirli</th><th>Belirsiz</th><th>Örnek</th></tr><tr><td>Eril</td><td>der</td><td>ein</td><td>der Tisch</td></tr><tr><td>Dişil</td><td>die</td><td>eine</td><td>die Lampe</td></tr><tr><td>Nötr</td><td>das</td><td>ein</td><td>das Buch</td></tr><tr><td>Çoğul</td><td>die</td><td>—</td><td>die Bücher</td></tr></table></div><p>Bazı ipuçları: <b>-ung, -heit, -keit, -ion</b> → die; <b>-chen, -lein</b> → das; günler, aylar, mevsimler → der.</p><span class="n">Uygulamada artikeller renkli: <span class="m">der</span> mavi, <span class="f">die</span> pembe, <span class="nt">das</span> yeşil. Renkleri kelimeyle birlikte hatırlamaya çalış.</span>`,
w:[
["der Tisch","masa","de:r tiş","Der Tisch ist neu.","Masa yeni."],
["der Stuhl","sandalye","de:r ştu:l","Der Stuhl ist bequem.","Sandalye rahat."],
["die Lampe","lamba","di: lampe","Die Lampe ist kaputt.","Lamba bozuk."],
["die Tür","kapı","di: tü:r","Mach bitte die Tür zu.","Lütfen kapıyı kapat."],
["das Buch","kitap","das bu:h","Das Buch ist interessant.","Kitap ilginç."],
["das Fenster","pencere","das fenstır","Das Fenster ist offen.","Pencere açık."],
["der Schlüssel","anahtar","de:r şlüsıl","Wo ist der Schlüssel?","Anahtar nerede?"],
["die Tasche","çanta","di: taşe","Die Tasche ist schwer.","Çanta ağır."],
["das Bett","yatak","das bet","Das Bett ist zu klein.","Yatak çok küçük."],
["die Uhr","saat (eşya)","di: u:r","Die Uhr ist neu.","Saat yeni."],
["der Computer","bilgisayar","de:r kompyu:tır","Der Computer ist langsam.","Bilgisayar yavaş."],
["die Flasche","şişe","di: flaşe","Eine Flasche Wasser, bitte.","Bir şişe su lütfen."]],
p:[
["Was ist das?","Bu ne?"],
["Das ist ein Stuhl.","Bu bir sandalye."],
["Ist das deine Tasche?","Bu senin çantan mı?"],
["Wie heißt das auf Deutsch?","Bunun Almancası ne?"],
["Wie schreibt man das?","Bu nasıl yazılır?"]]},

{t:"Aile ve iyelik",s:"mein, dein, sein, ihr",
g:`<p>İyelik sıfatı, sahip olunan şeyin cinsiyetine göre <b>-e</b> alır (dişil ve çoğul):</p><div class="tw"><table><tr><th>Kişi</th><th>Eril / Nötr</th><th>Dişil / Çoğul</th></tr><tr><td>benim</td><td>mein</td><td>meine</td></tr><tr><td>senin</td><td>dein</td><td>deine</td></tr><tr><td>onun (erkek)</td><td>sein</td><td>seine</td></tr><tr><td>onun (kadın)</td><td>ihr</td><td>ihre</td></tr><tr><td>bizim</td><td>unser</td><td>unsere</td></tr><tr><td>sizin (resmi)</td><td>Ihr</td><td>Ihre</td></tr></table></div><p>Örnek: <b>mein</b> Vater, <b>meine</b> Mutter, <b>meine</b> Eltern.</p><span class="n"><b>sein</b> "onun (erkeğin)", <b>ihr</b> "onun (kadının)" demektir. Türkçedeki gibi tek bir "onun" yoktur.</span>`,
w:[
["der Vater","baba","de:r fa:tır","Mein Vater ist Rentner.","Babam emekli."],
["die Mutter","anne","di: mutır","Meine Mutter wohnt in Izmir.","Annem İzmir'de yaşıyor."],
["die Eltern","anne baba (çoğul)","di: eltırn","Meine Eltern sind nett.","Annemle babam iyi insanlar."],
["der Bruder","erkek kardeş","de:r bru:dır","Mein Bruder ist älter.","Erkek kardeşim (abim) daha büyük."],
["die Schwester","kız kardeş","di: şvestır","Meine Schwester studiert.","Kız kardeşim üniversitede okuyor."],
["der Sohn","oğul","de:r zo:n","Sein Sohn ist fünf Jahre alt.","Oğlu beş yaşında."],
["die Tochter","kız evlat","di: tohtır","Ihre Tochter heißt Elif.","Kızının adı Elif."],
["das Kind","çocuk","das kint","Das Kind spielt im Garten.","Çocuk bahçede oynuyor."],
["der Mann","adam / koca","de:r man","Ihr Mann ist Arzt.","Kocası doktor."],
["die Frau","kadın / eş","di: frau","Meine Frau ist Krankenschwester.","Eşim hemşire."],
["die Großeltern","büyükanne ve büyükbaba","di: gro:seltırn","Meine Großeltern leben auf dem Land.","Büyükannemle büyükbabam köyde yaşıyor."],
["die Familie","aile","di: fami:liye","Meine Familie ist groß.","Ailem kalabalık."]],
p:[
["Hast du Geschwister?","Kardeşin var mı?"],
["Ich habe einen Bruder und eine Schwester.","Bir erkek, bir kız kardeşim var."],
["Das ist meine Frau.","Bu benim eşim."],
["Wie heißt dein Vater?","Babanın adı ne?"],
["Unsere Familie wohnt in Istanbul.","Ailemiz İstanbul'da yaşıyor."]]},

{t:"Ülkeler ve diller",s:"aus der Türkei, in Deutschland, ich spreche",
g:`<p>Ülke adlarının çoğu artikelsizdir: <b>in</b> Deutschland, <b>aus</b> Österreich. Ama birkaç ülke artikel alır:</p><div class="tw"><table><tr><th>Ülke</th><th>…'de</th><th>…'den</th></tr><tr><td>Deutschland</td><td>in Deutschland</td><td>aus Deutschland</td></tr><tr><td>Österreich</td><td>in Österreich</td><td>aus Österreich</td></tr><tr><td>die Türkei</td><td>in der Türkei</td><td>aus der Türkei</td></tr><tr><td>die Schweiz</td><td>in der Schweiz</td><td>aus der Schweiz</td></tr><tr><td>die USA</td><td>in den USA</td><td>aus den USA</td></tr></table></div><p>Bir yere gitmek: <b>nach</b> Wien (şehir, artikelsiz ülke), <b>in die</b> Türkei (artikelli ülke).</p><span class="n">Diller küçük harfle değil, büyük harfle yazılır ve artikel almaz: Ich spreche <b>Deutsch</b>, <b>Türkisch</b> und <b>Englisch</b>.</span>`,
w:[
["Deutschland","Almanya","doyçlant","Ich arbeite oft mit Deutschland.","Sık sık Almanya ile çalışıyorum."],
["Österreich","Avusturya","ö:stırayş","Wien ist die Hauptstadt von Österreich.","Viyana Avusturya'nın başkenti."],
["die Türkei","Türkiye","di: türkay","Ich komme aus der Türkei.","Türkiye'denim."],
["die Schweiz","İsviçre","di: şvayts","Sie wohnt in der Schweiz.","İsviçre'de yaşıyor."],
["sprechen","konuşmak","şpreşın","Ich spreche ein bisschen Deutsch.","Biraz Almanca konuşuyorum."],
["Deutsch","Almanca","doyç","Deutsch ist nicht so schwer.","Almanca o kadar zor değil."],
["Türkisch","Türkçe","türkiş","Meine Muttersprache ist Türkisch.","Ana dilim Türkçe."],
["Englisch","İngilizce","engliş","Sprechen Sie Englisch?","İngilizce konuşuyor musunuz?"],
["die Sprache","dil","di: şpra:he","Deutsch ist eine schöne Sprache.","Almanca güzel bir dil."],
["die Stadt","şehir","di: ştat","Wien ist eine schöne Stadt.","Viyana güzel bir şehir."],
["das Land","ülke / kırsal","das lant","Aus welchem Land kommen Sie?","Hangi ülkedensiniz?"],
["lernen","öğrenmek","lernın","Ich lerne Deutsch.","Almanca öğreniyorum."]],
p:[
["Woher kommen Sie?","Nerelisiniz?"],
["Ich komme aus der Türkei, aus Istanbul.","Türkiye'denim, İstanbul'dan."],
["Welche Sprachen sprechen Sie?","Hangi dilleri konuşuyorsunuz?"],
["Ich spreche Türkisch, Englisch und ein bisschen Deutsch.","Türkçe, İngilizce ve biraz Almanca konuşuyorum."],
["Ich fahre nächsten Monat nach Wien.","Gelecek ay Viyana'ya gidiyorum."]]},

{t:"Sayılar 20–1000 ve fiyat",s:"einundzwanzig, hundert, was kostet",
g:`<p>Almancada iki basamaklı sayılar <b>tersten</b> söylenir: önce birler, sonra onlar. 21 = <b>ein-und-zwanzig</b> (bir-ve-yirmi).</p><div class="tw"><table><tr><th>Sayı</th><th>Almanca</th></tr><tr><td>21</td><td>einundzwanzig</td></tr><tr><td>30 / 40 / 50</td><td>dreißig / vierzig / fünfzig</td></tr><tr><td>60 / 70</td><td>sechzig / siebzig</td></tr><tr><td>80 / 90</td><td>achtzig / neunzig</td></tr><tr><td>100</td><td>(ein)hundert</td></tr><tr><td>365</td><td>dreihundertfünfundsechzig</td></tr><tr><td>1000</td><td>(ein)tausend</td></tr></table></div><p>Fiyat: 3,50 € = <b>drei Euro fünfzig</b>. Ondalık ayracı virgüldür.</p><span class="n">Telefon numaralarını Almanlar genellikle tek tek ya da ikişer ikişer okur. Sayılar her zaman bitişik yazılır.</span>`,
w:[
["dreißig","otuz","draysiş","Ich bin dreißig.","Otuz yaşındayım."],
["vierzig","kırk","firtsiş","Vierzig Euro, bitte.","Kırk euro lütfen."],
["fünfzig","elli","fünftsiş","Der Bus kommt in fünfzig Minuten.","Otobüs elli dakika sonra geliyor."],
["hundert","yüz","hundırt","Das kostet hundert Euro.","Bu yüz euro."],
["tausend","bin","tauzınt","Die Miete ist tausend Euro.","Kira bin euro."],
["kosten","fiyatı … olmak","kostın","Was kostet das?","Bu ne kadar?"],
["der Euro","euro","de:r oyro","Ein Kaffee kostet drei Euro.","Bir kahve üç euro."],
["der Preis","fiyat","de:r prays","Der Preis ist gut.","Fiyat iyi."],
["teuer","pahalı","toyır","Das ist zu teuer.","Bu çok pahalı."],
["billig","ucuz","biliş","Das Hotel ist billig.","Otel ucuz."],
["bezahlen","ödemek","betsa:lın","Kann ich mit Karte bezahlen?","Kartla ödeyebilir miyim?"],
["bar","nakit","ba:r","Ich bezahle bar.","Nakit ödüyorum."]],
p:[
["Was kostet das?","Bu ne kadar?"],
["Das macht zwölf Euro fünfzig.","Toplam on iki euro elli."],
["Kann ich mit Karte bezahlen?","Kartla ödeyebilir miyim?"],
["Das ist mir zu teuer.","Bu bana çok pahalı."],
["Haben Sie etwas Billigeres?","Daha ucuz bir şeyiniz var mı?"]]},

{t:"Düzenli fiiller (şimdiki zaman)",s:"machen, wohnen, arbeiten",
g:`<p>Fiillerin mastarı <b>-en</b> ile biter. Kökü al (mach-), kişi ekini ekle:</p><div class="tw"><table><tr><th>Kişi</th><th>Ek</th><th>machen</th><th>arbeiten</th></tr><tr><td>ich</td><td>-e</td><td>mache</td><td>arbeite</td></tr><tr><td>du</td><td>-st</td><td>machst</td><td>arbeitest</td></tr><tr><td>er / sie / es</td><td>-t</td><td>macht</td><td>arbeitet</td></tr><tr><td>wir</td><td>-en</td><td>machen</td><td>arbeiten</td></tr><tr><td>ihr</td><td>-t</td><td>macht</td><td>arbeitet</td></tr><tr><td>sie / Sie</td><td>-en</td><td>machen</td><td>arbeiten</td></tr></table></div><p>Kökü <b>-t / -d</b> ile bitenler araya <b>e</b> alır: du arbeit<b>e</b>st, er find<b>e</b>t.</p><span class="n">Almanca şimdiki zaman hem "yapıyorum" hem "yaparım" hem de yakın gelecek anlamı taşır: Morgen <b>arbeite</b> ich zu Hause = Yarın evden çalışacağım.</span>`,
w:[
["machen","yapmak","mahın","Was machst du heute?","Bugün ne yapıyorsun?"],
["arbeiten","çalışmak","arbaytın","Ich arbeite von neun bis fünf.","Dokuzdan beşe çalışıyorum."],
["spielen","oynamak / çalmak","şpi:lın","Die Kinder spielen draußen.","Çocuklar dışarıda oynuyor."],
["kochen","yemek pişirmek","kohın","Ich koche am Wochenende.","Hafta sonu yemek yaparım."],
["kaufen","satın almak","kaufın","Wir kaufen Brot.","Ekmek alıyoruz."],
["hören","duymak / dinlemek","hö:rın","Ich höre gern Musik.","Müzik dinlemeyi severim."],
["fragen","sormak","fra:gın","Darf ich etwas fragen?","Bir şey sorabilir miyim?"],
["antworten","cevap vermek","antvortın","Er antwortet nicht.","Cevap vermiyor."],
["brauchen","ihtiyaç duymak","brauhın","Ich brauche Hilfe.","Yardıma ihtiyacım var."],
["suchen","aramak","zu:hın","Ich suche eine Wohnung.","Bir daire arıyorum."],
["finden","bulmak","findın","Ich finde den Schlüssel nicht.","Anahtarı bulamıyorum."],
["gern","severek, memnuniyetle","gern","Ich koche gern.","Yemek yapmayı severim."]],
p:[
["Was machst du am Wochenende?","Hafta sonu ne yapıyorsun?"],
["Ich arbeite heute von zu Hause.","Bugün evden çalışıyorum."],
["Wir spielen jeden Sonntag Fußball.","Her pazar futbol oynarız."],
["Ich höre gern Musik.","Müzik dinlemeyi severim."],
["Was suchen Sie?","Ne arıyorsunuz?"]]},

{t:"Soru sormak",s:"wer, wo, wann, warum, W-Fragen",
g:`<p>Almancada iki tür soru vardır:</p><div class="tw"><table><tr><th>Tür</th><th>Yapı</th><th>Örnek</th></tr><tr><td>Evet/Hayır</td><td>Fiil başa</td><td><b>Kommst</b> du heute?</td></tr><tr><td>W-sorusu</td><td>Soru + fiil + özne</td><td>Wann <b>kommst</b> du?</td></tr></table></div><div class="tw"><table><tr><th>Soru kelimesi</th><th>Anlam</th></tr><tr><td>wer / wen / wem</td><td>kim / kimi / kime</td></tr><tr><td>was</td><td>ne</td></tr><tr><td>wo / woher / wohin</td><td>nerede / nereden / nereye</td></tr><tr><td>wann</td><td>ne zaman</td></tr><tr><td>warum</td><td>neden</td></tr><tr><td>wie / wie viel</td><td>nasıl / ne kadar</td></tr><tr><td>welcher / welche / welches</td><td>hangi</td></tr></table></div><span class="n">Olumsuz bir soruya "evet" derken <b>ja</b> değil <b>doch</b> denir: Kommst du nicht? — <b>Doch!</b> (Gelmiyor musun? — Geliyorum tabii!)</span>`,
w:[
["wer","kim","ve:r","Wer ist das?","Bu kim?"],
["was","ne","vas","Was ist das?","Bu ne?"],
["wo","nerede","vo:","Wo wohnst du?","Nerede oturuyorsun?"],
["woher","nereden","vohe:r","Woher kommst du?","Nerelisin?"],
["wohin","nereye","vohin","Wohin fährst du?","Nereye gidiyorsun?"],
["wann","ne zaman","van","Wann beginnt der Film?","Film ne zaman başlıyor?"],
["warum","neden","varum","Warum lernst du Deutsch?","Neden Almanca öğreniyorsun?"],
["wie","nasıl","vi:","Wie geht es dir?","Nasılsın?"],
["wie viel","ne kadar","vi: fi:l","Wie viel kostet das?","Bu ne kadar?"],
["welche","hangi (dişil/çoğul)","velşe","Welche Farbe magst du?","Hangi rengi seversin?"],
["weil","çünkü","vayl","Ich lerne Deutsch, weil ich nach Wien ziehe.","Almanca öğreniyorum çünkü Viyana'ya taşınıyorum."],
["doch","(olumsuza) evet / yine de","doh","Hast du keine Zeit? — Doch!","Vaktin yok mu? — Var tabii!"]],
p:[
["Wo ist die Toilette, bitte?","Tuvalet nerede lütfen?"],
["Wann fährt der nächste Zug?","Bir sonraki tren ne zaman kalkıyor?"],
["Was bedeutet das?","Bu ne anlama geliyor?"],
["Wie sagt man das auf Deutsch?","Bunu Almanca nasıl söyleriz?"],
["Kannst du mir helfen?","Bana yardım edebilir misin?"]]},

{t:"Saat, günler, aylar",s:"es ist drei Uhr, Montag, Januar",
g:`<p>Saat <b>Es ist … Uhr</b> ile söylenir. Resmi saatte 24'lük sistem yaygındır: 15:30 = fünfzehn Uhr dreißig.</p><div class="tw"><table><tr><th>Saat</th><th>Günlük dil</th></tr><tr><td>3:00</td><td>Es ist drei (Uhr).</td></tr><tr><td>3:15</td><td>Viertel nach drei</td></tr><tr><td>3:30</td><td><b>halb vier</b> (dördün yarısı!)</td></tr><tr><td>3:45</td><td>Viertel vor vier</td></tr><tr><td>3:10</td><td>zehn nach drei</td></tr></table></div><p>Günler ve aylar <b>der</b> alır. "Pazartesi günü": <b>am</b> Montag. "Ocakta": <b>im</b> Januar. Saatte: <b>um</b> acht Uhr.</p><span class="n">En sık hata: <b>halb vier</b> = 3:30'dur, 4:30 değil. Bir sonraki saatin yarısı anlamına gelir. Avusturya'da Ocak ayına <b>Jänner</b> denir.</span>`,
w:[
["die Uhr","saat","di: u:r","Es ist drei Uhr.","Saat üç."],
["die Stunde","saat (süre)","di: ştunde","Der Film dauert zwei Stunden.","Film iki saat sürüyor."],
["die Minute","dakika","di: minu:te","Ich komme in fünf Minuten.","Beş dakikaya geliyorum."],
["halb","yarım, buçuk","halp","Es ist halb acht.","Saat yedi buçuk."],
["der Montag","pazartesi","de:r mo:nta:k","Am Montag arbeite ich im Büro.","Pazartesi ofiste çalışırım."],
["der Dienstag","salı","de:r di:nsta:k","Am Dienstag bin ich beim Kunden.","Salı günü müşterideyim."],
["der Mittwoch","çarşamba","de:r mitvoh","Am Mittwoch habe ich einen Termin.","Çarşamba bir randevum var."],
["der Freitag","cuma","de:r frayta:k","Am Freitag gehen wir essen.","Cuma yemeğe çıkıyoruz."],
["das Wochenende","hafta sonu","das vohınende","Schönes Wochenende!","İyi hafta sonları!"],
["heute","bugün","hoyte","Heute ist Sonntag.","Bugün pazar."],
["morgen","yarın","morgın","Bis morgen!","Yarın görüşürüz!"],
["der Monat","ay","de:r mo:nat","Nächsten Monat fahre ich nach Wien.","Gelecek ay Viyana'ya gidiyorum."]],
p:[
["Wie spät ist es?","Saat kaç?"],
["Es ist Viertel nach neun.","Saat dokuzu çeyrek geçiyor."],
["Um wie viel Uhr beginnt das Meeting?","Toplantı saat kaçta başlıyor?"],
["Welcher Tag ist heute?","Bugün günlerden ne?"],
["Ich habe am Montag um zehn einen Termin.","Pazartesi saat onda bir randevum var."]]},

{t:"Yiyecek ve içecek, Akkusativ",s:"ich möchte einen Kaffee",
g:`<p>Bir şeyi isterken, alırken, yerken o şey <b>nesne</b> olur (Akkusativ). Sadece <b>eril</b> artikel değişir:</p><div class="tw"><table><tr><th></th><th>Özne</th><th>Nesne</th></tr><tr><td>Eril</td><td>der / ein Kaffee</td><td><b>den / einen</b> Kaffee</td></tr><tr><td>Dişil</td><td>die / eine Suppe</td><td>die / eine Suppe</td></tr><tr><td>Nötr</td><td>das / ein Brot</td><td>das / ein Brot</td></tr><tr><td>Çoğul</td><td>die Äpfel</td><td>die Äpfel</td></tr></table></div><p>Kibar istek için <b>Ich möchte …</b> (… istiyorum / isterdim) ya da <b>Ich hätte gern …</b> kullanılır.</p><span class="n">Sayılamayan şeyler artikelsiz kullanılır: Ich trinke <b>Wasser</b>, ich esse <b>Brot</b>. Fransızcadaki gibi "biraz" artikeli yoktur.</span>`,
w:[
["der Kaffee","kahve","de:r kafe:","Ich möchte einen Kaffee.","Bir kahve istiyorum."],
["der Tee","çay","de:r te:","Trinkst du lieber Tee?","Çayı mı tercih edersin?"],
["das Wasser","su","das vasır","Ein Glas Wasser, bitte.","Bir bardak su lütfen."],
["das Brot","ekmek","das bro:t","Das Brot ist frisch.","Ekmek taze."],
["das Brötchen","küçük ekmek, poğaça","das brö:tşın","Zwei Brötchen, bitte.","İki küçük ekmek lütfen."],
["der Käse","peynir","de:r ke:ze","Ich esse gern Käse.","Peynir yemeyi severim."],
["das Fleisch","et","das flayş","Ich esse kein Schweinefleisch.","Domuz eti yemem."],
["das Hähnchen","tavuk (yemek)","das he:nşın","Ich nehme das Hähnchen.","Tavuğu alıyorum."],
["der Apfel","elma","de:r apfıl","Der Apfel ist süß.","Elma tatlı."],
["essen","yemek","esın","Was isst du gern?","Ne yemeyi seversin?"],
["trinken","içmek","trinkın","Ich trinke morgens Tee.","Sabahları çay içerim."],
["möchten","istemek (kibar)","mö:ştın","Ich möchte ein Wasser.","Bir su istiyorum."]],
p:[
["Ich hätte gern einen Tee, bitte.","Bir çay alabilir miyim lütfen."],
["Was möchten Sie trinken?","Ne içmek istersiniz?"],
["Ich esse kein Schweinefleisch.","Domuz eti yemiyorum."],
["Haben Sie auch etwas Vegetarisches?","Vejetaryen bir şeyiniz de var mı?"],
["Guten Appetit!","Afiyet olsun!"]]},

{t:"Ev ve es gibt",s:"es gibt, in, auf, unter, neben",
g:`<p><b>Es gibt</b> = var. Ardından nesne (Akkusativ) gelir: Es gibt <b>einen</b> Balkon. Olumsuzu: <b>Es gibt keinen / keine / kein …</b></p><div class="tw"><table><tr><th>Edat</th><th>Anlam</th><th>Örnek (nerede?)</th></tr><tr><td>in</td><td>içinde</td><td>in der Küche</td></tr><tr><td>auf</td><td>üstünde</td><td>auf dem Tisch</td></tr><tr><td>unter</td><td>altında</td><td>unter dem Bett</td></tr><tr><td>neben</td><td>yanında</td><td>neben dem Sofa</td></tr><tr><td>vor / hinter</td><td>önünde / arkasında</td><td>vor dem Haus</td></tr><tr><td>zwischen</td><td>arasında</td><td>zwischen den Fenstern</td></tr></table></div><p>"Nerede?" sorusunda bu edatlar <b>Dativ</b> ister: der → <b>dem</b>, die → <b>der</b>, das → <b>dem</b>.</p><span class="n">Kısaltmalar: in dem = <b>im</b> (im Wohnzimmer), an dem = <b>am</b>.</span>`,
w:[
["das Haus","ev","das haus","Das Haus ist alt.","Ev eski."],
["die Küche","mutfak","di: küşe","Die Küche ist modern.","Mutfak modern."],
["das Wohnzimmer","oturma odası","das vo:ntsimır","Das Sofa steht im Wohnzimmer.","Kanepe oturma odasında."],
["das Schlafzimmer","yatak odası","das şla:ftsimır","Das Schlafzimmer ist ruhig.","Yatak odası sessiz."],
["das Bad","banyo","das ba:t","Das Bad ist klein.","Banyo küçük."],
["der Balkon","balkon","de:r balkon","Es gibt einen Balkon.","Bir balkon var."],
["das Sofa","kanepe","das zo:fa","Die Katze schläft auf dem Sofa.","Kedi kanepede uyuyor."],
["der Schrank","dolap","de:r şrank","Die Kleider sind im Schrank.","Kıyafetler dolapta."],
["der Kühlschrank","buzdolabı","de:r kü:lşrank","Die Milch ist im Kühlschrank.","Süt buzdolabında."],
["auf","üstünde","auf","Das Handy liegt auf dem Tisch.","Telefon masanın üstünde."],
["unter","altında","untır","Die Schuhe sind unter dem Bett.","Ayakkabılar yatağın altında."],
["neben","yanında","ne:bın","Die Lampe steht neben dem Sofa.","Lamba kanepenin yanında."]],
p:[
["Es gibt einen Supermarkt in der Nähe.","Yakında bir süpermarket var."],
["Gibt es hier WLAN?","Burada Wi-Fi var mı?"],
["Die Wohnung hat drei Zimmer.","Daire üç odalı."],
["Wo ist mein Handy? — Auf dem Tisch.","Telefonum nerede? — Masanın üstünde."],
["Es gibt keinen Aufzug.","Asansör yok."]]},

{t:"Olumsuzluk ve sıfatlar",s:"nicht, kein, groß, klein",
g:`<p>Almancada iki olumsuzluk vardır:</p><div class="tw"><table><tr><th>Kelime</th><th>Ne zaman</th><th>Örnek</th></tr><tr><td>kein / keine</td><td>artikelsiz ya da ein'li ismi olumsuzlar</td><td>Ich habe <b>kein</b> Auto.</td></tr><tr><td>nicht</td><td>fiili, sıfatı, belirli ismi olumsuzlar</td><td>Ich komme <b>nicht</b>. Das ist <b>nicht</b> teuer.</td></tr></table></div><p>Sıfat <b>sein</b>'den sonra gelirse hiç değişmez: Das Haus ist <b>groß</b>. İsmin önüne gelince ek alır: ein <b>großes</b> Haus (bunu A2'de göreceksin).</p><span class="n">"Hiç" anlamı için <b>gar nicht</b> ya da <b>überhaupt nicht</b>: Das ist <b>gar nicht</b> schlecht = Hiç de fena değil.</span>`,
w:[
["nicht","değil","nişt","Das ist nicht teuer.","Bu pahalı değil."],
["kein","hiç … yok (eril/nötr)","kayn","Ich habe kein Auto.","Arabam yok."],
["groß","büyük, uzun boylu","gro:s","Mein Bruder ist sehr groß.","Abim çok uzun boylu."],
["klein","küçük","klayn","Die Wohnung ist klein.","Daire küçük."],
["neu","yeni","noy","Das Handy ist neu.","Telefon yeni."],
["schön","güzel","şö:n","Wien ist schön.","Viyana güzel."],
["gut","iyi","gu:t","Das Essen ist gut.","Yemek iyi."],
["schlecht","kötü","şleşt","Das Wetter ist schlecht.","Hava kötü."],
["schnell","hızlı","şnel","Der Zug ist schnell.","Tren hızlı."],
["langsam","yavaş","langza:m","Das Internet ist langsam.","İnternet yavaş."],
["einfach","kolay, basit","aynfah","Das ist ganz einfach.","Bu çok basit."],
["schwer","zor / ağır","şve:r","Deutsch ist nicht so schwer.","Almanca o kadar zor değil."]],
p:[
["Ich spreche nicht gut Deutsch.","Almancayı iyi konuşamıyorum."],
["Ich habe keine Zeit.","Vaktim yok."],
["Das ist gar nicht schlecht.","Bu hiç de fena değil."],
["Das ist kein Problem.","Bu sorun değil."],
["Ich verstehe das nicht.","Bunu anlamıyorum."]]},

{t:"gehen, fahren, kommen ve şehir",s:"ich gehe, ich fahre, zum, zur",
g:`<p>Almancada "gitmek" ikiye ayrılır: yürüyerek <b>gehen</b>, araçla <b>fahren</b>. fahren düzensizdir: du <b>fährst</b>, er <b>fährt</b>.</p><div class="tw"><table><tr><th>Nereye?</th><th>Edat</th><th>Örnek</th></tr><tr><td>bir yere (eril/nötr)</td><td>zu + dem = <b>zum</b></td><td>zum Bahnhof</td></tr><tr><td>bir yere (dişil)</td><td>zu + der = <b>zur</b></td><td>zur Bank</td></tr><tr><td>şehir, ülke</td><td>nach</td><td>nach Wien</td></tr><tr><td>eve</td><td>nach Hause</td><td>Ich gehe nach Hause.</td></tr><tr><td>evde</td><td>zu Hause</td><td>Ich bin zu Hause.</td></tr></table></div><p>Araçla: <b>mit dem</b> Bus, <b>mit der</b> U-Bahn, <b>mit dem</b> Auto.</p><span class="n">Yakın gelecek için şimdiki zaman yeter: Morgen <b>fahre</b> ich nach Köln = Yarın Köln'e gidiyorum.</span>`,
w:[
["gehen","gitmek (yürüyerek)","ge:ın","Ich gehe zum Supermarkt.","Süpermarkete gidiyorum."],
["fahren","gitmek (araçla)","fa:rın","Wir fahren mit dem Zug.","Trenle gidiyoruz."],
["der Bahnhof","tren istasyonu","de:r ba:nho:f","Wie komme ich zum Bahnhof?","İstasyona nasıl giderim?"],
["die Bank","banka / bank","di: bank","Ich gehe zur Bank.","Bankaya gidiyorum."],
["die Apotheke","eczane","di: apote:ke","Die Apotheke ist geschlossen.","Eczane kapalı."],
["der Supermarkt","süpermarket","de:r zu:pırmarkt","Der Supermarkt ist um die Ecke.","Süpermarket köşede."],
["die Straße","cadde, sokak","di: ştra:se","In dieser Straße wohne ich.","Bu sokakta oturuyorum."],
["der Bus","otobüs","de:r bus","Der Bus kommt gleich.","Otobüs birazdan geliyor."],
["die U-Bahn","metro","di: u:ba:n","Ich fahre mit der U-Bahn.","Metroyla gidiyorum."],
["der Zug","tren","de:r tsu:k","Der Zug hat Verspätung.","Tren rötarlı."],
["das Restaurant","restoran","das restoran","Das Restaurant ist sehr gut.","Restoran çok iyi."],
["nach Hause","eve","na:h hauze","Ich gehe jetzt nach Hause.","Şimdi eve gidiyorum."]],
p:[
["Wie komme ich zum Bahnhof?","İstasyona nasıl gidebilirim?"],
["Ich fahre mit der U-Bahn zur Arbeit.","İşe metroyla gidiyorum."],
["Ist das weit von hier?","Buradan uzak mı?"],
["Kommst du mit?","Sen de geliyor musun?"],
["Ich bin heute zu Hause.","Bugün evdeyim."]]}
]});

LV.push({id:"A2",name:"Temel",units:[
{t:"Günlük rutin ve ayrılabilen fiiller",s:"aufstehen, anrufen, einkaufen",
g:`<p>Pek çok fiilin başında ayrılabilen bir ön ek vardır (<b>auf</b>-, <b>an</b>-, <b>ein</b>-, <b>aus</b>-, <b>mit</b>-, <b>zurück</b>-). Çekimde ön ek <b>cümlenin sonuna</b> gider:</p><div class="tw"><table><tr><th>Mastar</th><th>Cümle</th><th>Anlam</th></tr><tr><td>aufstehen</td><td>Ich <b>stehe</b> um sieben <b>auf</b>.</td><td>Yedide kalkarım.</td></tr><tr><td>anrufen</td><td>Ich <b>rufe</b> dich später <b>an</b>.</td><td>Seni sonra ararım.</td></tr><tr><td>einkaufen</td><td>Wir <b>kaufen</b> am Samstag <b>ein</b>.</td><td>Cumartesi alışveriş yaparız.</td></tr><tr><td>fernsehen</td><td>Er <b>sieht</b> abends <b>fern</b>.</td><td>Akşamları televizyon izler.</td></tr></table></div><p>Ayrılmayan ön ekler de vardır: <b>be-, ver-, er-, ent-, ge-</b> (besuchen, verstehen). Bunlar hiç ayrılmaz.</p><span class="n">Sözlükte ve bu uygulamada ayrılabilen fiiller birleşik (aufstehen) yazılır. Cümlede parçaları ayrı ayrı gördüğünde ikisine birden dokunabilirsin.</span>`,
w:[
["aufstehen","kalkmak (yataktan)","aufşte:ın","Ich stehe um sieben auf.","Yedide kalkarım."],
["aufwachen","uyanmak","aufvahın","Ich wache oft früh auf.","Sık sık erken uyanırım."],
["sich duschen","duş almak","ziş du:şın","Ich dusche mich morgens.","Sabahları duş alırım."],
["frühstücken","kahvaltı etmek","frü:ştükın","Wir frühstücken zusammen.","Birlikte kahvaltı yaparız."],
["anrufen","telefonla aramak","anru:fın","Ich rufe dich später an.","Seni sonra ararım."],
["einkaufen","alışveriş yapmak","aynkaufın","Wir kaufen am Samstag ein.","Cumartesi alışveriş yaparız."],
["anfangen","başlamak","anfangın","Die Arbeit fängt um neun an.","İş dokuzda başlar."],
["aufhören","bitirmek, bırakmak","aufhö:rın","Ich höre um fünf auf.","Beşte bırakırım."],
["fernsehen","televizyon izlemek","fernze:ın","Abends sehe ich fern.","Akşamları televizyon izlerim."],
["schlafen gehen","yatmaya gitmek","şla:fın ge:ın","Ich gehe um elf schlafen.","On birde yatarım."],
["normalerweise","normalde, genellikle","norma:lırvayze","Normalerweise arbeite ich von zu Hause.","Normalde evden çalışırım."],
["danach","ondan sonra","dana:h","Danach gehe ich spazieren.","Ondan sonra yürüyüşe çıkarım."]],
p:[
["Wann stehst du normalerweise auf?","Normalde kaçta kalkarsın?"],
["Zuerst frühstücke ich, dann gehe ich zur Arbeit.","Önce kahvaltı yaparım, sonra işe giderim."],
["Am Dienstag fange ich früher an.","Salı günü daha erken başlarım."],
["Ich rufe dich heute Abend an.","Bu akşam seni ararım."],
["Am Wochenende schlafe ich lange.","Hafta sonu geç kalkarım."]]},

{t:"Modal fiiller",s:"können, müssen, wollen, dürfen, sollen",
g:`<p>Modal fiiller ikinci sırada çekimlenir, asıl fiil <b>mastar hâlinde sona</b> gider: Ich <b>kann</b> gut <b>schwimmen</b>.</p><div class="tw"><table><tr><th></th><th>können</th><th>müssen</th><th>wollen</th><th>dürfen</th><th>sollen</th></tr><tr><td>ich</td><td>kann</td><td>muss</td><td>will</td><td>darf</td><td>soll</td></tr><tr><td>du</td><td>kannst</td><td>musst</td><td>willst</td><td>darfst</td><td>sollst</td></tr><tr><td>er/sie</td><td>kann</td><td>muss</td><td>will</td><td>darf</td><td>soll</td></tr><tr><td>wir/Sie</td><td>können</td><td>müssen</td><td>wollen</td><td>dürfen</td><td>sollen</td></tr></table></div><p>Anlamlar: können = -ebilmek, müssen = zorunda olmak, wollen = istemek, dürfen = izinli olmak, sollen = -meli (başkası söylüyor).</p><span class="n"><b>nicht müssen</b> "yasak" değil "gerek yok" demektir: Du <b>musst nicht</b> kommen = Gelmen gerekmiyor. Yasak için <b>nicht dürfen</b>: Hier <b>darf</b> man <b>nicht</b> rauchen.</span>`,
w:[
["können","-ebilmek","könın","Ich kann ein bisschen Deutsch.","Biraz Almanca biliyorum."],
["müssen","zorunda olmak","müsın","Ich muss heute lange arbeiten.","Bugün uzun çalışmak zorundayım."],
["wollen","istemek","volın","Wir wollen nach Wien ziehen.","Viyana'ya taşınmak istiyoruz."],
["dürfen","izinli olmak","dürfın","Darf ich hier parken?","Buraya park edebilir miyim?"],
["sollen","-meli (tavsiye/görev)","zolın","Der Arzt sagt, ich soll mehr schlafen.","Doktor daha çok uyumam gerektiğini söylüyor."],
["mögen","sevmek, hoşlanmak","mö:gın","Ich mag Kaffee.","Kahveyi severim."],
["schwimmen","yüzmek","şvimın","Kannst du schwimmen?","Yüzebilir misin?"],
["rauchen","sigara içmek","rauhın","Hier darf man nicht rauchen.","Burada sigara içilmez."],
["parken","park etmek","parkın","Man darf hier nicht parken.","Buraya park edilmez."],
["helfen","yardım etmek","helfın","Kann ich Ihnen helfen?","Size yardım edebilir miyim?"],
["leider","maalesef","layder","Leider kann ich nicht kommen.","Maalesef gelemiyorum."],
["vielleicht","belki","filayşt","Vielleicht komme ich später.","Belki sonra gelirim."]],
p:[
["Kann ich Ihnen helfen?","Size yardım edebilir miyim?"],
["Ich muss jetzt leider gehen.","Maalesef şimdi gitmem gerek."],
["Darf ich das Fenster aufmachen?","Pencereyi açabilir miyim?"],
["Du musst nicht kommen, wenn du müde bist.","Yorgunsan gelmene gerek yok."],
["Was soll ich machen?","Ne yapmalıyım?"]]},

{t:"Geçmiş zaman: haben ile Perfekt",s:"ich habe gemacht, ich habe gegessen",
g:`<p>Konuşmada geçmiş zaman <b>Perfekt</b> ile anlatılır: <b>haben</b> (çekimli, 2. sırada) + <b>Partizip II</b> (sonda).</p><div class="tw"><table><tr><th>Tür</th><th>Kural</th><th>Örnek</th></tr><tr><td>Düzenli</td><td>ge- + kök + -t</td><td>machen → <b>gemacht</b></td></tr><tr><td>Düzensiz</td><td>ge- + (değişen kök) + -en</td><td>essen → <b>gegessen</b>, trinken → <b>getrunken</b></td></tr><tr><td>Ayrılabilen</td><td>ön ek + ge + kök</td><td>einkaufen → ein<b>ge</b>kauft</td></tr><tr><td>be-/ver-/-ieren</td><td>ge- yok</td><td>besuchen → <b>besucht</b>, telefonieren → <b>telefoniert</b></td></tr></table></div><p>Cümle yapısı bir "çerçeve" gibidir: Ich <b>habe</b> gestern Pizza <b>gegessen</b>.</p><span class="n">Olumsuzu: Ich habe das <b>noch nicht</b> gemacht = Bunu henüz yapmadım.</span>`,
w:[
["gemacht","yaptı (machen)","gemaht","Was hast du gestern gemacht?","Dün ne yaptın?"],
["gegessen","yedi (essen)","gegesın","Ich habe schon gegessen.","Ben yemek yedim bile."],
["getrunken","içti (trinken)","getrunkın","Wir haben Wein getrunken.","Şarap içtik."],
["gesehen","gördü (sehen)","gezeın","Hast du den Film gesehen?","Filmi gördün mü?"],
["gekauft","satın aldı (kaufen)","gekauft","Ich habe ein neues Handy gekauft.","Yeni bir telefon aldım."],
["gearbeitet","çalıştı (arbeiten)","gearbaytıt","Ich habe bis acht gearbeitet.","Sekize kadar çalıştım."],
["geschrieben","yazdı (schreiben)","geşri:bın","Ich habe dir eine Mail geschrieben.","Sana bir e-posta yazdım."],
["gelesen","okudu (lesen)","gele:zın","Hast du das Buch gelesen?","Kitabı okudun mu?"],
["besucht","ziyaret etti (besuchen)","bezu:ht","Wir haben meine Eltern besucht.","Annemle babamı ziyaret ettik."],
["gestern","dün","gestırn","Gestern habe ich viel gearbeitet.","Dün çok çalıştım."],
["schon","zaten, -di bile","şo:n","Hast du schon gegessen?","Yemek yedin mi (bile)?"],
["noch nicht","henüz değil","noh nişt","Ich habe das noch nicht gemacht.","Bunu henüz yapmadım."]],
p:[
["Was hast du am Wochenende gemacht?","Hafta sonu ne yaptın?"],
["Ich habe lange geschlafen und gekocht.","Geç kalktım ve yemek yaptım."],
["Hast du meine Nachricht gelesen?","Mesajımı okudun mu?"],
["Ich habe das Problem schon gelöst.","Sorunu zaten çözdüm."],
["Wir haben uns lange nicht gesehen.","Uzun zamandır görüşmedik."]]},

{t:"Geçmiş zaman: sein ile Perfekt",s:"ich bin gegangen, er ist gekommen",
g:`<p>Yer değiştirme ve durum değişikliği bildiren fiiller Perfekt'te <b>sein</b> alır:</p><div class="tw"><table><tr><th>Fiil</th><th>Perfekt</th><th>Anlam</th></tr><tr><td>gehen</td><td>ist gegangen</td><td>gitti</td></tr><tr><td>kommen</td><td>ist gekommen</td><td>geldi</td></tr><tr><td>fahren</td><td>ist gefahren</td><td>(araçla) gitti</td></tr><tr><td>fliegen</td><td>ist geflogen</td><td>uçtu</td></tr><tr><td>bleiben</td><td>ist geblieben</td><td>kaldı</td></tr><tr><td>werden</td><td>ist geworden</td><td>oldu</td></tr><tr><td>passieren</td><td>ist passiert</td><td>oldu, meydana geldi</td></tr><tr><td>sein</td><td>ist gewesen</td><td>idi</td></tr></table></div><p>Örnek: Wir <b>sind</b> nach Köln <b>gefahren</b>. Was <b>ist</b> <b>passiert</b>?</p><span class="n">Konuşmada <b>sein</b> ve <b>haben</b> için geçmişte genelde Präteritum kullanılır: ich <b>war</b>, ich <b>hatte</b> (ich bin gewesen yerine).</span>`,
w:[
["gegangen","gitti (gehen)","gegangın","Ich bin früh nach Hause gegangen.","Eve erken gittim."],
["gekommen","geldi (kommen)","gekomın","Wann bist du gekommen?","Ne zaman geldin?"],
["gefahren","gitti (fahren)","gefa:rın","Wir sind mit dem Auto gefahren.","Arabayla gittik."],
["geflogen","uçtu (fliegen)","geflo:gın","Ich bin nach Wien geflogen.","Viyana'ya uçtum."],
["geblieben","kaldı (bleiben)","gebli:bın","Wir sind drei Tage geblieben.","Üç gün kaldık."],
["passiert","oldu (passieren)","pasi:rt","Was ist passiert?","Ne oldu?"],
["angekommen","vardı (ankommen)","angekomın","Der Zug ist pünktlich angekommen.","Tren zamanında vardı."],
["aufgestanden","kalktı (aufstehen)","aufgeştandın","Ich bin um sechs aufgestanden.","Altıda kalktım."],
["umgezogen","taşındı (umziehen)","umgetso:gın","Sie ist nach Berlin umgezogen.","Berlin'e taşındı."],
["geboren","doğmuş","gebo:rın","Ich bin 1998 geboren.","1998'de doğdum."],
["letzte","geçen","letste","Letzte Woche war ich in München.","Geçen hafta Münih'teydim."],
["vor","önce (zaman)","fo:r","Vor zwei Jahren bin ich umgezogen.","İki yıl önce taşındım."]],
p:[
["Wann bist du angekommen?","Ne zaman vardın?"],
["Wir sind letztes Jahr nach Italien gefahren.","Geçen yıl İtalya'ya gittik."],
["Was ist passiert?","Ne oldu?"],
["Ich war gestern krank.","Dün hastaydım."],
["Ich bin zu Hause geblieben.","Evde kaldım."]]},

{t:"Alışveriş ve kıyafet",s:"dieser, diese, dieses · anprobieren",
g:`<p>İşaret sıfatı <b>dieser</b> (bu) belirli artikel gibi çekimlenir:</p><div class="tw"><table><tr><th></th><th>Özne</th><th>Nesne</th></tr><tr><td>Eril</td><td>dieser Pullover</td><td>diesen Pullover</td></tr><tr><td>Dişil</td><td>diese Jacke</td><td>diese Jacke</td></tr><tr><td>Nötr</td><td>dieses Hemd</td><td>dieses Hemd</td></tr><tr><td>Çoğul</td><td>diese Schuhe</td><td>diese Schuhe</td></tr></table></div><p>Kıyafet fiilleri: <b>anprobieren</b> (denemek), <b>passen</b> (olmak, uymak — beden), <b>stehen</b> (yakışmak), <b>tragen</b> (giymek).</p><span class="n">Beden için: Die Hose <b>passt</b> mir nicht = Pantolon bana olmuyor. Yakışma için Dativ: Die Farbe <b>steht dir</b> gut = Bu renk sana yakışıyor.</span>`,
w:[
["die Kleidung","kıyafet","di: klaydung","Ich kaufe neue Kleidung.","Yeni kıyafet alıyorum."],
["die Hose","pantolon","di: ho:ze","Die Hose ist zu lang.","Pantolon çok uzun."],
["das Hemd","gömlek","das hemt","Dieses Hemd ist schön.","Bu gömlek güzel."],
["die Jacke","ceket, mont","di: yake","Ich brauche eine warme Jacke.","Sıcak bir monta ihtiyacım var."],
["der Pullover","kazak","de:r pulo:vır","Der Pullover ist aus Wolle.","Kazak yünden."],
["die Schuhe","ayakkabılar","di: şu:e","Diese Schuhe sind bequem.","Bu ayakkabılar rahat."],
["die Größe","beden","di: grö:se","Welche Größe haben Sie?","Bedeniniz kaç?"],
["anprobieren","denemek (kıyafet)","anprobi:rın","Kann ich das anprobieren?","Bunu deneyebilir miyim?"],
["passen","olmak, uymak","pasın","Die Jacke passt perfekt.","Ceket tam oldu."],
["tragen","giymek / taşımak","tra:gın","Er trägt immer Schwarz.","Hep siyah giyer."],
["die Umkleidekabine","deneme kabini","di: umklaydekabi:ne","Wo ist die Umkleidekabine?","Deneme kabini nerede?"],
["das Angebot","indirim, teklif","das angebo:t","Das ist heute im Angebot.","Bu bugün indirimde."]],
p:[
["Kann ich das anprobieren?","Bunu deneyebilir miyim?"],
["Haben Sie das eine Nummer größer?","Bunun bir büyük bedeni var mı?"],
["Die Farbe steht dir gut.","Bu renk sana yakışıyor."],
["Ich schaue nur, danke.","Sadece bakıyorum, teşekkürler."],
["Kann ich das umtauschen?","Bunu değiştirebilir miyim?"]]},

{t:"Restoranda",s:"bestellen, die Rechnung, empfehlen",
g:`<p>Restoranda kibar kalıplar <b>Ich hätte gern …</b>, <b>Ich nehme …</b> ve <b>Für mich …, bitte</b>. "Ich will" garsona karşı kaba duyulur.</p><div class="tw"><table><tr><th>Bölüm</th><th>Almanca</th></tr><tr><td>Başlangıç</td><td>die Vorspeise</td></tr><tr><td>Ana yemek</td><td>das Hauptgericht</td></tr><tr><td>Tatlı</td><td>der Nachtisch / die Nachspeise</td></tr><tr><td>Menü kartı</td><td>die Speisekarte</td></tr><tr><td>Günün menüsü</td><td>das Tagesmenü</td></tr></table></div><p>Hesap: <b>Die Rechnung, bitte</b> ya da <b>Zahlen, bitte</b>. Garson <b>Zusammen oder getrennt?</b> (birlikte mi ayrı mı?) diye sorar.</p><span class="n">Bahşiş genelde %5–10'dur ve öderken söylenir: hesap 27 € ise "<b>30, bitte</b>" ya da "<b>Stimmt so</b>" (üstü kalsın) dersin.</span>`,
w:[
["die Speisekarte","menü","di: şpayzekarte","Die Speisekarte, bitte.","Menü lütfen."],
["bestellen","sipariş vermek","beştelın","Möchten Sie bestellen?","Sipariş vermek ister misiniz?"],
["die Vorspeise","başlangıç","di: fo:rşpayze","Als Vorspeise nehme ich eine Suppe.","Başlangıç olarak çorba alıyorum."],
["das Hauptgericht","ana yemek","das hauptgerişt","Was gibt es als Hauptgericht?","Ana yemek olarak ne var?"],
["der Nachtisch","tatlı","de:r na:htiş","Zum Nachtisch nehme ich Apfelstrudel.","Tatlı olarak elmalı strudel alıyorum."],
["die Rechnung","hesap, fatura","di: reşnung","Die Rechnung, bitte.","Hesap lütfen."],
["empfehlen","tavsiye etmek","empfe:lın","Was können Sie empfehlen?","Ne tavsiye edersiniz?"],
["lecker","lezzetli","lekır","Das war sehr lecker.","Çok lezzetliydi."],
["scharf","acı","şarf","Ist das scharf?","Bu acı mı?"],
["reservieren","rezervasyon yapmak","rezervi:rın","Ich möchte einen Tisch reservieren.","Bir masa ayırtmak istiyorum."],
["getrennt","ayrı ayrı","getrent","Wir zahlen getrennt.","Ayrı ayrı ödüyoruz."],
["das Trinkgeld","bahşiş","das trinkgelt","Das Trinkgeld ist inklusive.","Bahşiş dahil."]],
p:[
["Einen Tisch für zwei, bitte.","İki kişilik bir masa lütfen."],
["Was können Sie empfehlen?","Ne tavsiye edersiniz?"],
["Ich hätte gern das Schnitzel mit Salat.","Salatayla birlikte şnitzel alabilir miyim."],
["Zusammen oder getrennt?","Birlikte mi, ayrı mı?"],
["Stimmt so, danke.","Üstü kalsın, teşekkürler."]]},

{t:"Hava ve mevsimler",s:"es regnet, es ist sonnig",
g:`<p>Hava durumu <b>es</b> ile anlatılır:</p><div class="tw"><table><tr><th>Almanca</th><th>Anlam</th></tr><tr><td>Es ist sonnig / warm / kalt.</td><td>Güneşli / sıcak / soğuk.</td></tr><tr><td>Es regnet.</td><td>Yağmur yağıyor.</td></tr><tr><td>Es schneit.</td><td>Kar yağıyor.</td></tr><tr><td>Es ist windig / bewölkt.</td><td>Rüzgârlı / bulutlu.</td></tr><tr><td>Es sind 20 Grad.</td><td>Hava 20 derece.</td></tr><tr><td>Es gewittert.</td><td>Fırtına var.</td></tr></table></div><p>Mevsimler <b>der</b> alır ve "…'da" için <b>im</b>: im Sommer, im Winter, im Frühling, im Herbst.</p><span class="n">Soru: <b>Wie ist das Wetter?</b> Kişisel his için Dativ: <b>Mir ist kalt</b> = Üşüyorum (Ich bin kalt değil!).</span>`,
w:[
["das Wetter","hava durumu","das vetır","Wie ist das Wetter heute?","Bugün hava nasıl?"],
["die Sonne","güneş","di: zone","Die Sonne scheint.","Güneş parlıyor."],
["der Regen","yağmur","de:r re:gın","Morgen gibt es Regen.","Yarın yağmur var."],
["regnen","yağmur yağmak","re:gnın","Es regnet schon den ganzen Tag.","Bütün gün yağmur yağıyor."],
["der Schnee","kar","de:r şne:","In Wien gibt es im Winter Schnee.","Viyana'da kışın kar olur."],
["kalt","soğuk","kalt","Im Januar ist es sehr kalt.","Ocakta çok soğuk olur."],
["warm","sıcak, ılık","varm","Heute ist es warm.","Bugün hava sıcak."],
["der Sommer","yaz","de:r zomır","Im Sommer fahren wir ans Meer.","Yazın denize gideriz."],
["der Winter","kış","de:r vintır","Der Winter in Wien ist lang.","Viyana'da kış uzun."],
["der Frühling","ilkbahar","de:r frü:ling","Im Frühling ist es schön.","İlkbaharda hava güzel."],
["der Herbst","sonbahar","de:r herpst","Im Herbst regnet es oft.","Sonbaharda sık yağmur yağar."],
["der Regenschirm","şemsiye","de:r re:gınşirm","Vergiss deinen Regenschirm nicht.","Şemsiyeni unutma."]],
p:[
["Wie ist das Wetter heute?","Bugün hava nasıl?"],
["Es regnet, nimm einen Schirm mit.","Yağmur yağıyor, şemsiye al."],
["Mir ist kalt.","Üşüyorum."],
["Morgen soll es schön werden.","Yarın havanın güzel olacağı söyleniyor."],
["Es sind nur fünf Grad.","Hava sadece beş derece."]]},

{t:"Vücut ve sağlık",s:"mir tut … weh, die Apotheke",
g:`<p>Ağrı anlatmanın iki yolu vardır:</p><div class="tw"><table><tr><th>Yapı</th><th>Örnek</th></tr><tr><td>…schmerzen haben</td><td>Ich habe <b>Kopfschmerzen</b>. (başım ağrıyor)</td></tr><tr><td>Mir tut … weh</td><td><b>Mir tut</b> der Rücken <b>weh</b>. (sırtım ağrıyor)</td></tr><tr><td>Mir tun … weh (çoğul)</td><td><b>Mir tun</b> die Füße <b>weh</b>.</td></tr></table></div><p>Doktorda: <b>Ich fühle mich nicht gut</b> (kendimi iyi hissetmiyorum), <b>Ich habe Fieber</b> (ateşim var), <b>Ich bin erkältet</b> (soğuk algınlığım var).</p><span class="n">Almanya ve Avusturya'da reçeteli ilaç sadece <b>Apotheke</b>'de satılır. <b>Drogerie</b> (dm, Bipa) kozmetik ve temizlik dükkânıdır.</span>`,
w:[
["der Kopf","baş","de:r kopf","Mein Kopf tut weh.","Başım ağrıyor."],
["der Bauch","karın","de:r bauh","Ich habe Bauchschmerzen.","Karnım ağrıyor."],
["der Rücken","sırt","de:r rükın","Mir tut der Rücken weh.","Sırtım ağrıyor."],
["der Hals","boğaz, boyun","de:r hals","Ich habe Halsschmerzen.","Boğazım ağrıyor."],
["das Bein","bacak","das bayn","Er hat sich das Bein gebrochen.","Bacağını kırdı."],
["die Hand","el","di: hant","Wasch dir die Hände.","Ellerini yıka."],
["das Fieber","ateş","das fi:bır","Das Kind hat Fieber.","Çocuğun ateşi var."],
["erkältet","soğuk algınlığı olmuş","erkeltıt","Ich bin erkältet.","Soğuk algınlığım var."],
["das Medikament","ilaç","das medikament","Nehmen Sie dieses Medikament dreimal täglich.","Bu ilacı günde üç kez alın."],
["das Rezept","reçete / tarif","das retsept","Ich brauche ein Rezept.","Bir reçeteye ihtiyacım var."],
["die Praxis","muayenehane","di: praksis","Die Praxis ist am Freitag geschlossen.","Muayenehane cuma kapalı."],
["gesund","sağlıklı","gezunt","Bleib gesund!","Sağlıklı kal!"]],
p:[
["Ich fühle mich nicht gut.","Kendimi iyi hissetmiyorum."],
["Seit wann haben Sie die Schmerzen?","Ne zamandan beri ağrınız var?"],
["Ich möchte einen Termin beim Arzt.","Doktordan randevu almak istiyorum."],
["Gute Besserung!","Geçmiş olsun!"],
["Haben Sie etwas gegen Kopfschmerzen?","Baş ağrısı için bir şeyiniz var mı?"]]},

{t:"Yön tarifi ve emir kipi",s:"gehen Sie, nehmen Sie, links, rechts",
g:`<p><b>Emir kipi</b> üç biçimdedir:</p><div class="tw"><table><tr><th>Kime</th><th>Yapı</th><th>Örnek</th></tr><tr><td>Sie</td><td>fiil + Sie</td><td><b>Gehen Sie</b> geradeaus!</td></tr><tr><td>du</td><td>kök (-st düşer)</td><td><b>Geh</b> geradeaus! <b>Nimm</b> den Bus!</td></tr><tr><td>ihr</td><td>ihr biçimi</td><td><b>Geht</b> geradeaus!</td></tr></table></div><div class="tw"><table><tr><th>Yön</th><th>Anlam</th></tr><tr><td>geradeaus</td><td>dümdüz</td></tr><tr><td>links / rechts</td><td>sola / sağa</td></tr><tr><td>an der Ampel</td><td>trafik ışığında</td></tr><tr><td>an der Kreuzung</td><td>kavşakta</td></tr><tr><td>die zweite Straße</td><td>ikinci sokak</td></tr></table></div><span class="n">Emri yumuşatmak için <b>bitte</b> ve <b>mal</b> eklenir: <b>Komm mal</b> her! = Bir buraya gelsene. sein'ın emri: <b>Sei</b> ruhig! / <b>Seien Sie</b> vorsichtig!</span>`,
w:[
["geradeaus","dümdüz","gera:dıaus","Gehen Sie immer geradeaus.","Hep dümdüz gidin."],
["links","sol(a)","links","Biegen Sie links ab.","Sola dönün."],
["rechts","sağ(a)","reşts","Die Bank ist rechts.","Banka sağda."],
["abbiegen","(bir yöne) dönmek","apbi:gın","Biegen Sie an der Ampel rechts ab.","Işıkta sağa dönün."],
["die Ampel","trafik ışığı","di: ampıl","An der Ampel links.","Işıkta sola."],
["die Kreuzung","kavşak","di: kroytsung","Nach der Kreuzung ist die Post.","Kavşaktan sonra postane var."],
["die Ecke","köşe","di: eke","Das Café ist um die Ecke.","Kafe köşede."],
["weit","uzak","vayt","Ist es weit?","Uzak mı?"],
["in der Nähe","yakında","in de:r ne:e","Gibt es eine Apotheke in der Nähe?","Yakında eczane var mı?"],
["nehmen","almak","ne:mın","Nehmen Sie die U-Bahn.","Metroya binin."],
["aussteigen","inmek (araçtan)","ausştaygın","Steigen Sie am Stephansplatz aus.","Stephansplatz'da inin."],
["umsteigen","aktarma yapmak","umştaygın","Sie müssen einmal umsteigen.","Bir kez aktarma yapmanız gerekiyor."]],
p:[
["Entschuldigung, wie komme ich zum Rathaus?","Affedersiniz, belediye binasına nasıl giderim?"],
["Gehen Sie geradeaus und dann die zweite Straße links.","Düz gidin, sonra ikinci sokaktan sola."],
["Es ist nur fünf Minuten zu Fuß.","Yürüyerek sadece beş dakika."],
["Wo muss ich aussteigen?","Nerede inmem gerekiyor?"],
["Können Sie mir das auf der Karte zeigen?","Bunu bana haritada gösterebilir misiniz?"]]},

{t:"Dativ ve kişi zamirleri",s:"mir, dir, ihm, ihn, ihr",
g:`<p>Almancada zamir, cümledeki görevine göre değişir. <b>Akkusativ</b> = -i hâli (beni), <b>Dativ</b> = -e hâli (bana).</p><div class="tw"><table><tr><th>Özne</th><th>Akkusativ</th><th>Dativ</th></tr><tr><td>ich</td><td>mich</td><td>mir</td></tr><tr><td>du</td><td>dich</td><td>dir</td></tr><tr><td>er</td><td>ihn</td><td>ihm</td></tr><tr><td>sie</td><td>sie</td><td>ihr</td></tr><tr><td>wir</td><td>uns</td><td>uns</td></tr><tr><td>ihr</td><td>euch</td><td>euch</td></tr><tr><td>sie / Sie</td><td>sie / Sie</td><td>ihnen / Ihnen</td></tr></table></div><p>Dativ isteyen sık fiiller: <b>helfen, danken, gefallen, gehören, schmecken, antworten</b>. Dativ isteyen edatlar: <b>mit, nach, bei, von, zu, aus, seit</b>.</p><span class="n"><b>gefallen</b> Türkçedeki "hoşuna gitmek" gibidir: Die Stadt <b>gefällt mir</b> = Şehir hoşuma gidiyor (özne şehir).</span>`,
w:[
["mir","bana","mi:r","Kannst du mir helfen?","Bana yardım edebilir misin?"],
["dir","sana","di:r","Ich gebe dir das Buch.","Kitabı sana veriyorum."],
["ihm","ona (erkek)","i:m","Ich schreibe ihm eine Mail.","Ona bir e-posta yazıyorum."],
["ihn","onu (erkek)","i:n","Kennst du ihn?","Onu tanıyor musun?"],
["uns","bizi / bize","uns","Besuch uns mal!","Bir ara bizi ziyaret et!"],
["gefallen","hoşuna gitmek","gefalın","Wien gefällt mir sehr.","Viyana çok hoşuma gidiyor."],
["gehören","ait olmak","gehö:rın","Wem gehört diese Tasche?","Bu çanta kimin?"],
["schmecken","tadı … olmak","şmekın","Schmeckt es dir?","Beğendin mi (yemeği)?"],
["danken","teşekkür etmek","dankın","Ich danke dir.","Sana teşekkür ederim."],
["geben","vermek","ge:bın","Gib mir bitte das Salz.","Tuzu verir misin lütfen."],
["zeigen","göstermek","tsaygın","Ich zeige Ihnen das Büro.","Size ofisi göstereyim."],
["mit","ile","mit","Ich wohne mit meiner Frau.","Eşimle yaşıyorum."]],
p:[
["Wie gefällt dir die Stadt?","Şehri nasıl buldun?"],
["Das schmeckt mir sehr gut.","Bunun tadı çok güzel."],
["Kannst du mir das erklären?","Bunu bana açıklayabilir misin?"],
["Ich rufe ihn morgen an.","Onu yarın ararım."],
["Das gehört mir nicht.","Bu benim değil."]]},

{t:"Eskiden: Präteritum",s:"war, hatte, es gab, konnte",
g:`<p><b>Präteritum</b> yazı dilinin geçmiş zamanıdır. Konuşmada ise özellikle <b>sein, haben, es gibt</b> ve modal fiillerle kullanılır.</p><div class="tw"><table><tr><th>Kişi</th><th>sein</th><th>haben</th><th>können</th><th>müssen</th></tr><tr><td>ich</td><td>war</td><td>hatte</td><td>konnte</td><td>musste</td></tr><tr><td>du</td><td>warst</td><td>hattest</td><td>konntest</td><td>musstest</td></tr><tr><td>er / sie</td><td>war</td><td>hatte</td><td>konnte</td><td>musste</td></tr><tr><td>wir / Sie</td><td>waren</td><td>hatten</td><td>konnten</td><td>mussten</td></tr></table></div><p>Alışkanlık için <b>früher</b> (eskiden) eklenir: <b>Früher war</b> ich oft in Ankara. <b>Als Kind hatte</b> ich einen Hund.</p><span class="n">es gibt → <b>es gab</b> (vardı). Düzenli fiillerde Präteritum eki <b>-te</b>: ich machte, wir wohnten.</span>`,
w:[
["war","idi (sein)","va:r","Das war ein schöner Tag.","Güzel bir gündü."],
["hatte","vardı (haben)","hate","Ich hatte keine Zeit.","Vaktim yoktu."],
["es gab","vardı","es ga:p","Früher gab es hier ein Kino.","Eskiden burada bir sinema vardı."],
["konnte","-ebildi (können)","konte","Ich konnte nicht schlafen.","Uyuyamadım."],
["musste","zorunda kaldı","muste","Ich musste lange warten.","Uzun süre beklemek zorunda kaldım."],
["wollte","istedi","volte","Ich wollte dich anrufen.","Seni aramak istedim."],
["früher","eskiden","frü:ır","Früher habe ich geraucht.","Eskiden sigara içerdim."],
["als Kind","çocukken","als kint","Als Kind war ich sehr ruhig.","Çocukken çok sakindim."],
["damals","o zamanlar","da:ma:ls","Damals wohnten wir in Ankara.","O zamanlar Ankara'da oturuyorduk."],
["oft","sık sık","oft","Wir waren oft am Meer.","Sık sık denizdeydik."],
["immer","her zaman","imır","Es war immer laut.","Her zaman gürültülüydü."],
["die Kindheit","çocukluk","di: kinthayt","Meine Kindheit war schön.","Çocukluğum güzeldi."]],
p:[
["Wo warst du gestern?","Dün neredeydin?"],
["Ich hatte gestern einen langen Tag.","Dün uzun bir gün geçirdim."],
["Als Kind wollte ich Pilot werden.","Çocukken pilot olmak istiyordum."],
["Früher gab es hier keine U-Bahn.","Eskiden burada metro yoktu."],
["Ich konnte leider nicht kommen.","Maalesef gelemedim."]]},

{t:"Karşılaştırma",s:"größer als, so … wie, am besten",
g:`<div class="tw"><table><tr><th>Yapı</th><th>Anlam</th><th>Örnek</th></tr><tr><td>-er + als</td><td>…den daha</td><td>Wien ist <b>kleiner als</b> Berlin.</td></tr><tr><td>so … wie</td><td>… kadar</td><td>Er ist <b>so groß wie</b> ich.</td></tr><tr><td>am …-sten</td><td>en …</td><td>Der Zug ist <b>am schnellsten</b>.</td></tr><tr><td>der / die / das …-ste</td><td>en … (isim önünde)</td><td>der <b>schönste</b> Tag</td></tr></table></div><p>Tek heceli sıfatların çoğu umlaut alır: alt → <b>ä</b>lter, groß → gr<b>ö</b>ßer, jung → j<b>ü</b>nger.</p><span class="n">Düzensizler: gut → <b>besser</b> → am <b>besten</b>; viel → <b>mehr</b> → am <b>meisten</b>; gern → <b>lieber</b> → am <b>liebsten</b>; hoch → <b>höher</b>.</span>`,
w:[
["als","…den (karşılaştırma)","als","Mein Bruder ist älter als ich.","Abim benden büyük."],
["größer","daha büyük","grö:sır","Istanbul ist größer als Wien.","İstanbul Viyana'dan daha büyük."],
["kleiner","daha küçük","klaynır","Die Wohnung ist kleiner als unsere.","Daire bizimkinden daha küçük."],
["besser","daha iyi","besır","Heute geht es mir besser.","Bugün daha iyiyim."],
["am besten","en iyi","am bestın","Das gefällt mir am besten.","En çok bunu beğendim."],
["mehr","daha çok","me:r","Ich möchte mehr Deutsch sprechen.","Daha çok Almanca konuşmak istiyorum."],
["weniger","daha az","ve:nigır","Ich habe weniger Zeit als früher.","Eskisinden daha az vaktim var."],
["lieber","tercihen, daha çok","li:bır","Ich trinke lieber Tee.","Çayı tercih ederim."],
["älter","daha yaşlı / büyük","eltır","Sie ist zwei Jahre älter.","O iki yaş büyük."],
["jünger","daha genç","yüngır","Mein Bruder ist jünger als ich.","Kardeşim benden genç."],
["teurer","daha pahalı","toyrır","Wien ist teurer als Istanbul.","Viyana İstanbul'dan daha pahalı."],
["genauso","aynı şekilde, aynen","genauzo:","Das ist genauso gut.","Bu da aynı derecede iyi."]],
p:[
["Was ist besser, der Zug oder das Flugzeug?","Hangisi daha iyi, tren mi uçak mı?"],
["Das Leben in Wien ist teurer als in Istanbul.","Viyana'da yaşam İstanbul'dan pahalı."],
["Er spricht so gut Deutsch wie ein Muttersprachler.","Ana dili gibi Almanca konuşuyor."],
["Am liebsten esse ich türkisch.","En çok Türk yemeği yemeyi severim."],
["Je mehr ich übe, desto besser spreche ich.","Ne kadar çok pratik yaparsam o kadar iyi konuşuyorum."]]},

{t:"İş hayatı",s:"die Besprechung, der Kollege, das Projekt",
g:`<p>İş ortamında <b>Sie</b> varsayılandır. Birçok şirkette meslektaşlar <b>du</b>'ya geçer, ama genelde daha kıdemli olan önerir: <b>Wollen wir uns duzen?</b></p><div class="tw"><table><tr><th>Durum</th><th>Kalıp</th></tr><tr><td>E-posta açılışı (resmi)</td><td>Sehr geehrte Frau Weber, / Sehr geehrter Herr Kaya,</td></tr><tr><td>E-posta açılışı (yarı resmi)</td><td>Hallo Frau Weber, / Liebe Anna,</td></tr><tr><td>Kapanış</td><td>Mit freundlichen Grüßen / Viele Grüße</td></tr><tr><td>Ekte</td><td>Im Anhang finden Sie …</td></tr><tr><td>Geri dönüş</td><td>Ich melde mich bei Ihnen.</td></tr></table></div><span class="n">Almanlar iş yerinde dakikliğe çok önem verir: toplantıya 2–3 dakika erken gelmek normaldir. <b>Feierabend</b> = mesai bitişi; "Schönen Feierabend!" dersin.</span>`,
w:[
["die Besprechung","toplantı","di: beşpreşung","Die Besprechung beginnt um zehn.","Toplantı onda başlıyor."],
["der Kollege","iş arkadaşı (erkek)","de:r kole:ge","Mein Kollege ist im Urlaub.","İş arkadaşım izinde."],
["der Chef","patron, şef","de:r şef","Der Chef ist heute nicht da.","Şef bugün burada değil."],
["das Projekt","proje","das proyekt","Das Projekt dauert sechs Monate.","Proje altı ay sürüyor."],
["der Kunde","müşteri","de:r kunde","Am Dienstag bin ich beim Kunden.","Salı günü müşterideyim."],
["die Firma","şirket","di: firma","Ich arbeite bei einer IT-Firma.","Bir BT şirketinde çalışıyorum."],
["das Büro","ofis","das büro:","Heute arbeite ich im Büro.","Bugün ofiste çalışıyorum."],
["die Aufgabe","görev","di: aufga:be","Das ist eine wichtige Aufgabe.","Bu önemli bir görev."],
["der Feierabend","mesai bitişi","de:r fayıra:bınt","Schönen Feierabend!","İyi akşamlar (mesai sonrası)!"],
["der Urlaub","izin, tatil","de:r u:rlaup","Ich nehme nächste Woche Urlaub.","Gelecek hafta izin alıyorum."],
["das Homeoffice","evden çalışma","das ho:mofis","Montags bin ich im Homeoffice.","Pazartesileri evden çalışırım."],
["die Frist","son tarih","di: frist","Die Frist ist am Freitag.","Son tarih cuma."]],
p:[
["Können wir einen Termin für nächste Woche vereinbaren?","Gelecek hafta için bir toplantı ayarlayabilir miyiz?"],
["Ich melde mich morgen bei Ihnen.","Yarın size dönüş yapacağım."],
["Im Anhang finden Sie den Bericht.","Raporu ekte bulabilirsiniz."],
["Das System läuft wieder stabil.","Sistem yeniden stabil çalışıyor."],
["Mit freundlichen Grüßen","Saygılarımla"]]},

{t:"Boş zaman ve hobiler",s:"gern, lieber, am liebsten, spielen",
g:`<p>Sevdiğin şeyi söylemenin en doğal yolu fiil + <b>gern</b>:</p><div class="tw"><table><tr><th>Derece</th><th>Örnek</th><th>Anlam</th></tr><tr><td>gern</td><td>Ich lese <b>gern</b>.</td><td>Okumayı severim.</td></tr><tr><td>lieber</td><td>Ich lese <b>lieber</b> Romane.</td><td>Daha çok roman okumayı severim.</td></tr><tr><td>am liebsten</td><td>Ich reise <b>am liebsten</b>.</td><td>En çok seyahat etmeyi severim.</td></tr><tr><td>nicht gern</td><td>Ich koche <b>nicht gern</b>.</td><td>Yemek yapmayı sevmem.</td></tr></table></div><p>Spor ve müzik: Fußball <b>spielen</b>, Gitarre <b>spielen</b>, <b>schwimmen</b>, <b>joggen</b>, ins Fitnessstudio <b>gehen</b>, Sport <b>machen</b>.</p><span class="n">İlgi için: Ich <b>interessiere mich für</b> Geschichte = Tarihle ilgileniyorum. Hobi sormak: <b>Was machst du in deiner Freizeit?</b></span>`,
w:[
["die Freizeit","boş zaman","di: fraytsayt","Was machst du in deiner Freizeit?","Boş zamanında ne yaparsın?"],
["das Hobby","hobi","das hobi","Mein Hobby ist Fotografieren.","Hobim fotoğraf çekmek."],
["lesen","okumak","le:zın","Ich lese gern Krimis.","Polisiye okumayı severim."],
["reisen","seyahat etmek","rayzın","Wir reisen sehr gern.","Seyahat etmeyi çok severiz."],
["joggen","koşu yapmak","cogın","Ich jogge jeden Morgen.","Her sabah koşarım."],
["das Fitnessstudio","spor salonu","das fitnısştu:dio","Ich gehe dreimal pro Woche ins Fitnessstudio.","Haftada üç kez spor salonuna giderim."],
["wandern","doğa yürüyüşü yapmak","vandırn","In Österreich kann man gut wandern.","Avusturya'da güzel doğa yürüyüşü yapılır."],
["die Musik","müzik","di: muzi:k","Ich höre gern klassische Musik.","Klasik müzik dinlemeyi severim."],
["das Kino","sinema","das ki:no","Gehen wir heute ins Kino?","Bugün sinemaya gidelim mi?"],
["der Verein","kulüp, dernek","de:r ferayn","Er ist in einem Fußballverein.","Bir futbol kulübünde."],
["sich treffen","buluşmak","ziş trefın","Wir treffen uns am Samstag.","Cumartesi buluşuyoruz."],
["am liebsten","en çok severek","am li:pstın","Am liebsten reise ich.","En çok seyahat etmeyi severim."]],
p:[
["Was machst du gern in deiner Freizeit?","Boş zamanında ne yapmayı seversin?"],
["Ich gehe gern spazieren und lese viel.","Yürüyüş yapmayı severim, çok okurum."],
["Hast du Lust, am Wochenende wandern zu gehen?","Hafta sonu doğa yürüyüşüne gitmek ister misin?"],
["Ich interessiere mich für Technik.","Teknolojiyle ilgileniyorum."],
["Wollen wir uns heute Abend treffen?","Bu akşam buluşalım mı?"]]},

{t:"Telefon ve randevu",s:"Ich möchte … sprechen, zurückrufen, Termin",
g:`<p>Almanlar telefonu genelde <b>soyadıyla</b> açar: "Weber." ya da "Firma X, Kaya, guten Tag."</p><div class="tw"><table><tr><th>Durum</th><th>Kalıp</th></tr><tr><td>Biriyle görüşmek</td><td>Ich möchte gern Frau Weber sprechen.</td></tr><tr><td>Bağlatmak</td><td>Können Sie mich mit … verbinden?</td></tr><tr><td>Mesaj bırakmak</td><td>Kann ich eine Nachricht hinterlassen?</td></tr><tr><td>Geri aramak</td><td>Ich rufe Sie zurück.</td></tr><tr><td>Randevu almak</td><td>Ich hätte gern einen Termin.</td></tr><tr><td>Randevu iptal</td><td>Ich muss den Termin leider absagen.</td></tr><tr><td>Randevu ertelemek</td><td>Können wir den Termin verschieben?</td></tr></table></div><span class="n">Harfleri kodlarken Almanlar isim kullanır: A wie Anton, M wie Martha, K wie Kaufmann. Adını kodlamayı öğren: <b>M-A-H-S-U-N</b>.</span>`,
w:[
["telefonieren","telefonla konuşmak","telefoni:rın","Ich telefoniere gerade.","Şu an telefondayım."],
["zurückrufen","geri aramak","tsurükru:fın","Ich rufe Sie in zehn Minuten zurück.","Sizi on dakika sonra geri ararım."],
["verbinden","bağlamak","ferbindın","Ich verbinde Sie.","Sizi bağlıyorum."],
["die Nachricht","mesaj, haber","di: na:hrişt","Kann ich eine Nachricht hinterlassen?","Mesaj bırakabilir miyim?"],
["erreichen","ulaşmak","erayşın","Ich kann ihn nicht erreichen.","Ona ulaşamıyorum."],
["besetzt","meşgul","bezetst","Die Leitung ist besetzt.","Hat meşgul."],
["absagen","iptal etmek","apza:gın","Ich muss den Termin absagen.","Randevuyu iptal etmem gerekiyor."],
["verschieben","ertelemek","ferşi:bın","Können wir das auf Montag verschieben?","Bunu pazartesiye erteleyebilir miyiz?"],
["vereinbaren","kararlaştırmak","feraynba:rın","Wir vereinbaren einen Termin.","Bir randevu kararlaştırıyoruz."],
["passen","uygun olmak","pasın","Passt Ihnen Donnerstag?","Perşembe size uyar mı?"],
["buchstabieren","harf harf söylemek","bu:hştabi:rın","Können Sie das buchstabieren?","Bunu harf harf söyleyebilir misiniz?"],
["die Telefonnummer","telefon numarası","di: telefo:numır","Wie ist Ihre Telefonnummer?","Telefon numaranız nedir?"]],
p:[
["Guten Tag, hier spricht Mahsun Ak.","Merhaba, ben Mahsun Ak."],
["Ich möchte gern Herrn Becker sprechen.","Bay Becker ile görüşmek istiyorum."],
["Er ist gerade nicht am Platz.","Kendisi şu an yerinde değil."],
["Passt Ihnen Donnerstag um zehn?","Perşembe saat on size uyar mı?"],
["Können Sie bitte etwas lauter sprechen?","Biraz daha yüksek sesle konuşabilir misiniz?"]]},

{t:"Bağlaçlar: und, aber, oder, denn, sondern",s:"cümleleri bağlamak, fiil sırası",
g:`<p>Almancada bağlaçlar fiil sırasına göre üç gruba ayrılır. Hangi gruptan olduğunu bilmek, cümleyi doğru kurmanın anahtarıdır.</p><div class="tw"><table><tr><th>Grup</th><th>Bağlaçlar</th><th>Fiil nerede?</th><th>Örnek</th></tr><tr><td>Sıra 0</td><td>und, aber, oder, denn, sondern</td><td>değişmez (2. sırada)</td><td>…, <b>aber</b> ich <b>habe</b> keine Zeit.</td></tr><tr><td>Zarf bağlaçlar</td><td>deshalb, trotzdem, dann, sonst, außerdem</td><td>hemen ardından</td><td>…, <b>deshalb bleibe</b> ich hier.</td></tr><tr><td>Yan cümle</td><td>weil, dass, wenn, ob, obwohl, als</td><td>en sonda</td><td>…, <b>weil</b> ich müde <b>bin</b>.</td></tr></table></div><p>Aynı anlam, üç yapı: Ich bleibe zu Hause, <b>denn</b> ich <b>bin</b> krank. / Ich bin krank, <b>deshalb bleibe</b> ich zu Hause. / Ich bleibe zu Hause, <b>weil</b> ich krank <b>bin</b>.</p><span class="n">Sıra 0 bağlaçlarını <b>ADUSO</b> diye ezberle: <b>A</b>ber, <b>D</b>enn, <b>U</b>nd, <b>S</b>ondern, <b>O</b>der. Bunlar fiil sırasını hiç bozmaz. Tüm bağlaçların listesi Hazine'de "Bağlaçlar" kategorisinde.</span>`,
w:[
["und","ve","unt","Ich trinke Kaffee und sie trinkt Tee.","Ben kahve içiyorum, o da çay."],
["aber","ama","a:bır","Ich möchte kommen, aber ich habe keine Zeit.","Gelmek istiyorum ama vaktim yok."],
["oder","veya, ya da","o:dır","Kommst du heute oder morgen?","Bugün mü geliyorsun yarın mı?"],
["denn","çünkü (fiil 2. sırada)","den","Ich bleibe hier, denn es regnet.","Burada kalıyorum, çünkü yağmur yağıyor."],
["sondern","(değil) … bilakis","zondırn","Das ist nicht billig, sondern teuer.","Bu ucuz değil, pahalı."],
["deshalb","bu yüzden","deshalp","Ich bin müde, deshalb gehe ich schlafen.","Yorgunum, bu yüzden yatmaya gidiyorum."],
["trotzdem","yine de","trotsde:m","Es regnet, trotzdem gehen wir spazieren.","Yağmur yağıyor, yine de yürüyüşe çıkıyoruz."],
["dann","sonra / o zaman","dan","Zuerst esse ich, dann arbeite ich.","Önce yerim, sonra çalışırım."],
["sonst","yoksa","zonst","Beeil dich, sonst kommst du zu spät.","Acele et, yoksa geç kalacaksın."],
["außerdem","ayrıca","ausırde:m","Die Wohnung ist groß, außerdem ist sie billig.","Daire büyük, ayrıca ucuz."],
["auch","de / da, ayrıca","auh","Ich spreche auch Englisch.","İngilizce de konuşuyorum."],
["nicht nur … sondern auch","sadece … değil … de","nişt nu:r … zondırn auh","Er spricht nicht nur Deutsch, sondern auch Italienisch.","Sadece Almanca değil, İtalyanca da konuşuyor."]],
p:[
["Ich arbeite viel, aber ich mache auch Sport.","Çok çalışıyorum ama spor da yapıyorum."],
["Möchtest du Tee oder Kaffee?","Çay mı istersin kahve mi?"],
["Das ist nicht mein Handy, sondern deins.","Bu benim telefonum değil, seninki."],
["Ich habe Hunger, deshalb koche ich jetzt.","Acıktım, bu yüzden şimdi yemek yapıyorum."],
["Ich komme heute nicht, denn ich muss arbeiten.","Bugün gelmiyorum, çünkü çalışmam lazım."]]},

{t:"Dönüşlü fiiller",s:"sich freuen, sich interessieren für",
g:`<p>Dönüşlü fiiller kişiye göre değişen bir zamir alır (<b>sich</b>):</p><div class="tw"><table><tr><th>Kişi</th><th>Zamir</th><th>Örnek</th></tr><tr><td>ich</td><td>mich</td><td>Ich freue <b>mich</b>.</td></tr><tr><td>du</td><td>dich</td><td>Du freust <b>dich</b>.</td></tr><tr><td>er / sie</td><td>sich</td><td>Sie freut <b>sich</b>.</td></tr><tr><td>wir</td><td>uns</td><td>Wir freuen <b>uns</b>.</td></tr><tr><td>ihr</td><td>euch</td><td>Ihr freut <b>euch</b>.</td></tr><tr><td>sie / Sie</td><td>sich</td><td>Sie freuen <b>sich</b>.</td></tr></table></div><p>Çoğu dönüşlü fiil sabit bir edatla gelir: sich freuen <b>auf</b> (gelecekteki bir şeyi sabırsızlıkla beklemek), sich freuen <b>über</b> (bir şeye sevinmek), sich interessieren <b>für</b>, sich erinnern <b>an</b>, sich kümmern <b>um</b>.</p><span class="n">Edatlı fiilleri tek kelime gibi öğren: <b>sich freuen auf</b>. Soru için wo(r) + edat: <b>Worauf</b> freust du dich?</span>`,
w:[
["sich freuen","sevinmek","ziş froyın","Ich freue mich auf den Urlaub.","Tatili dört gözle bekliyorum."],
["sich interessieren","ilgilenmek","ziş intıresi:rın","Ich interessiere mich für Geschichte.","Tarihle ilgileniyorum."],
["sich erinnern","hatırlamak","ziş erinırn","Ich erinnere mich nicht an seinen Namen.","Adını hatırlamıyorum."],
["sich kümmern","ilgilenmek, bakmak","ziş kümırn","Ich kümmere mich um das Problem.","Sorunla ben ilgileniyorum."],
["sich setzen","oturmak","ziş zetsın","Setzen Sie sich bitte.","Lütfen oturun."],
["sich beeilen","acele etmek","ziş bea:ylın","Beeil dich, der Zug fährt gleich!","Acele et, tren birazdan kalkıyor!"],
["sich ausruhen","dinlenmek","ziş ausru:ın","Am Sonntag ruhe ich mich aus.","Pazar günü dinlenirim."],
["sich anziehen","giyinmek","ziş antsi:ın","Ich ziehe mich schnell an.","Hızlıca giyiniyorum."],
["sich vorstellen","kendini tanıtmak","ziş fo:rştelın","Darf ich mich vorstellen?","Kendimi tanıtabilir miyim?"],
["sich fühlen","hissetmek","ziş fü:lın","Ich fühle mich heute gut.","Bugün kendimi iyi hissediyorum."],
["sich gewöhnen","alışmak","ziş gevö:nın","Ich gewöhne mich an das Wetter.","Havaya alışıyorum."],
["sich entschuldigen","özür dilemek","ziş entşuldigın","Ich möchte mich entschuldigen.","Özür dilemek istiyorum."]],
p:[
["Ich freue mich auf das Wochenende.","Hafta sonunu dört gözle bekliyorum."],
["Freut mich, dass es dir gefällt!","Beğenmene sevindim!"],
["Erinnerst du dich an mich?","Beni hatırlıyor musun?"],
["Wir müssen uns beeilen.","Acele etmemiz lazım."],
["Ich kann mich nicht entscheiden.","Karar veremiyorum."]]}
]});

LV.push({id:"B1",name:"Orta",units:[
{t:"Yan cümleler",s:"weil, dass, wenn, ob — fiil sona",
g:`<p>Yan cümlede <b>çekimli fiil en sona</b> gider. Bu, Almancanın en önemli kuralıdır.</p><div class="tw"><table><tr><th>Bağlaç</th><th>Anlam</th><th>Örnek</th></tr><tr><td>weil</td><td>çünkü</td><td>…, weil ich müde <b>bin</b>.</td></tr><tr><td>dass</td><td>-dığını, ki</td><td>Ich glaube, dass er recht <b>hat</b>.</td></tr><tr><td>wenn</td><td>-ince, eğer</td><td>Wenn ich Zeit <b>habe</b>, …</td></tr><tr><td>ob</td><td>-ip -mediğini</td><td>Ich weiß nicht, ob sie <b>kommt</b>.</td></tr><tr><td>obwohl</td><td>-e rağmen</td><td>…, obwohl es <b>regnet</b>.</td></tr></table></div><p>Yan cümle başa gelirse ana cümle fiille başlar: <b>Wenn</b> ich Zeit habe, <b>komme</b> ich. (fiil-virgül-fiil)</p><span class="n">Perfekt'te yardımcı fiil sona gider: …, weil ich lange <b>gearbeitet habe</b>. Ayrılabilen fiil yan cümlede birleşir: …, wenn der Zug <b>ankommt</b>.</span>`,
w:[
["weil","çünkü","vayl","Ich bleibe zu Hause, weil ich krank bin.","Evde kalıyorum çünkü hastayım."],
["dass","-dığını, ki","das","Ich weiß, dass das schwierig ist.","Bunun zor olduğunu biliyorum."],
["wenn","-ince / eğer","ven","Wenn ich Zeit habe, rufe ich dich an.","Vaktim olunca seni ararım."],
["ob","-ip -mediğini","op","Ich weiß nicht, ob er kommt.","Gelip gelmeyeceğini bilmiyorum."],
["obwohl","-e rağmen","opvo:l","Ich gehe joggen, obwohl es regnet.","Yağmur yağmasına rağmen koşuya çıkıyorum."],
["glauben","inanmak, sanmak","glaubın","Ich glaube, dass du recht hast.","Bence haklısın."],
["wissen","bilmek","visın","Weißt du, wann der Kurs beginnt?","Kursun ne zaman başladığını biliyor musun?"],
["hoffen","ummak","hofın","Ich hoffe, dass es klappt.","Umarım olur."],
["sicher","emin / kesin","ziher","Ich bin sicher, dass er kommt.","Geleceğinden eminim."],
["denn","çünkü (fiil 2. sırada)","den","Ich komme nicht, denn ich bin müde.","Gelmiyorum, çünkü yorgunum."],
["deshalb","bu yüzden","deshalp","Es regnet, deshalb bleibe ich hier.","Yağmur yağıyor, bu yüzden burada kalıyorum."],
["trotzdem","yine de","trotsde:m","Es ist kalt, trotzdem gehen wir raus.","Hava soğuk, yine de dışarı çıkıyoruz."]],
p:[
["Ich lerne Deutsch, weil ich in Wien arbeiten möchte.","Almanca öğreniyorum çünkü Viyana'da çalışmak istiyorum."],
["Weißt du, ob das Geschäft heute offen ist?","Dükkânın bugün açık olup olmadığını biliyor musun?"],
["Wenn du Fragen hast, schreib mir einfach.","Sorun olursa bana yazman yeterli."],
["Ich finde es gut, dass wir darüber sprechen.","Bunu konuşmamızı iyi buluyorum."],
["Obwohl ich müde war, habe ich weitergearbeitet.","Yorgun olmama rağmen çalışmaya devam ettim."]]},

{t:"Hikâye anlatmak",s:"als, wenn, nachdem, bevor, während",
g:`<p>Bir olayı anlatırken zaman bağlaçları kullanılır (hepsi fiili sona atar):</p><div class="tw"><table><tr><th>Bağlaç</th><th>Anlam</th><th>Kullanım</th></tr><tr><td>als</td><td>-dığında</td><td>geçmişte <b>tek seferlik</b> olay</td></tr><tr><td>wenn</td><td>-dığında / her …-dığında</td><td>tekrar eden olay, şimdi/gelecek</td></tr><tr><td>während</td><td>-iken</td><td>aynı anda</td></tr><tr><td>bevor</td><td>-meden önce</td><td>önce</td></tr><tr><td>nachdem</td><td>-dikten sonra</td><td>sonra (Plusquamperfekt ile)</td></tr><tr><td>seitdem</td><td>-den beri</td><td>başlangıç</td></tr></table></div><p><b>Plusquamperfekt</b> = hatte/war + Partizip: Nachdem ich gegessen <b>hatte</b>, bin ich losgegangen.</p><span class="n">Hikâye akışı için: <b>zuerst</b> (önce), <b>dann</b> (sonra), <b>danach</b> (ondan sonra), <b>plötzlich</b> (aniden), <b>schließlich / am Ende</b> (sonunda).</span>`,
w:[
["als","-dığında (geçmiş, tek sefer)","als","Als ich in Wien war, hat es geschneit.","Viyana'dayken kar yağdı."],
["während","-iken","ve:rınt","Während ich koche, hört er Musik.","Ben yemek yaparken o müzik dinliyor."],
["bevor","-meden önce","befo:r","Bevor ich schlafe, lese ich.","Uyumadan önce okurum."],
["nachdem","-dikten sonra","na:hde:m","Nachdem er angekommen war, rief er an.","Vardıktan sonra aradı."],
["seitdem","-den beri","zaytde:m","Seitdem ich jogge, fühle ich mich besser.","Koşmaya başladığımdan beri daha iyi hissediyorum."],
["plötzlich","aniden","plötsliş","Plötzlich ging das Licht aus.","Aniden ışık söndü."],
["zuerst","önce","tsu:e:rst","Zuerst waren wir im Museum.","Önce müzedeydik."],
["schließlich","sonunda","şli:sliş","Schließlich haben wir das Hotel gefunden.","Sonunda oteli bulduk."],
["die Geschichte","hikâye / tarih","di: geşişte","Das ist eine lustige Geschichte.","Bu komik bir hikâye."],
["erzählen","anlatmak","ertse:lın","Erzähl mal, wie war der Urlaub?","Anlat bakalım, tatil nasıldı?"],
["passieren","olmak, yaşanmak","pasi:rın","Mir ist etwas Komisches passiert.","Başıma garip bir şey geldi."],
["erleben","yaşamak, deneyimlemek","erle:bın","Wir haben viel erlebt.","Çok şey yaşadık."]],
p:[
["Als ich klein war, wohnten wir am Meer.","Küçükken deniz kenarında oturuyorduk."],
["Weißt du, was mir gestern passiert ist?","Dün başıma ne geldi biliyor musun?"],
["Plötzlich hat mein Handy nicht mehr funktioniert.","Birden telefonum çalışmaz oldu."],
["Nachdem wir gegessen hatten, sind wir spazieren gegangen.","Yemek yedikten sonra yürüyüşe çıktık."],
["Am Ende war alles gut.","Sonunda her şey yoluna girdi."]]},

{t:"Gelecek zaman",s:"werden + Infinitiv",
g:`<p><b>Futur I</b> = <b>werden</b> (çekimli) + mastar (sonda). Plan, tahmin ve söz için kullanılır.</p><div class="tw"><table><tr><th>Kişi</th><th>werden</th><th>Örnek</th></tr><tr><td>ich</td><td>werde</td><td>Ich <b>werde</b> dich <b>anrufen</b>.</td></tr><tr><td>du</td><td>wirst</td><td>Du <b>wirst</b> das <b>schaffen</b>.</td></tr><tr><td>er / sie</td><td>wird</td><td>Es <b>wird</b> morgen <b>regnen</b>.</td></tr><tr><td>wir / sie / Sie</td><td>werden</td><td>Wir <b>werden</b> <b>umziehen</b>.</td></tr><tr><td>ihr</td><td>werdet</td><td>Ihr <b>werdet</b> <b>sehen</b>.</td></tr></table></div><p>Günlük konuşmada zaman belirteci varsa şimdiki zaman yeterlidir: <b>Nächstes Jahr ziehen wir um.</b></p><span class="n"><b>werden</b> tek başına "olmak (dönüşmek)" demektir: Ich <b>werde</b> Vater = Baba oluyorum. Es <b>wird</b> kalt = Hava soğuyor.</span>`,
w:[
["werden","olmak / -ecek","ve:rdın","Ich werde dich vermissen.","Seni özleyeceğim."],
["schaffen","başarmak","şafın","Du wirst das schaffen!","Bunu başaracaksın!"],
["planen","planlamak","pla:nın","Wir planen eine Reise.","Bir seyahat planlıyoruz."],
["vorhaben","niyetinde olmak","fo:rha:bın","Was hast du morgen vor?","Yarın ne yapmayı düşünüyorsun?"],
["die Zukunft","gelecek","di: tsu:kunft","In der Zukunft möchte ich selbstständig arbeiten.","Gelecekte serbest çalışmak istiyorum."],
["bald","yakında","balt","Wir sehen uns bald.","Yakında görüşürüz."],
["nächste","gelecek, bir sonraki","ne:kste","Nächste Woche habe ich Urlaub.","Gelecek hafta iznim var."],
["später","daha sonra","şpe:tır","Ich mache das später.","Bunu sonra yaparım."],
["wahrscheinlich","muhtemelen","va:rşaynliş","Es wird wahrscheinlich regnen.","Muhtemelen yağmur yağacak."],
["versprechen","söz vermek","ferşpreşın","Ich verspreche dir, ich komme.","Sana söz veriyorum, geleceğim."],
["umziehen","taşınmak","umtsi:ın","Wir werden nach Wien umziehen.","Viyana'ya taşınacağız."],
["der Plan","plan","de:r pla:n","Hast du schon einen Plan?","Bir planın var mı şimdiden?"]],
p:[
["Was hast du am Wochenende vor?","Hafta sonu ne yapmayı planlıyorsun?"],
["Ich werde nächstes Jahr selbstständig arbeiten.","Gelecek yıl serbest çalışacağım."],
["Es wird bestimmt klappen.","Kesin olacak."],
["Wir werden sehen.","Göreceğiz."],
["Ich werde mein Bestes geben.","Elimden geleni yapacağım."]]},

{t:"Kibar dil: Konjunktiv II",s:"ich würde, könnten Sie, ich hätte gern",
g:`<p><b>Konjunktiv II</b> kibarlık, istek, tavsiye ve hayal için kullanılır. Çoğu fiilde <b>würde + mastar</b> yeterlidir.</p><div class="tw"><table><tr><th>Normal</th><th>Konjunktiv II</th><th>Anlam</th></tr><tr><td>ich bin</td><td>ich <b>wäre</b></td><td>olurdum</td></tr><tr><td>ich habe</td><td>ich <b>hätte</b></td><td>olurdu (sahip)</td></tr><tr><td>ich kann</td><td>ich <b>könnte</b></td><td>-ebilirdim</td></tr><tr><td>ich muss</td><td>ich <b>müsste</b></td><td>-mem gerekirdi</td></tr><tr><td>ich soll</td><td>ich <b>sollte</b></td><td>-meliyim (tavsiye)</td></tr><tr><td>ich mache</td><td>ich <b>würde</b> machen</td><td>yapardım</td></tr></table></div><p>Kibar rica: <b>Könnten Sie</b> mir helfen? <b>Würden Sie</b> bitte das Fenster schließen? Tavsiye: Du <b>solltest</b> mehr schlafen.</p><span class="n">Sipariş ve istekte <b>Ich hätte gern …</b> ve <b>Ich würde gern …</b> en doğal kalıplardır.</span>`,
w:[
["würde","-erdi (yardımcı)","vürde","Ich würde gern mitkommen.","Seve seve gelirdim."],
["wäre","olurdu","ve:re","Das wäre super!","Bu süper olurdu!"],
["hätte","olurdu (sahip olmak)","hete","Ich hätte gern ein Glas Wasser.","Bir bardak su alabilir miyim."],
["könnte","-ebilirdi","könte","Könnten Sie mir bitte helfen?","Bana yardım edebilir miydiniz?"],
["sollte","-meli (tavsiye)","zolte","Du solltest zum Arzt gehen.","Doktora gitmelisin."],
["müsste","-mesi gerekirdi","müste","Das müsste funktionieren.","Bunun çalışması gerekir."],
["gern","memnuniyetle","gern","Ich würde gern in Wien leben.","Viyana'da yaşamayı isterdim."],
["der Vorschlag","öneri","de:r fo:rşla:k","Ich habe einen Vorschlag.","Bir önerim var."],
["vorschlagen","önermek","fo:rşla:gın","Ich würde vorschlagen, dass wir morgen anfangen.","Yarın başlamamızı önerirdim."],
["die Bitte","rica","di: bite","Ich hätte eine Bitte.","Bir ricam olacaktı."],
["eventuell","belki, olası","eventuel","Könnten wir eventuell früher anfangen?","Belki daha erken başlayabilir miyiz?"],
["lieber","daha iyi (tercih)","li:bır","Ich würde lieber zu Hause bleiben.","Evde kalmayı tercih ederdim."]],
p:[
["Könnten Sie das bitte noch einmal erklären?","Bunu bir kez daha açıklayabilir miydiniz?"],
["Ich hätte eine Frage zu Ihrem Angebot.","Teklifinizle ilgili bir sorum olacaktı."],
["Würden Sie mir bitte die Unterlagen schicken?","Belgeleri bana gönderebilir miydiniz?"],
["An deiner Stelle würde ich das nicht machen.","Senin yerinde olsam bunu yapmazdım."],
["Es wäre schön, wenn wir uns bald sehen könnten.","Yakında görüşebilsek güzel olurdu."]]},

{t:"Koşul cümleleri",s:"wenn ich Zeit hätte, würde ich …",
g:`<div class="tw"><table><tr><th>Tür</th><th>Wenn + …</th><th>Ana cümle</th><th>Anlam</th></tr><tr><td>Gerçek</td><td>Präsens</td><td>Präsens / Futur</td><td>Wenn ich Zeit <b>habe</b>, <b>komme</b> ich.</td></tr><tr><td>Hayalî (şimdi)</td><td>Konjunktiv II</td><td>würde / wäre / hätte</td><td>Wenn ich Zeit <b>hätte</b>, <b>würde</b> ich <b>kommen</b>.</td></tr><tr><td>Hayalî (geçmiş)</td><td>hätte/wäre + Partizip</td><td>hätte/wäre + Partizip</td><td>Wenn ich Zeit <b>gehabt hätte</b>, <b>wäre</b> ich <b>gekommen</b>.</td></tr></table></div><p>Dilek için <b>Wenn … nur</b> ya da <b>Ich wünschte</b>: <b>Wenn</b> ich <b>nur</b> mehr Zeit hätte! = Keşke daha çok vaktim olsa!</p><span class="n"><b>wenn</b> başa gelince virgülden sonra fiil gelir: Wenn ich reich wäre, <b>würde</b> ich reisen. "falls" da kullanılır: <b>Falls</b> du Hilfe brauchst = Yardıma ihtiyacın olursa.</span>`,
w:[
["falls","olur da, eğer","fals","Falls du Hilfe brauchst, ruf mich an.","Yardıma ihtiyacın olursa beni ara."],
["sonst","yoksa, aksi hâlde","zonst","Beeil dich, sonst verpassen wir den Zug.","Acele et, yoksa treni kaçıracağız."],
["reich","zengin","rayş","Wenn ich reich wäre, würde ich viel reisen.","Zengin olsaydım çok seyahat ederdim."],
["wünschen","dilemek","vünşın","Ich wünschte, ich könnte besser Deutsch.","Keşke Almancam daha iyi olsa."],
["der Wunsch","dilek","de:r vunş","Hast du einen Wunsch?","Bir dileğin var mı?"],
["die Möglichkeit","imkân","di: mö:klişkayt","Wenn ich die Möglichkeit hätte, würde ich im Ausland arbeiten.","İmkânım olsa yurtdışında çalışırdım."],
["im Ausland","yurtdışında","im auslant","Sie hat lange im Ausland gelebt.","Uzun süre yurtdışında yaşadı."],
["entscheiden","karar vermek","entşaydın","Wenn ich entscheiden könnte, würde ich bleiben.","Karar verebilseydim kalırdım."],
["gewinnen","kazanmak","gevinın","Wenn ich im Lotto gewinnen würde, …","Lotodan kazansaydım, …"],
["an deiner Stelle","senin yerinde","an daynır ştele","An deiner Stelle würde ich fragen.","Senin yerinde olsam sorardım."],
["die Bedingung","koşul","di: bedingung","Unter einer Bedingung.","Bir şartla."],
["egal","fark etmez","ega:l","Das ist mir egal.","Benim için fark etmez."]],
p:[
["Wenn ich mehr Zeit hätte, würde ich öfter Sport machen.","Daha çok vaktim olsa daha sık spor yapardım."],
["Was würdest du machen, wenn du im Lotto gewinnen würdest?","Lotodan kazansan ne yapardın?"],
["Wenn ich das gewusst hätte, wäre ich früher gekommen.","Bunu bilseydim daha erken gelirdim."],
["Falls es regnet, bleiben wir zu Hause.","Yağmur yağarsa evde kalırız."],
["Wenn ich nur besser schlafen könnte!","Keşke daha iyi uyuyabilsem!"]]},

{t:"Fikir bildirmek",s:"meiner Meinung nach, ich finde, einerseits …",
g:`<p>Fikir söylemek ve tartışmak için kalıplar konuşmanı B1 seviyesine taşır:</p><div class="tw"><table><tr><th>İşlev</th><th>Kalıp</th></tr><tr><td>Fikir</td><td>Ich finde / glaube / denke, dass … · Meiner Meinung nach …</td></tr><tr><td>Katılmak</td><td>Da hast du recht. · Das sehe ich genauso.</td></tr><tr><td>Katılmamak</td><td>Da bin ich anderer Meinung. · Das sehe ich anders.</td></tr><tr><td>Kısmen</td><td>Ja, schon, aber … · Das stimmt teilweise.</td></tr><tr><td>Karşılaştırma</td><td>Einerseits …, andererseits …</td></tr><tr><td>Örnek</td><td>zum Beispiel · Ich denke da an …</td></tr><tr><td>Sonuç</td><td>Alles in allem … · Zusammenfassend …</td></tr></table></div><span class="n"><b>Meiner Meinung nach</b>'tan sonra fiil hemen gelir: Meiner Meinung nach <b>ist</b> das richtig. <b>Ich finde, dass</b>'ten sonra fiil sona gider.</span>`,
w:[
["die Meinung","fikir, görüş","di: maynung","Was ist deine Meinung?","Senin fikrin ne?"],
["meiner Meinung nach","bence","maynır maynung na:h","Meiner Meinung nach ist das zu teuer.","Bence bu çok pahalı."],
["finden","bulmak / düşünmek","findın","Ich finde die Idee gut.","Fikri iyi buluyorum."],
["recht haben","haklı olmak","reşt ha:bın","Da hast du recht.","Orada haklısın."],
["einerseits","bir yandan","aynırzayts","Einerseits ist Wien teuer, andererseits ist es sicher.","Bir yandan Viyana pahalı, diğer yandan güvenli."],
["andererseits","öte yandan","andırırzayts","Andererseits gibt es viele Vorteile.","Öte yandan birçok avantajı var."],
["der Vorteil","avantaj","de:r fo:rtayl","Das hat viele Vorteile.","Bunun birçok avantajı var."],
["der Nachteil","dezavantaj","de:r na:htayl","Der Nachteil ist der Preis.","Dezavantajı fiyat."],
["überzeugen","ikna etmek","ü:bırtsoygın","Das Argument überzeugt mich nicht.","Bu argüman beni ikna etmiyor."],
["zustimmen","katılmak","tsu:ştimın","Da stimme ich dir zu.","Bu konuda sana katılıyorum."],
["allerdings","ancak, gerçi","alırdings","Das stimmt, allerdings ist es kompliziert.","Doğru, ancak karmaşık."],
["eigentlich","aslında","aygıntliş","Eigentlich hast du recht.","Aslında haklısın."]],
p:[
["Meiner Meinung nach sollten wir mehr Zeit einplanen.","Bence daha fazla zaman ayırmalıyız."],
["Das sehe ich anders.","Ben bunu farklı görüyorum."],
["Einerseits verstehe ich dich, andererseits finde ich das riskant.","Bir yandan seni anlıyorum, öte yandan bunu riskli buluyorum."],
["Da hast du völlig recht.","Bu konuda tamamen haklısın."],
["Alles in allem ist das eine gute Lösung.","Sonuç olarak bu iyi bir çözüm."]]},

{t:"İlgi zamirleri",s:"der, die, das, in dem, mit dem",
g:`<p>İki cümleyi birleştirip bir ismi tanımlarken kullanılır (Türkçedeki -an, -dığı). İlgi zamiri isme göre seçilir, <b>fiil sona</b> gider.</p><div class="tw"><table><tr><th></th><th>Özne</th><th>Akkusativ</th><th>Dativ</th></tr><tr><td>Eril</td><td>der</td><td>den</td><td>dem</td></tr><tr><td>Dişil</td><td>die</td><td>die</td><td>der</td></tr><tr><td>Nötr</td><td>das</td><td>das</td><td>dem</td></tr><tr><td>Çoğul</td><td>die</td><td>die</td><td>denen</td></tr></table></div><p>Örnekler: der Mann, <b>der</b> dort steht (orada duran adam) · der Film, <b>den</b> ich gesehen habe (gördüğüm film) · die Kollegin, <b>mit der</b> ich arbeite (birlikte çalıştığım meslektaş).</p><span class="n">Yer için <b>wo</b> da kullanılır: die Stadt, <b>wo</b> ich wohne = oturduğum şehir. "Her şey" ve "bir şey"den sonra <b>was</b>: alles, <b>was</b> ich weiß.</span>`,
w:[
["der","ki o (eril ilgi)","de:r","Das ist der Kollege, der mir geholfen hat.","Bu bana yardım eden meslektaş."],
["den","ki onu (eril)","de:n","Der Film, den ich gesehen habe, war gut.","İzlediğim film iyiydi."],
["dem","ki ona (eril/nötr)","de:m","Das ist der Freund, dem ich das Buch gegeben habe.","Bu kitabı verdiğim arkadaş."],
["denen","ki onlara","de:nın","Die Leute, mit denen ich arbeite, sind nett.","Birlikte çalıştığım insanlar iyi."],
["was","ki (alles, etwas sonrası)","vas","Das ist alles, was ich weiß.","Bildiğim her şey bu."],
["wo","ki orada","vo:","Die Stadt, wo ich wohne, ist schön.","Oturduğum şehir güzel."],
["der Grund","sebep","de:r grunt","Das ist der Grund, warum ich lerne.","Öğrenmemin sebebi bu."],
["empfehlen","tavsiye etmek","empfe:lın","Das Restaurant, das du empfohlen hast, war super.","Tavsiye ettiğin restoran süperdi."],
["kennenlernen","tanışmak","kenınlernın","Die Frau, die ich kennengelernt habe, ist Ärztin.","Tanıştığım kadın doktor."],
["sich verlassen auf","güvenmek","ziş ferlasın auf","Er ist jemand, auf den man sich verlassen kann.","Güvenilebilecek biri."],
["der Ort","yer","de:r ort","Das ist ein Ort, an dem ich mich wohlfühle.","Burası kendimi iyi hissettiğim bir yer."],
["jemand","biri","ye:mant","Ich suche jemanden, der Deutsch spricht.","Almanca konuşan birini arıyorum."]],
p:[
["Das ist das Restaurant, von dem ich dir erzählt habe.","Sana bahsettiğim restoran bu."],
["Kennst du jemanden, der eine Wohnung vermietet?","Daire kiraya veren birini tanıyor musun?"],
["Das ist genau das, was ich gesucht habe.","Tam aradığım şey bu."],
["Die Kollegen, mit denen ich arbeite, sind sehr hilfsbereit.","Birlikte çalıştığım meslektaşlar çok yardımsever."],
["Es gibt vieles, was ich noch lernen muss.","Daha öğrenmem gereken çok şey var."]]},

{t:"Duygular ve ilişkiler",s:"sich ärgern über, sich verstehen mit",
g:`<p>Duygu ifadesi üç yolla kurulur:</p><div class="tw"><table><tr><th>Yapı</th><th>Örnek</th></tr><tr><td>sein + sıfat</td><td>Ich bin <b>froh / traurig / enttäuscht</b>.</td></tr><tr><td>dönüşlü fiil + edat</td><td>Ich <b>ärgere mich über</b> den Stau. · Ich <b>freue mich über</b> das Geschenk.</td></tr><tr><td>Dativ yapısı</td><td><b>Mir</b> ist langweilig. · Das tut <b>mir</b> leid. · Das ist <b>mir</b> peinlich.</td></tr></table></div><p>İlişkiler: sich <b>verstehen mit</b> (iyi anlaşmak), sich <b>streiten mit</b> (kavga etmek), sich <b>verlieben in</b> (âşık olmak), sich <b>trennen von</b> (ayrılmak).</p><span class="n"><b>Das tut mir leid</b> hem "üzgünüm" hem "özür dilerim" anlamında kullanılır. Daha güçlü özür: <b>Es tut mir wirklich leid.</b></span>`,
w:[
["froh","memnun, mutlu","fro:","Ich bin froh, dass du da bist.","Burada olduğuna sevindim."],
["traurig","üzgün","trauriş","Sie ist traurig, weil ihr Hund krank ist.","Köpeği hasta olduğu için üzgün."],
["enttäuscht","hayal kırıklığına uğramış","enttoyşt","Ich bin ein bisschen enttäuscht.","Biraz hayal kırıklığına uğradım."],
["sich ärgern","sinirlenmek","ziş ergırn","Ich ärgere mich über den Stau.","Trafiğe sinir oluyorum."],
["leidtun","üzgün olmak","layttu:n","Es tut mir leid.","Üzgünüm / Özür dilerim."],
["sich verstehen","anlaşmak","ziş ferşte:ın","Ich verstehe mich gut mit meinen Kollegen.","Meslektaşlarımla iyi anlaşıyorum."],
["sich streiten","kavga etmek","ziş ştraytın","Sie streiten sich oft.","Sık sık tartışırlar."],
["sich verlieben","âşık olmak","ziş ferli:bın","Er hat sich in sie verliebt.","Ona âşık oldu."],
["die Beziehung","ilişki","di: betsi:ung","Wir haben eine gute Beziehung.","İyi bir ilişkimiz var."],
["vermissen","özlemek","fermisın","Ich vermisse meine Familie.","Ailemi özlüyorum."],
["stolz","gururlu","ştolts","Ich bin stolz auf dich.","Seninle gurur duyuyorum."],
["die Laune","ruh hâli, keyif","di: laune","Er hat heute gute Laune.","Bugün keyfi yerinde."]],
p:[
["Das tut mir wirklich leid.","Gerçekten çok üzgünüm."],
["Ich freue mich sehr für dich!","Senin adına çok sevindim!"],
["Mach dir keine Sorgen.","Endişelenme."],
["Das ärgert mich total.","Bu beni çok sinirlendiriyor."],
["Wir verstehen uns sehr gut.","Çok iyi anlaşıyoruz."]]},

{t:"Haberler ve medya",s:"laut, angeblich, die Nachrichten",
g:`<p>Duyduğun ya da okuduğun bilgiyi aktarırken:</p><div class="tw"><table><tr><th>Kalıp</th><th>Anlam</th></tr><tr><td>Laut der Zeitung …</td><td>Gazeteye göre …</td></tr><tr><td>In den Nachrichten hieß es, dass …</td><td>Haberlerde … dendi</td></tr><tr><td>Angeblich …</td><td>Söylendiğine göre …</td></tr><tr><td>Ich habe gelesen, dass …</td><td>…dığını okudum</td></tr><tr><td>Es heißt, dass …</td><td>…dığı söyleniyor</td></tr><tr><td>Er soll … haben</td><td>…dığı iddia ediliyor</td></tr></table></div><p>Medya kelimeleri: die Nachrichten (haberler), die Zeitung (gazete), der Artikel (makale), die Sendung (program), die Schlagzeile (manşet).</p><span class="n"><b>sollen</b> haber dilinde "iddiaya göre" anlamı taşır: Der Minister <b>soll</b> zurücktreten = Bakanın istifa edeceği söyleniyor.</span>`,
w:[
["die Nachrichten","haberler","di: na:hriştın","Hast du die Nachrichten gesehen?","Haberleri izledin mi?"],
["die Zeitung","gazete","di: tsaytung","Ich lese die Zeitung online.","Gazeteyi internetten okuyorum."],
["der Artikel","makale / artikel","de:r artikıl","Ich habe einen interessanten Artikel gelesen.","İlginç bir makale okudum."],
["laut","…e göre / yüksek sesli","laut","Laut der Studie schlafen wir zu wenig.","Araştırmaya göre çok az uyuyoruz."],
["angeblich","söylendiğine göre","angeypliş","Angeblich wird das Benzin teurer.","Söylentiye göre benzine zam gelecek."],
["berichten","haber vermek","berişın","Die Medien berichten über den Streik.","Medya grevi haberleştiriyor."],
["die Sendung","program (TV/radyo)","di: zendung","Die Sendung beginnt um acht.","Program sekizde başlıyor."],
["veröffentlichen","yayımlamak","ferö:fıntlişın","Die Ergebnisse wurden gestern veröffentlicht.","Sonuçlar dün yayımlandı."],
["die Quelle","kaynak","di: kvele","Was ist die Quelle?","Kaynak ne?"],
["aktuell","güncel","aktuel","Das ist ein aktuelles Thema.","Bu güncel bir konu."],
["die Werbung","reklam","di: verbung","Es gibt zu viel Werbung.","Çok fazla reklam var."],
["die sozialen Medien","sosyal medya","di: zotsia:lın me:diın","Ich bin nicht oft in den sozialen Medien.","Sosyal medyada pek sık değilim."]],
p:[
["Laut den Nachrichten gibt es morgen einen Streik.","Haberlere göre yarın grev var."],
["Ich habe gelesen, dass die Mieten in Wien steigen.","Viyana'da kiraların arttığını okudum."],
["Angeblich soll das neue Gesetz bald kommen.","Söylendiğine göre yeni yasa yakında gelecek."],
["Man sollte nicht alles glauben, was im Internet steht.","İnternette yazan her şeye inanmamak lazım."],
["Was ist deine Quelle?","Kaynağın ne?"]]},

{t:"Toplum ve çevre",s:"die Umwelt, das Problem, die Lösung",
g:`<p>Bir sorunu tartışma şeması B1 sınavlarında (Goethe, ÖSD, telc) da istenir:</p><div class="tw"><table><tr><th>Adım</th><th>Kalıp</th></tr><tr><td>Konuyu tanıtmak</td><td>Ein wichtiges Thema ist …</td></tr><tr><td>Sorun</td><td>Das Problem ist, dass …</td></tr><tr><td>Neden</td><td>Das liegt daran, dass …</td></tr><tr><td>Sonuç</td><td>Das führt zu … · Die Folge ist …</td></tr><tr><td>Çözüm</td><td>Man könnte / sollte … · Eine Lösung wäre …</td></tr><tr><td>Kişisel</td><td>In meinem Heimatland …</td></tr></table></div><p>Genel özne <b>man</b> (insan, kişi) toplum konularında çok kullanılır: <b>Man sollte</b> weniger Auto fahren.</p><span class="n">Avusturya ve Almanya'da çöp ayrıştırma (<b>Mülltrennung</b>) çok ciddidir: Papier, Plastik, Glas, Bio ve Restmüll ayrı kutulara atılır.</span>`,
w:[
["die Umwelt","çevre","di: umvelt","Wir müssen die Umwelt schützen.","Çevreyi korumalıyız."],
["schützen","korumak","şütsın","Man sollte die Natur schützen.","Doğa korunmalı."],
["das Problem","sorun","das proble:m","Das Problem ist der Verkehr.","Sorun trafik."],
["die Lösung","çözüm","di: lö:zung","Wir brauchen eine Lösung.","Bir çözüme ihtiyacımız var."],
["der Müll","çöp","de:r mül","Den Müll muss man trennen.","Çöpü ayrıştırmak gerekiyor."],
["trennen","ayırmak","trenın","In Wien trennt man den Müll.","Viyana'da çöp ayrıştırılır."],
["der Klimawandel","iklim değişikliği","de:r kli:mavandıl","Der Klimawandel ist ein großes Problem.","İklim değişikliği büyük bir sorun."],
["die Energie","enerji","di: energi:","Wir sollten Energie sparen.","Enerji tasarrufu yapmalıyız."],
["sparen","tasarruf etmek","şpa:rın","Ich spare Wasser.","Su tasarrufu yapıyorum."],
["die Gesellschaft","toplum","di: gezelşaft","Die Gesellschaft verändert sich.","Toplum değişiyor."],
["die Folge","sonuç","di: folge","Das hat schlimme Folgen.","Bunun kötü sonuçları var."],
["verursachen","neden olmak","feru:rzahın","Autos verursachen viel Lärm.","Arabalar çok gürültüye neden oluyor."]],
p:[
["Das Problem ist, dass es zu viel Verkehr gibt.","Sorun şu ki çok fazla trafik var."],
["Das liegt daran, dass viele Leute mit dem Auto fahren.","Bunun sebebi birçok insanın arabayla gitmesi."],
["Eine Lösung wäre, mehr öffentliche Verkehrsmittel zu bauen.","Bir çözüm daha çok toplu taşıma inşa etmek olurdu."],
["Jeder kann etwas für die Umwelt tun.","Herkes çevre için bir şey yapabilir."],
["In meinem Heimatland ist das anders.","Benim ülkemde bu farklı."]]},

{t:"Edilgen çatı: Passiv",s:"wird gemacht, wurde gebaut",
g:`<p><b>Passiv</b>, işi kimin yaptığı önemli olmadığında kullanılır: <b>werden</b> + Partizip II.</p><div class="tw"><table><tr><th>Zaman</th><th>Yapı</th><th>Örnek</th></tr><tr><td>Şimdi</td><td>wird + Partizip</td><td>Das System <b>wird</b> neu <b>gestartet</b>.</td></tr><tr><td>Geçmiş</td><td>wurde + Partizip</td><td>Das Haus <b>wurde</b> 1900 <b>gebaut</b>.</td></tr><tr><td>Perfekt</td><td>ist + Partizip + worden</td><td>Der Fehler <b>ist behoben worden</b>.</td></tr><tr><td>Modal</td><td>muss + Partizip + werden</td><td>Das <b>muss</b> heute <b>erledigt werden</b>.</td></tr></table></div><p>Yapan kişi belirtilecekse <b>von</b> + Dativ: Das Projekt wurde <b>von</b> meinem Team geleitet.</p><span class="n">Teknik dilde ve kılavuzlarda Passiv çok yaygındır: "Das Update <b>wird</b> am Wochenende <b>eingespielt</b>" = Güncelleme hafta sonu yüklenecek.</span>`,
w:[
["gebaut","inşa edildi (bauen)","gebaut","Die Brücke wurde 1990 gebaut.","Köprü 1990'da inşa edildi."],
["repariert","tamir edildi","repari:rt","Das Auto wird morgen repariert.","Araba yarın tamir edilecek."],
["gelöscht","silindi","gelöşt","Die alten Daten wurden gelöscht.","Eski veriler silindi."],
["installiert","kuruldu","instali:rt","Das Update wird heute Nacht installiert.","Güncelleme bu gece kurulacak."],
["erledigen","halletmek","erle:digın","Das muss heute erledigt werden.","Bunun bugün halledilmesi gerekiyor."],
["beheben","gidermek (hata)","behe:bın","Der Fehler wurde schnell behoben.","Hata hızlıca giderildi."],
["eröffnen","açmak (resmen)","erö:fnın","Das Museum wurde 2010 eröffnet.","Müze 2010'da açıldı."],
["gründen","kurmak (şirket)","gründın","Die Firma wurde 1985 gegründet.","Şirket 1985'te kuruldu."],
["einladen","davet etmek","aynla:dın","Wir wurden zur Hochzeit eingeladen.","Düğüne davet edildik."],
["verbieten","yasaklamak","ferbi:tın","Rauchen ist hier verboten.","Burada sigara içmek yasak."],
["herstellen","üretmek","he:rştelın","Diese Autos werden in Deutschland hergestellt.","Bu arabalar Almanya'da üretiliyor."],
["worden","(Passiv Perfekt)","vordın","Das Paket ist gestern geliefert worden.","Paket dün teslim edildi."]],
p:[
["Das System wird gerade aktualisiert.","Sistem şu anda güncelleniyor."],
["Wann wurde das gebaut?","Bu ne zaman inşa edildi?"],
["Der Fehler ist schon behoben worden.","Hata çoktan giderildi."],
["Hier wird Deutsch gesprochen.","Burada Almanca konuşulur."],
["Die Rechnung muss bis Freitag bezahlt werden.","Faturanın cumaya kadar ödenmesi gerekiyor."]]},

{t:"Şikâyet ve sorun çözme",s:"die Beschwerde, funktioniert nicht, erstatten",
g:`<p>Kibar ama net bir şikâyet şu sırayla kurulur:</p><div class="tw"><table><tr><th>Adım</th><th>Kalıp</th></tr><tr><td>Giriş</td><td>Ich möchte mich beschweren. · Ich habe ein Problem mit …</td></tr><tr><td>Sorun</td><td>… funktioniert nicht. · … ist kaputt. · … fehlt.</td></tr><tr><td>Zaman</td><td>Seit drei Tagen … · Schon zum zweiten Mal …</td></tr><tr><td>Talep</td><td>Ich möchte das Geld zurück. · Können Sie das umtauschen?</td></tr><tr><td>Yazılı</td><td>Hiermit beschwere ich mich über …</td></tr><tr><td>Son tarih</td><td>Ich bitte Sie, das bis … zu klären.</td></tr></table></div><span class="n">Almanya ve Avusturya'da internet alışverişinde genellikle <b>14 gün cayma hakkı</b> (Widerrufsrecht) vardır. Fiş: <b>der Kassenbon / die Quittung</b>.</span>`,
w:[
["die Beschwerde","şikâyet","di: beşve:rde","Ich möchte eine Beschwerde einreichen.","Bir şikâyette bulunmak istiyorum."],
["sich beschweren","şikâyet etmek","ziş beşve:rın","Die Nachbarn beschweren sich über den Lärm.","Komşular gürültüden şikâyet ediyor."],
["funktionieren","çalışmak (cihaz)","funktsio:ni:rın","Die Heizung funktioniert nicht.","Kalorifer çalışmıyor."],
["kaputt","bozuk","kaput","Die Waschmaschine ist kaputt.","Çamaşır makinesi bozuk."],
["der Fehler","hata","de:r fe:lır","Das war ein Fehler.","Bu bir hataydı."],
["zurückgeben","geri vermek, iade etmek","tsurükge:bın","Ich möchte das zurückgeben.","Bunu iade etmek istiyorum."],
["erstatten","(parayı) iade etmek","erştatın","Wir erstatten Ihnen den Betrag.","Tutarı size iade ediyoruz."],
["der Kassenbon","fiş","de:r kasınbo:n","Haben Sie den Kassenbon noch?","Fiş hâlâ sizde mi?"],
["die Garantie","garanti","di: garanti:","Das Gerät hat zwei Jahre Garantie.","Cihazın iki yıl garantisi var."],
["umtauschen","değiştirmek (ürün)","umtauşın","Kann ich das umtauschen?","Bunu değiştirebilir miyim?"],
["die Verspätung","gecikme","di: ferşpe:tung","Der Flug hatte drei Stunden Verspätung.","Uçuş üç saat rötar yaptı."],
["klären","açıklığa kavuşturmak","kle:rın","Wir müssen das schnell klären.","Bunu hızlıca netleştirmemiz lazım."]],
p:[
["Ich habe ein Problem mit meiner Bestellung.","Siparişimle ilgili bir sorunum var."],
["Das Gerät funktioniert schon seit einer Woche nicht.","Cihaz bir haftadır çalışmıyor."],
["Ich möchte gern mein Geld zurück.","Paramı geri istiyorum."],
["Das ist schon das zweite Mal.","Bu zaten ikinci kez oluyor."],
["Können Sie mir bitte eine Lösung vorschlagen?","Bana bir çözüm önerebilir misiniz lütfen?"]]},

{t:"Kariyer ve mülakat",s:"die Erfahrung, die Kenntnisse, sich bewerben",
g:`<p>Kendi deneyimini anlatırken üç zaman bir arada kullanılır:</p><div class="tw"><table><tr><th>Ne</th><th>Zaman</th><th>Örnek</th></tr><tr><td>Şu anki iş</td><td>Präsens + seit</td><td>Ich arbeite <b>seit</b> fünf Jahren als SAP-Basis-Berater.</td></tr><tr><td>Geçmiş deneyim</td><td>Perfekt / Präteritum</td><td>Ich <b>habe</b> viele Migrationen <b>durchgeführt</b>.</td></tr><tr><td>Hedef</td><td>möchte / würde gern</td><td>Ich <b>würde</b> mich gern weiter<b>entwickeln</b>.</td></tr></table></div><p>Başvuru belgeleri: <b>der Lebenslauf</b> (özgeçmiş), <b>das Anschreiben</b> (ön yazı), <b>das Zeugnis</b> (referans/diploma), <b>die Bewerbung</b> (başvuru).</p><span class="n">Almanca konuşulan ülkelerde mülakatta sık sorulan soru: <b>Wo sehen Sie sich in fünf Jahren?</b> Maaş beklentisi: <b>Ihre Gehaltsvorstellung</b> (yıllık brüt olarak söylenir).</span>`,
w:[
["die Bewerbung","iş başvurusu","di: beverbung","Ich schicke meine Bewerbung heute ab.","Başvurumu bugün gönderiyorum."],
["sich bewerben","başvurmak","ziş beverbın","Ich bewerbe mich als SAP-Berater.","SAP danışmanı olarak başvuruyorum."],
["der Lebenslauf","özgeçmiş","de:r le:bınslauf","Mein Lebenslauf ist auf Englisch.","Özgeçmişim İngilizce."],
["die Erfahrung","deneyim","di: erfa:rung","Ich habe fünf Jahre Erfahrung.","Beş yıllık deneyimim var."],
["die Kenntnisse","bilgi, beceri (çoğul)","di: kentnise","Ich habe gute Englischkenntnisse.","İyi İngilizce bilgim var."],
["das Vorstellungsgespräch","iş görüşmesi","das fo:rştelungsgeşpre:ş","Ich habe morgen ein Vorstellungsgespräch.","Yarın bir iş görüşmem var."],
["die Stelle","pozisyon, iş yeri","di: ştele","Die Stelle ist in Wien.","Pozisyon Viyana'da."],
["das Gehalt","maaş","das geha:lt","Das Gehalt ist verhandelbar.","Maaş pazarlığa açık."],
["verantwortlich","sorumlu","ferantvortliş","Ich bin für die Systemadministration verantwortlich.","Sistem yönetiminden sorumluyum."],
["die Stärke","güçlü yön","di: şterke","Meine Stärke ist Problemlösung.","Güçlü yönüm problem çözmek."],
["die Weiterbildung","mesleki eğitim","di: vaytırbildung","Ich mache eine Weiterbildung.","Bir mesleki eğitim alıyorum."],
["selbstständig","serbest çalışan, bağımsız","zelpstştendiş","Ich möchte selbstständig arbeiten.","Serbest çalışmak istiyorum."]],
p:[
["Ich arbeite seit fünf Jahren als SAP-Basis-Berater.","Beş yıldır SAP Basis danışmanı olarak çalışıyorum."],
["Ich habe viel Erfahrung mit SAP HANA und S/4HANA.","SAP HANA ve S/4HANA konusunda çok deneyimim var."],
["Warum möchten Sie bei uns arbeiten?","Neden bizde çalışmak istiyorsunuz?"],
["Ich arbeite gern im Team, aber auch selbstständig.","Takım hâlinde de bağımsız da çalışmayı severim."],
["Wann könnten Sie anfangen?","Ne zaman başlayabilirsiniz?"]]},

{t:"Para ve resmi işler",s:"die Bank, die Miete, die Anmeldung",
g:`<p>Resmi işlerde gereklilik şöyle anlatılır:</p><div class="tw"><table><tr><th>Yapı</th><th>Örnek</th></tr><tr><td>man muss + mastar</td><td><b>Man muss</b> sich in drei Tagen <b>anmelden</b>.</td></tr><tr><td>Sie brauchen …</td><td><b>Sie brauchen</b> einen Reisepass und den Mietvertrag.</td></tr><tr><td>es ist nötig, … zu</td><td><b>Es ist nötig</b>, einen Termin <b>zu</b> vereinbaren.</td></tr><tr><td>Passiv + müssen</td><td>Das Formular <b>muss ausgefüllt werden</b>.</td></tr></table></div><p>Taşınınca ilk iş <b>Anmeldung</b>'dur (adres kaydı). Avusturya'da buna <b>Meldezettel</b> denir ve 3 gün içinde yapılır. Almanya'da 14 gün süren vardır.</p><span class="n">Kira ilanlarında: <b>Kaltmiete</b> (yalnız kira), <b>Warmmiete</b> (ısınma dahil), <b>Kaution</b> (depozito, genelde 2–3 kira), <b>Betriebskosten / Nebenkosten</b> (aidat ve giderler).</span>`,
w:[
["das Konto","banka hesabı","das konto","Ich möchte ein Konto eröffnen.","Bir hesap açmak istiyorum."],
["überweisen","havale etmek","ü:bırvayzın","Ich überweise dir das Geld.","Parayı sana havale ediyorum."],
["die Miete","kira","di: mi:te","Die Miete ist am Monatsanfang fällig.","Kira ay başında ödenir."],
["der Mietvertrag","kira sözleşmesi","de:r mi:tfertra:k","Ich unterschreibe den Mietvertrag.","Kira sözleşmesini imzalıyorum."],
["die Kaution","depozito","di: kautsio:n","Die Kaution beträgt drei Monatsmieten.","Depozito üç aylık kira."],
["die Anmeldung","adres kaydı / kayıt","di: anmeldung","Für die Anmeldung brauchen Sie den Pass.","Kayıt için pasaporta ihtiyacınız var."],
["das Formular","form","das formula:r","Bitte füllen Sie das Formular aus.","Lütfen formu doldurun."],
["ausfüllen","doldurmak (form)","ausfülın","Ich fülle das Formular online aus.","Formu internetten dolduruyorum."],
["unterschreiben","imzalamak","untırşraybın","Unterschreiben Sie bitte hier.","Lütfen buraya imza atın."],
["die Unterlagen","belgeler","di: untırla:gın","Ich habe alle Unterlagen dabei.","Tüm belgeler yanımda."],
["die Versicherung","sigorta","di: ferzişırung","Ich brauche eine Krankenversicherung.","Bir sağlık sigortasına ihtiyacım var."],
["die Behörde","resmî daire","di: behö:rde","Die Behörde ist nur vormittags offen.","Daire sadece öğleden önce açık."]],
p:[
["Welche Unterlagen brauche ich für die Anmeldung?","Kayıt için hangi belgelere ihtiyacım var?"],
["Ich möchte ein Girokonto eröffnen.","Vadesiz bir hesap açmak istiyorum."],
["Ist die Miete warm oder kalt?","Kira ısınma dahil mi, hariç mi?"],
["Muss ich einen Termin vereinbaren?","Randevu almam gerekiyor mu?"],
["Können Sie mir das bitte schriftlich geben?","Bunu bana yazılı olarak verebilir misiniz?"]]},

{t:"Amaç ve karşıtlık bağlaçları",s:"um … zu, damit, statt … zu, trotzdem",
g:`<p>Amaç bildirmenin iki yolu vardır:</p><div class="tw"><table><tr><th>Yapı</th><th>Ne zaman</th><th>Örnek</th></tr><tr><td>um … zu + mastar</td><td>iki cümlenin öznesi aynıysa</td><td>Ich lerne Deutsch, <b>um</b> in Wien <b>zu</b> arbeiten.</td></tr><tr><td>damit + yan cümle</td><td>özneler farklıysa</td><td>Ich spreche langsam, <b>damit</b> du mich verstehst.</td></tr><tr><td>ohne … zu</td><td>…meden</td><td>Er ging, <b>ohne</b> tschüss <b>zu</b> sagen.</td></tr><tr><td>statt … zu</td><td>…mek yerine</td><td><b>Statt zu</b> warten, rufe ich an.</td></tr></table></div><div class="tw"><table><tr><th>Bağlaç</th><th>Anlam</th></tr><tr><td>sondern</td><td>(değil) … bilakis</td></tr><tr><td>je … desto</td><td>ne kadar … o kadar</td></tr><tr><td>sowohl … als auch</td><td>hem … hem de</td></tr><tr><td>weder … noch</td><td>ne … ne de</td></tr><tr><td>entweder … oder</td><td>ya … ya da</td></tr></table></div><span class="n">Ayrılabilen fiilde <b>zu</b> araya girer: an<b>zu</b>rufen, auf<b>zu</b>stehen.</span>`,
w:[
["um … zu","…mek için","um … tsu:","Ich spare, um eine Wohnung zu kaufen.","Daire almak için para biriktiriyorum."],
["damit","…sın diye","damit","Ich erkläre es, damit alle es verstehen.","Herkes anlasın diye açıklıyorum."],
["ohne","…sız / …meden","o:ne","Er ist gegangen, ohne etwas zu sagen.","Bir şey söylemeden gitti."],
["statt","yerine","ştat","Statt Kaffee trinke ich Tee.","Kahve yerine çay içiyorum."],
["sondern","bilakis, -de","zondırn","Nicht heute, sondern morgen.","Bugün değil, yarın."],
["sowohl … als auch","hem … hem de","zo:vo:l … als auh","Ich spreche sowohl Englisch als auch Türkisch.","Hem İngilizce hem Türkçe konuşuyorum."],
["weder … noch","ne … ne de","ve:dır … noh","Ich habe weder Zeit noch Lust.","Ne vaktim ne de isteğim var."],
["entweder … oder","ya … ya da","entve:dır … o:dır","Entweder heute oder morgen.","Ya bugün ya yarın."],
["je … desto","ne kadar … o kadar","ye: … desto","Je früher, desto besser.","Ne kadar erken o kadar iyi."],
["außerdem","ayrıca","ausırde:m","Außerdem ist es billiger.","Ayrıca daha ucuz."],
["stattdessen","onun yerine","ştatdesın","Stattdessen bleiben wir zu Hause.","Onun yerine evde kalıyoruz."],
["zumindest","en azından","tsuminde:st","Zumindest hast du es versucht.","En azından denedin."]],
p:[
["Ich lerne jeden Tag, um besser Deutsch zu sprechen.","Daha iyi Almanca konuşmak için her gün çalışıyorum."],
["Ich schicke dir die Adresse, damit du uns findest.","Bizi bulasın diye sana adresi gönderiyorum."],
["Je mehr ich lese, desto mehr verstehe ich.","Ne kadar çok okursam o kadar çok anlıyorum."],
["Das ist nicht mein Fehler, sondern ein Systemfehler.","Bu benim hatam değil, sistem hatası."],
["Ich habe es geschafft, ohne Hilfe zu fragen.","Yardım istemeden başardım."]]},

{t:"Doğal konuşma",s:"also, halt, eigentlich, na ja, genau",
g:`<p>Ders kitaplarında az geçen ama Almanların her cümlede kullandığı dolgu ve tepki ifadeleri. Bunlar seni doğal duyurur:</p><div class="tw"><table><tr><th>İfade</th><th>Ne zaman</th></tr><tr><td>Also …</td><td>Yani / pekâlâ (konuya başlarken)</td></tr><tr><td>Genau!</td><td>Aynen! Tam olarak!</td></tr><tr><td>Na ja …</td><td>Şey… / Eh işte</td></tr><tr><td>halt / eben</td><td>işte (değiştirilemez durum)</td></tr><tr><td>Echt?</td><td>Gerçekten mi?</td></tr><tr><td>Keine Ahnung.</td><td>Hiçbir fikrim yok.</td></tr><tr><td>Passt! / Alles klar!</td><td>Tamam, olur!</td></tr><tr><td>Mal sehen.</td><td>Bakalım.</td></tr><tr><td>Ach so!</td><td>Haa, anladım!</td></tr></table></div><span class="n">Küçük vurgu kelimeleri (<b>mal, doch, ja, halt</b>) cümleyi yumuşatır: Komm <b>doch mal</b> vorbei! = Bir uğrasana! Avusturya'da <b>Passt!</b> ve <b>Oida</b> (samimi) çok duyulur.</span>`,
w:[
["also","yani, pekâlâ","alzo:","Also, wo waren wir?","Pekâlâ, nerede kalmıştık?"],
["genau","aynen, tam olarak","genau","Genau, das meine ich!","Aynen, onu kastediyorum!"],
["na ja","eh işte, şey","na: ya:","Na ja, es geht.","Eh işte, idare eder."],
["halt","işte (öyle)","halt","Das ist halt so.","İşte öyle."],
["echt","gerçekten","eşt","Echt? Das wusste ich nicht.","Gerçekten mi? Bilmiyordum."],
["keine Ahnung","hiçbir fikrim yok","kayne a:nung","Keine Ahnung, frag mal Anna.","Hiç bilmiyorum, Anna'ya sor."],
["alles klar","tamamdır","alıs kla:r","Alles klar, bis morgen!","Tamamdır, yarın görüşürüz!"],
["ach so","haa, anladım","ah zo:","Ach so, jetzt verstehe ich.","Haa, şimdi anladım."],
["mal sehen","bakalım","ma:l ze:ın","Mal sehen, ob es klappt.","Bakalım olacak mı."],
["übrigens","bu arada","ü:brigıns","Übrigens, hast du morgen Zeit?","Bu arada, yarın vaktin var mı?"],
["sozusagen","tabiri caizse","zo:tsuza:gın","Er ist sozusagen der Chef.","Tabiri caizse şef o."],
["Quatsch","saçmalık","kvatş","So ein Quatsch!","Ne saçmalık!"]],
p:[
["Also, ich würde sagen, wir machen das morgen.","Yani, bence bunu yarın yapalım."],
["Na ja, eigentlich hast du recht.","Şey, aslında haklısın."],
["Das ist halt so, da kann man nichts machen.","İşte öyle, yapacak bir şey yok."],
["Übrigens, mein Deutsch wird langsam besser.","Bu arada, Almancam yavaş yavaş gelişiyor."],
["Alles klar, dann bis später!","Tamamdır, o zaman sonra görüşürüz!"]]}
]});

LV.push({id:"B2",name:"Orta-Üstü",units:[
{t:"Genitiv ve Genitiv edatları",s:"des, wegen, trotz, während, aufgrund",
g:`<p><b>Genitiv</b> "-in" hâlidir (Türkçedeki tamlayan). Eril ve nötr isim <b>-s / -es</b> eki alır.</p><div class="tw"><table><tr><th></th><th>Belirli</th><th>Belirsiz</th><th>Örnek</th></tr><tr><td>Eril</td><td>des</td><td>eines</td><td>das Auto <b>des</b> Mann<b>es</b></td></tr><tr><td>Dişil</td><td>der</td><td>einer</td><td>die Tasche <b>der</b> Frau</td></tr><tr><td>Nötr</td><td>des</td><td>eines</td><td>das Ende <b>des</b> Film<b>s</b></td></tr><tr><td>Çoğul</td><td>der</td><td>—</td><td>die Meinung <b>der</b> Kunden</td></tr></table></div><p>Genitiv isteyen edatlar: <b>wegen</b> (yüzünden), <b>trotz</b> (rağmen), <b>während</b> (sırasında), <b>aufgrund</b> (nedeniyle), <b>innerhalb / außerhalb</b> (içinde / dışında), <b>statt</b> (yerine).</p><span class="n">Konuşmada wegen ve trotz çoğu zaman Dativ ile de kullanılır (wegen dem Wetter), ama yazıda ve sınavda Genitiv doğrudur: <b>wegen des Wetters</b>.</span>`,
w:[
["wegen","yüzünden","ve:gın","Wegen des Staus kam ich zu spät.","Trafik yüzünden geç kaldım."],
["trotz","-e rağmen","trots","Trotz des Regens sind wir gewandert.","Yağmura rağmen yürüyüş yaptık."],
["während","sırasında","ve:rınt","Während der Besprechung war das Handy aus.","Toplantı sırasında telefon kapalıydı."],
["aufgrund","nedeniyle","aufgrunt","Aufgrund eines Fehlers ist das System ausgefallen.","Bir hata nedeniyle sistem çöktü."],
["innerhalb","içinde (süre/yer)","inırhalp","Bitte antworten Sie innerhalb einer Woche.","Lütfen bir hafta içinde cevap verin."],
["außerhalb","dışında","ausırhalp","Wir wohnen außerhalb der Stadt.","Şehrin dışında oturuyoruz."],
["statt","yerine","ştat","Statt eines Autos kaufe ich ein Fahrrad.","Araba yerine bisiklet alıyorum."],
["laut","…e göre","laut","Laut des Berichts steigen die Kosten.","Rapora göre maliyetler artıyor."],
["anlässlich","vesilesiyle","anlesliş","Anlässlich seines Geburtstags gab es eine Feier.","Doğum günü vesilesiyle bir kutlama vardı."],
["bezüglich","ile ilgili olarak","betsü:kliş","Bezüglich Ihrer Anfrage melde ich mich morgen.","Talebinizle ilgili yarın dönüş yapacağım."],
["mithilfe","yardımıyla","mithilfe","Mithilfe eines Skripts haben wir die Daten migriert.","Bir betik yardımıyla verileri taşıdık."],
["infolge","sonucunda","infolge","Infolge des Stromausfalls stand die Produktion still.","Elektrik kesintisi sonucunda üretim durdu."]],
p:[
["Wegen der Wartungsarbeiten ist das System heute Nacht nicht erreichbar.","Bakım çalışmaları nedeniyle sistem bu gece erişilemez olacak."],
["Trotz aller Probleme haben wir das Projekt pünktlich abgeschlossen.","Tüm sorunlara rağmen projeyi zamanında bitirdik."],
["Das ist das Büro meines Kollegen.","Bu meslektaşımın ofisi."],
["Innerhalb der nächsten zwei Wochen erhalten Sie eine Antwort.","Önümüzdeki iki hafta içinde bir cevap alacaksınız."],
["Während des Urlaubs habe ich kaum E-Mails gelesen.","Tatil sırasında neredeyse hiç e-posta okumadım."]]},

{t:"Sıfat çekimi (tam tablo)",s:"der neue, ein neuer, neuer Wein",
g:`<p>İsimden önceki sıfat, önündeki kelimeye göre ek alır. Kural: <b>artikel cinsiyeti gösteriyorsa sıfat -e/-en</b>; göstermiyorsa sıfat kendisi gösterir.</p><div class="tw"><table><tr><th></th><th>der/die/das sonrası</th><th>ein sonrası</th><th>artikelsiz</th></tr><tr><td>Eril (özne)</td><td>der neu<b>e</b> Chef</td><td>ein neu<b>er</b> Chef</td><td>neu<b>er</b> Wein</td></tr><tr><td>Eril (nesne)</td><td>den neu<b>en</b> Chef</td><td>einen neu<b>en</b> Chef</td><td>neu<b>en</b> Wein</td></tr><tr><td>Dişil</td><td>die neu<b>e</b> Firma</td><td>eine neu<b>e</b> Firma</td><td>neu<b>e</b> Musik</td></tr><tr><td>Nötr</td><td>das neu<b>e</b> Auto</td><td>ein neu<b>es</b> Auto</td><td>neu<b>es</b> Brot</td></tr><tr><td>Dativ (hepsi)</td><td>dem neu<b>en</b> …</td><td>einem neu<b>en</b> …</td><td>mit neu<b>em</b> …</td></tr><tr><td>Çoğul</td><td>die neu<b>en</b> Kollegen</td><td>keine neu<b>en</b> …</td><td>neu<b>e</b> Kollegen</td></tr></table></div><span class="n">Kısa yol: Dativ, Genitiv ve çoğul (belirli) hep <b>-en</b>. Hata yapmamak için önce "artikel cinsiyeti gösteriyor mu?" diye sor.</span>`,
w:[
["neu","yeni","noy","Wir haben einen neuen Chef.","Yeni bir şefimiz var."],
["erfahren","deneyimli","erfa:rın","Sie ist eine erfahrene Beraterin.","Deneyimli bir danışman."],
["zuständig","yetkili, sorumlu","tsu:ştendiş","Wer ist der zuständige Kollege?","Sorumlu meslektaş kim?"],
["aktuell","güncel","aktuel","Das ist die aktuelle Version.","Bu güncel sürüm."],
["vorhanden","mevcut","fo:rhandın","Die vorhandenen Daten reichen nicht.","Mevcut veriler yetmiyor."],
["umfangreich","kapsamlı","umfangrayş","Das war ein umfangreiches Projekt.","Bu kapsamlı bir projeydi."],
["entscheidend","belirleyici","entşaydınt","Das ist ein entscheidender Punkt.","Bu belirleyici bir nokta."],
["bisherig","şimdiye kadarki","bishe:riş","Die bisherigen Ergebnisse sind gut.","Şimdiye kadarki sonuçlar iyi."],
["zusätzlich","ek, ilave","tsu:zetsliş","Wir brauchen zusätzliche Ressourcen.","Ek kaynaklara ihtiyacımız var."],
["gesamt","tüm, toplam","gezamt","Die gesamte Abteilung war da.","Tüm departman oradaydı."],
["bestimmt","belirli / kesin","beştimt","Haben Sie einen bestimmten Wunsch?","Belirli bir isteğiniz var mı?"],
["günstig","uygun (fiyat/zaman)","günstiş","Das ist ein günstiger Zeitpunkt.","Bu uygun bir zaman."]],
p:[
["Ich suche eine größere Wohnung mit einem kleinen Balkon.","Küçük balkonlu daha büyük bir daire arıyorum."],
["Mit freundlichen Grüßen und bestem Dank","Saygılarımla ve en içten teşekkürlerimle"],
["Das ist der wichtigste Punkt der heutigen Besprechung.","Bu bugünkü toplantının en önemli noktası."],
["Wir arbeiten mit modernen Technologien.","Modern teknolojilerle çalışıyoruz."],
["Er hat ein sehr gutes Angebot bekommen.","Çok iyi bir teklif aldı."]]},

{t:"Partizip sıfatlar",s:"die laufende Wartung, das gelöste Problem",
g:`<p>Fiiller sıfat olarak kullanılabilir:</p><div class="tw"><table><tr><th>Biçim</th><th>Yapı</th><th>Anlam</th><th>Örnek</th></tr><tr><td>Partizip I</td><td>mastar + d</td><td>-en, -makta olan (etken)</td><td>die <b>laufende</b> Wartung</td></tr><tr><td>Partizip II</td><td>ge…t / ge…en</td><td>-miş, -ilen (edilgen, bitmiş)</td><td>das <b>gelöste</b> Problem</td></tr></table></div><p>Bu sıfatlar genişletilebilir (resmî dilde çok sık): die <b>seit Montag laufende</b> Wartung = pazartesiden beri süren bakım. Çevirirken Türkçedeki gibi <b>sondan başa</b> oku.</p><span class="n">Türkçe ile aynı mantık: "dün <b>kurulan</b> sistem" = das gestern <b>installierte</b> System. Sıfat çekim eklerini unutma: ein <b>laufender</b> Prozess.</span>`,
w:[
["laufend","süren, devam eden","laufınt","Die laufenden Kosten sind hoch.","Süregelen maliyetler yüksek."],
["steigend","artan","ştaygınt","Steigende Mieten sind ein Problem.","Artan kiralar bir sorun."],
["folgend","aşağıdaki, izleyen","folgınt","Beachten Sie die folgenden Punkte.","Aşağıdaki noktalara dikkat edin."],
["entsprechend","uygun, ilgili","entşpreşınt","Bitte füllen Sie das entsprechende Formular aus.","Lütfen ilgili formu doldurun."],
["dringend","acil","dringınt","Wir haben eine dringende Anfrage.","Acil bir talebimiz var."],
["geplant","planlanmış","gepla:nt","Die geplante Migration beginnt im März.","Planlanan geçiş martta başlıyor."],
["gelöst","çözülmüş","gelö:st","Das gelöste Problem kam nicht zurück.","Çözülen sorun geri gelmedi."],
["veröffentlicht","yayımlanmış","ferö:fıntlişt","Der veröffentlichte Bericht ist online.","Yayımlanan rapor internette."],
["abgeschlossen","tamamlanmış","apgeşlosın","Das ist ein abgeschlossenes Projekt.","Bu tamamlanmış bir proje."],
["ausgebucht","tamamen dolu","ausgebu:ht","Das Hotel ist ausgebucht.","Otel tamamen dolu."],
["betroffen","etkilenen","betrofın","Alle betroffenen Nutzer wurden informiert.","Etkilenen tüm kullanıcılar bilgilendirildi."],
["zufriedenstellend","tatmin edici","tsufri:dınştelınt","Das Ergebnis ist zufriedenstellend.","Sonuç tatmin edici."]],
p:[
["Das gestern installierte Update verursacht Fehler.","Dün kurulan güncelleme hatalara yol açıyor."],
["Die seit Wochen laufende Diskussion ist endlich vorbei.","Haftalardır süren tartışma nihayet bitti."],
["Alle betroffenen Systeme wurden neu gestartet.","Etkilenen tüm sistemler yeniden başlatıldı."],
["Bitte beachten Sie die folgenden Hinweise.","Lütfen aşağıdaki notlara dikkat edin."],
["Die von uns vorgeschlagene Lösung wurde akzeptiert.","Bizim önerdiğimiz çözüm kabul edildi."]]},

{t:"Konjunktiv I ve dolaylı anlatım",s:"er sagt, er sei krank · sie habe keine Zeit",
g:`<p>Haberlerde ve resmî yazıda başkasının sözü <b>Konjunktiv I</b> ile aktarılır. Böylece yazar "bunu ben söylemiyorum" der.</p><div class="tw"><table><tr><th>Mastar</th><th>er/sie/es</th><th>Örnek</th></tr><tr><td>sein</td><td><b>sei</b></td><td>Er sagt, er <b>sei</b> krank.</td></tr><tr><td>haben</td><td><b>habe</b></td><td>Sie sagt, sie <b>habe</b> keine Zeit.</td></tr><tr><td>können</td><td><b>könne</b></td><td>Er meint, er <b>könne</b> nicht kommen.</td></tr><tr><td>werden</td><td><b>werde</b></td><td>Die Firma teilt mit, sie <b>werde</b> expandieren.</td></tr><tr><td>machen</td><td><b>mache</b></td><td>Er behauptet, er <b>mache</b> alles richtig.</td></tr></table></div><p>Geçmiş: <b>habe/sei + Partizip</b>: Er sagt, er <b>habe</b> den Fehler <b>behoben</b>.</p><span class="n">Konjunktiv I normal şimdiki zamanla aynıysa (ich habe, wir haben) yerine <b>Konjunktiv II</b> kullanılır: Sie sagen, sie <b>hätten</b> keine Zeit. Günlük konuşmada çoğu kişi basitçe "dass + normal fiil" der.</span>`,
w:[
["sei","olduğu (Konj. I)","zay","Er sagt, er sei im Urlaub.","Tatilde olduğunu söylüyor."],
["habe","sahip olduğu (Konj. I)","ha:be","Sie behauptet, sie habe nichts gewusst.","Hiçbir şey bilmediğini iddia ediyor."],
["könne","-ebildiği (Konj. I)","köne","Er meint, er könne das allein.","Bunu tek başına yapabileceğini düşünüyor."],
["werde","-eceği (Konj. I)","ve:rde","Der Minister erklärte, er werde zurücktreten.","Bakan istifa edeceğini açıkladı."],
["behaupten","iddia etmek","behauptın","Er behauptet, das System sei sicher.","Sistemin güvenli olduğunu iddia ediyor."],
["mitteilen","bildirmek","mittaylın","Die Firma teilte mit, man habe das Problem gelöst.","Şirket sorunu çözdüklerini bildirdi."],
["erklären","açıklamak, beyan etmek","erkle:rın","Sie erklärte, sie sei nicht zuständig.","Yetkili olmadığını açıkladı."],
["betonen","vurgulamak","beto:nın","Der Chef betonte, die Deadline gelte.","Şef son tarihin geçerli olduğunu vurguladı."],
["angeben","belirtmek","ange:bın","Er gab an, er habe nichts gesehen.","Hiçbir şey görmediğini belirtti."],
["die Aussage","ifade, beyan","di: ausza:ge","Laut seiner Aussage sei alles in Ordnung.","İfadesine göre her şey yolundaymış."],
["zufolge","…e göre","tsufolge","Dem Bericht zufolge seien die Zahlen falsch.","Rapora göre rakamlar yanlışmış."],
["indirekt","dolaylı","indirekt","Das ist indirekte Rede.","Bu dolaylı anlatım."]],
p:[
["Der Kunde sagt, das System sei seit gestern langsam.","Müşteri sistemin dünden beri yavaş olduğunu söylüyor."],
["Sie meinte, sie habe die Mail nicht bekommen.","E-postayı almadığını söyledi."],
["Laut Pressesprecher werde es keine Entlassungen geben.","Basın sözcüsüne göre işten çıkarma olmayacakmış."],
["Er fragte, ob ich Zeit hätte.","Vaktim olup olmadığını sordu."],
["Sie behaupten, sie hätten alles getestet.","Her şeyi test ettiklerini iddia ediyorlar."]]},

{t:"Passiv alternatifleri",s:"lässt sich, -bar, ist zu machen, man",
g:`<p>Almanca Passiv'i her zaman werden ile kurmaz. Yazıda sık görülen alternatifler:</p><div class="tw"><table><tr><th>Yapı</th><th>Anlam</th><th>Örnek</th></tr><tr><td>sich lassen + mastar</td><td>-ilebilir</td><td>Das Problem <b>lässt sich</b> lösen.</td></tr><tr><td>sıfat + -bar</td><td>-ilebilir</td><td>Das Problem ist <b>lösbar</b>.</td></tr><tr><td>sein + zu + mastar</td><td>-ilmeli / -ilebilir</td><td>Das Formular <b>ist</b> bis Freitag <b>abzugeben</b>.</td></tr><tr><td>man + aktif fiil</td><td>-ilir</td><td><b>Man</b> spricht hier Deutsch.</td></tr><tr><td>bekommen + Partizip</td><td>(birine) -ilmek</td><td>Ich <b>bekomme</b> das Paket <b>geliefert</b>.</td></tr></table></div><span class="n">"sein + zu" bağlama göre zorunluluk ya da olanak bildirir: Die Rechnung <b>ist</b> sofort <b>zu bezahlen</b> (ödenmeli) · Das <b>ist</b> nicht <b>zu ändern</b> (değiştirilemez).</span>`,
w:[
["sich lassen","-ilebilmek","ziş lasın","Das lässt sich leicht ändern.","Bu kolayca değiştirilebilir."],
["machbar","yapılabilir","mahba:r","Das ist in zwei Wochen machbar.","Bu iki haftada yapılabilir."],
["lösbar","çözülebilir","lö:sba:r","Das Problem ist lösbar.","Sorun çözülebilir."],
["erreichbar","ulaşılabilir","erayşba:r","Ich bin morgen telefonisch erreichbar.","Yarın telefonla ulaşılabilirim."],
["verfügbar","mevcut, kullanılabilir","ferfü:kba:r","Der Server ist wieder verfügbar.","Sunucu yeniden kullanılabilir."],
["vergleichbar","karşılaştırılabilir","ferglayşba:r","Die Ergebnisse sind nicht vergleichbar.","Sonuçlar karşılaştırılamaz."],
["abgeben","teslim etmek","apge:bın","Der Antrag ist bis Montag abzugeben.","Başvuru pazartesiye kadar teslim edilmeli."],
["beachten","dikkate almak","beahtın","Folgendes ist zu beachten.","Şunlara dikkat edilmeli."],
["vermeiden","kaçınmak","fermaydın","Solche Fehler sind zu vermeiden.","Bu tür hatalardan kaçınılmalı."],
["unvermeidbar","kaçınılmaz","unfermaytba:r","Eine kurze Ausfallzeit ist unvermeidbar.","Kısa bir kesinti kaçınılmaz."],
["nachvollziehbar","anlaşılır","na:hfoltsi:ba:r","Ihre Entscheidung ist nachvollziehbar.","Kararınız anlaşılır."],
["umsetzbar","uygulanabilir","umzetsba:r","Der Plan ist gut umsetzbar.","Plan rahatça uygulanabilir."]],
p:[
["Das lässt sich leider nicht mehr ändern.","Bu maalesef artık değiştirilemez."],
["Die Rechnung ist innerhalb von 14 Tagen zu begleichen.","Fatura 14 gün içinde ödenmeli."],
["Ist das bis Freitag machbar?","Bu cumaya kadar yapılabilir mi?"],
["Hier darf man nicht rauchen.","Burada sigara içilmez."],
["Ich bin ab 9 Uhr erreichbar.","Saat 9'dan itibaren ulaşılabilirim."]]},

{t:"Modal fiillerin öznel anlamı",s:"er muss krank sein, sie soll reich sein, er will … haben",
g:`<p>Modal fiiller tahmin ve iddia da bildirir:</p><div class="tw"><table><tr><th>Fiil</th><th>Anlam</th><th>Örnek</th></tr><tr><td>muss</td><td>kesin öyle (≈ %90)</td><td>Er <b>muss</b> krank sein.</td></tr><tr><td>dürfte</td><td>büyük ihtimalle (≈ %75)</td><td>Das <b>dürfte</b> reichen.</td></tr><tr><td>kann / könnte</td><td>olabilir (≈ %50)</td><td>Das <b>könnte</b> ein Bug sein.</td></tr><tr><td>soll</td><td>söylendiğine göre</td><td>Sie <b>soll</b> sehr reich sein.</td></tr><tr><td>will</td><td>kendisi iddia ediyor</td><td>Er <b>will</b> alles gewusst haben.</td></tr></table></div><p>Geçmişe dair tahmin: modal + <b>Partizip + haben/sein</b>: Er <b>muss</b> den Zug <b>verpasst haben</b> = Treni kaçırmış olmalı.</p><span class="n">Geçmişte yapılmayanı eleştirmek için Konjunktiv II: Du <b>hättest</b> mich anrufen <b>sollen</b> = Beni araman gerekirdi.</span>`,
w:[
["dürfte","muhtemelen …dır","dürfte","Das dürfte kein Problem sein.","Bu muhtemelen sorun olmaz."],
["muss … sein","…olmalı (kesin tahmin)","mus … zayn","Das muss ein Missverständnis sein.","Bu bir yanlış anlaşılma olmalı."],
["könnte","olabilir","könte","Das könnte am Netzwerk liegen.","Bu ağdan kaynaklanıyor olabilir."],
["soll","söylendiğine göre","zol","Das Restaurant soll sehr gut sein.","Restoranın çok iyi olduğu söyleniyor."],
["will","(kendi) iddiasına göre","vil","Er will das nicht gewusst haben.","Bunu bilmediğini iddia ediyor."],
["vermutlich","muhtemelen","fermu:tliş","Er ist vermutlich im Stau.","Muhtemelen trafikte."],
["wohl","herhalde","vo:l","Sie ist wohl schon nach Hause gegangen.","Herhalde eve gitmiştir."],
["anscheinend","görünüşe göre","anşaynınt","Anscheinend hat niemand die Mail gelesen.","Görünüşe göre kimse e-postayı okumamış."],
["offenbar","anlaşılan","ofınba:r","Offenbar gab es ein Missverständnis.","Anlaşılan bir yanlış anlaşılma olmuş."],
["verpassen","kaçırmak","ferpasın","Er muss den Zug verpasst haben.","Treni kaçırmış olmalı."],
["hätte … sollen","…meliydi","hete … zolın","Wir hätten früher testen sollen.","Daha önce test etmeliydik."],
["hätte … können","…ebilirdi","hete … könın","Das hätte schlimmer sein können.","Daha kötü olabilirdi."]],
p:[
["Er ist nicht da, er muss krank sein.","Burada değil, hasta olmalı."],
["Das dürfte etwa zwei Stunden dauern.","Bu yaklaşık iki saat sürer muhtemelen."],
["Die neue Version soll viel schneller sein.","Yeni sürümün çok daha hızlı olduğu söyleniyor."],
["Du hättest mir das früher sagen sollen.","Bunu bana daha önce söylemeliydin."],
["Das hätte man vermeiden können.","Bu önlenebilirdi."]]},

{t:"Konjunktiv II geçmiş ve als ob",s:"wäre gekommen, hätte gemacht, als ob",
g:`<p>Geçmişteki gerçekleşmemiş durumlar: <b>hätte / wäre + Partizip II</b>.</p><div class="tw"><table><tr><th>Kullanım</th><th>Örnek</th><th>Anlam</th></tr><tr><td>Hayalî geçmiş</td><td>Ich <b>wäre</b> gern <b>gekommen</b>.</td><td>Gelmeyi isterdim (gelemedim).</td></tr><tr><td>Koşul (geçmiş)</td><td>Wenn ich das <b>gewusst hätte</b>, …</td><td>Bunu bilseydim …</td></tr><tr><td>Pişmanlık</td><td>Ich <b>hätte</b> das nicht <b>sagen sollen</b>.</td><td>Bunu söylememeliydim.</td></tr><tr><td>als ob</td><td>Er tut so, <b>als ob</b> er nichts <b>wüsste</b>.</td><td>Hiçbir şey bilmiyormuş gibi yapıyor.</td></tr><tr><td>Neredeyse</td><td>Ich <b>hätte</b> fast den Flug <b>verpasst</b>.</td><td>Az kalsın uçağı kaçırıyordum.</td></tr></table></div><span class="n"><b>als ob</b> yerine <b>als</b> + fiil hemen ardından da kullanılır: Er tut so, <b>als wüsste</b> er nichts.</span>`,
w:[
["als ob","-mış gibi","als op","Er tut so, als ob er krank wäre.","Hastaymış gibi davranıyor."],
["so tun","…mış gibi yapmak","zo: tu:n","Tu nicht so, als ob du nichts wüsstest.","Hiçbir şey bilmiyormuş gibi yapma."],
["fast","neredeyse","fast","Ich hätte fast den Termin vergessen.","Az kalsın randevuyu unutuyordum."],
["beinahe","az kalsın","bayna:e","Beinahe wäre ich gestürzt.","Az kalsın düşüyordum."],
["bereuen","pişman olmak","beroyın","Ich bereue nichts.","Hiçbir şeye pişman değilim."],
["rechtzeitig","zamanında","reşttsaytiş","Hätten wir rechtzeitig reagiert, …","Zamanında tepki verseydik, …"],
["gewusst","bilinen (wissen)","gevust","Hätte ich das gewusst!","Keşke bunu bilseydim!"],
["wäre gekommen","gelirdi (geçmiş)","ve:re gekomın","Ich wäre gern gekommen.","Gelmeyi isterdim."],
["hätte gemacht","yapardı (geçmiş)","hete gemaht","Ich hätte das anders gemacht.","Ben bunu farklı yapardım."],
["der Zufall","tesadüf","de:r tsu:fal","Wenn das kein Zufall wäre!","Bu tesadüf olmasaydı!"],
["vorsichtiger","daha dikkatli","fo:rziştigır","Wir hätten vorsichtiger sein müssen.","Daha dikkatli olmalıydık."],
["anders","farklı","andırs","Es wäre anders gekommen.","İş farklı olurdu."]],
p:[
["Wenn ich das gewusst hätte, hätte ich anders entschieden.","Bunu bilseydim farklı karar verirdim."],
["Ich wäre gern mitgekommen, aber ich war krank.","Gelmeyi isterdim ama hastaydım."],
["Er redet, als ob er der Chef wäre.","Şefmiş gibi konuşuyor."],
["Das hätten wir uns sparen können.","Buna hiç gerek yoktu (bundan kaçınabilirdik)."],
["An deiner Stelle hätte ich sofort angerufen.","Senin yerinde olsam hemen arardım."]]},

{t:"Nominalisierung: isim ağırlıklı dil",s:"entscheiden → die Entscheidung treffen",
g:`<p>Resmî ve teknik Almanca fiil yerine <b>isim</b> kullanmayı sever (Nominalstil):</p><div class="tw"><table><tr><th>Fiil cümlesi (konuşma)</th><th>İsim cümlesi (yazı)</th></tr><tr><td>Weil das System ausgefallen ist, …</td><td><b>Aufgrund des Systemausfalls</b> …</td></tr><tr><td>Nachdem wir das Update installiert hatten, …</td><td><b>Nach der Installation des Updates</b> …</td></tr><tr><td>Wenn Sie Fragen haben, …</td><td><b>Bei Fragen</b> …</td></tr><tr><td>Obwohl es Probleme gab, …</td><td><b>Trotz der Probleme</b> …</td></tr><tr><td>Um die Kosten zu senken, …</td><td><b>Zur Senkung der Kosten</b> …</td></tr></table></div><p>İsim yapım ekleri: <b>-ung</b> (die Lösung), <b>-heit / -keit</b> (die Sicherheit), <b>-ion</b> (die Installation), mastar (das Testen), kök (der Ausfall).</p><span class="n">E-postada "Bei Fragen stehe ich Ihnen gern zur Verfügung" (Sorularınız olursa memnuniyetle yardımcı olurum) en klasik kapanıştır.</span>`,
w:[
["die Entscheidung","karar","di: entşaydung","Wir müssen eine Entscheidung treffen.","Bir karar vermemiz lazım."],
["die Durchführung","yürütme, uygulama","di: durşfü:rung","Die Durchführung dauert drei Tage.","Uygulama üç gün sürüyor."],
["die Umsetzung","hayata geçirme","di: umzetsung","Die Umsetzung beginnt im Mai.","Uygulama mayısta başlıyor."],
["die Verbesserung","iyileştirme","di: ferbesırung","Das ist eine deutliche Verbesserung.","Bu belirgin bir iyileşme."],
["der Ausfall","kesinti, çöküş","de:r ausfal","Nach dem Ausfall lief alles wieder.","Kesintiden sonra her şey yeniden çalıştı."],
["die Senkung","düşürme","di: zenkung","Ziel ist die Senkung der Kosten.","Hedef maliyetlerin düşürülmesi."],
["die Erhöhung","artırma","di: erhö:ung","Wir planen eine Erhöhung der Kapazität.","Kapasite artırımı planlıyoruz."],
["die Überprüfung","kontrol, denetim","di: ü:bırprü:fung","Nach der Überprüfung melden wir uns.","Kontrolden sonra dönüş yapacağız."],
["die Genehmigung","onay, izin","di: gene:migung","Wir warten auf die Genehmigung.","Onayı bekliyoruz."],
["die Inbetriebnahme","devreye alma","di: inbetri:pna:me","Die Inbetriebnahme ist für Juni geplant.","Devreye alma haziranda planlanıyor."],
["bei","…durumunda, …de","bay","Bei Problemen rufen Sie bitte an.","Sorun olursa lütfen arayın."],
["zur Verfügung stehen","hizmetinde olmak","tsu:r ferfü:gung şte:ın","Ich stehe Ihnen gern zur Verfügung.","Memnuniyetle hizmetinizdeyim."]],
p:[
["Bei Fragen stehe ich Ihnen gern zur Verfügung.","Sorularınız olursa memnuniyetle yardımcı olurum."],
["Nach Abschluss der Tests erfolgt die Inbetriebnahme.","Testlerin tamamlanmasının ardından devreye alma yapılır."],
["Zur Vermeidung von Datenverlust bitte vorher ein Backup erstellen.","Veri kaybını önlemek için lütfen önce yedek alın."],
["Aufgrund der hohen Nachfrage kommt es zu Verzögerungen.","Yüksek talep nedeniyle gecikmeler yaşanıyor."],
["Die Umsetzung erfolgt in drei Phasen.","Uygulama üç aşamada gerçekleşiyor."]]},

{t:"Funktionsverbgefüge",s:"zur Verfügung stellen, in Frage kommen, Bescheid geben",
g:`<p><b>Funktionsverbgefüge</b> = anlamı isimde taşıyan sabit "isim + fiil" kalıpları. Resmî dilde fiilin kendisi yerine tercih edilir.</p><div class="tw"><table><tr><th>Kalıp</th><th>Basit fiil</th><th>Anlam</th></tr><tr><td>eine Entscheidung treffen</td><td>entscheiden</td><td>karar vermek</td></tr><tr><td>zur Verfügung stellen</td><td>bereitstellen</td><td>sağlamak</td></tr><tr><td>in Frage kommen</td><td>möglich sein</td><td>söz konusu olmak</td></tr><tr><td>Kritik üben</td><td>kritisieren</td><td>eleştirmek</td></tr><tr><td>in Kraft treten</td><td>gültig werden</td><td>yürürlüğe girmek</td></tr><tr><td>Rücksicht nehmen auf</td><td>berücksichtigen</td><td>dikkate almak</td></tr><tr><td>zum Abschluss bringen</td><td>abschließen</td><td>sonuçlandırmak</td></tr></table></div><span class="n">Bu kalıplarda fiili değiştiremezsin: "eine Entscheidung <b>machen</b>" ✗ → "eine Entscheidung <b>treffen</b>" ✓. Kalıbı bütün olarak ezberle.</span>`,
w:[
["eine Entscheidung treffen","karar vermek","ayne entşaydung trefın","Wir müssen heute eine Entscheidung treffen.","Bugün bir karar vermeliyiz."],
["zur Verfügung stellen","sağlamak, tahsis etmek","tsu:r ferfü:gung ştelın","Wir stellen Ihnen einen Testzugang zur Verfügung.","Size bir test erişimi sağlıyoruz."],
["in Frage kommen","söz konusu olmak","in fra:ge komın","Das kommt nicht in Frage.","Bu söz konusu bile olamaz."],
["Kritik üben","eleştirmek","kriti:k ü:bın","Er übte scharfe Kritik an dem Plan.","Plana sert eleştiri getirdi."],
["in Kraft treten","yürürlüğe girmek","in kraft tre:tın","Das Gesetz tritt im Januar in Kraft.","Yasa ocakta yürürlüğe giriyor."],
["Rücksicht nehmen","dikkate almak, saygı göstermek","rükzişt ne:mın","Bitte nehmen Sie Rücksicht auf die Nachbarn.","Lütfen komşuları dikkate alın."],
["Bescheid geben","haber vermek","beşayt ge:bın","Gib mir bitte Bescheid, wenn du fertig bist.","Bitirince bana haber ver lütfen."],
["in Anspruch nehmen","yararlanmak","in anşpruh ne:mın","Wir nehmen den Support in Anspruch.","Destek hizmetinden yararlanıyoruz."],
["eine Rolle spielen","rol oynamak","ayne role şpi:lın","Der Preis spielt eine große Rolle.","Fiyat büyük rol oynuyor."],
["zum Ausdruck bringen","ifade etmek","tsum ausdruk bringın","Er brachte seine Sorge zum Ausdruck.","Endişesini dile getirdi."],
["in Betracht ziehen","göz önünde bulundurmak","in betraht tsi:ın","Wir ziehen eine Cloud-Lösung in Betracht.","Bir bulut çözümünü değerlendiriyoruz."],
["Maßnahmen ergreifen","önlem almak","ma:sna:mın ergrayfın","Wir haben sofort Maßnahmen ergriffen.","Hemen önlem aldık."]],
p:[
["Das kommt überhaupt nicht in Frage.","Bu kesinlikle söz konusu değil."],
["Wir stellen Ihnen die Unterlagen gern zur Verfügung.","Belgeleri memnuniyetle size sağlarız."],
["Bitte geben Sie mir bis Freitag Bescheid.","Lütfen cumaya kadar bana haber verin."],
["Wir sollten auch andere Optionen in Betracht ziehen.","Başka seçenekleri de göz önünde bulundurmalıyız."],
["Die neue Regelung tritt ab sofort in Kraft.","Yeni düzenleme derhâl yürürlüğe giriyor."]]},

{t:"Edatlı fiiller, da- ve wo- birleşikleri",s:"darauf, worüber, sich verlassen auf",
g:`<p>Edatlı fiilde nesne bir <b>şey</b> ise zamir yerine <b>da(r) + edat</b>, soru için <b>wo(r) + edat</b> kullanılır. Kişi ise edat + zamir:</p><div class="tw"><table><tr><th>Fiil</th><th>Şey</th><th>Kişi</th><th>Soru (şey)</th></tr><tr><td>warten auf</td><td>Ich warte <b>darauf</b>.</td><td>Ich warte <b>auf ihn</b>.</td><td><b>Worauf</b> wartest du?</td></tr><tr><td>sprechen über</td><td>Wir sprechen <b>darüber</b>.</td><td>… <b>über sie</b>.</td><td><b>Worüber</b>?</td></tr><tr><td>sich kümmern um</td><td>Ich kümmere mich <b>darum</b>.</td><td>… <b>um ihn</b>.</td><td><b>Worum</b>?</td></tr><tr><td>denken an</td><td>Ich denke <b>daran</b>.</td><td>… <b>an dich</b>.</td><td><b>Woran</b>?</td></tr></table></div><p>da- birleşiği bir yan cümleyi önceden haber verebilir: Ich freue mich <b>darauf</b>, <b>dass</b> du kommst. · Es kommt <b>darauf</b> an, <b>ob</b> …</p><span class="n">Edat sesliyle başlıyorsa araya <b>r</b> girer: da<b>r</b>auf, wo<b>r</b>über, da<b>r</b>an.</span>`,
w:[
["darauf","onu, ona (auf + şey)","da:rauf","Ich freue mich schon darauf.","Şimdiden dört gözle bekliyorum."],
["darüber","onun hakkında","da:rü:bır","Darüber müssen wir reden.","Bunu konuşmamız lazım."],
["darum","onunla (um + şey)","da:rum","Ich kümmere mich darum.","Ben ilgilenirim."],
["daran","ona (an + şey)","da:ran","Denk bitte daran!","Lütfen bunu unutma!"],
["damit","onunla (mit + şey)","da:mit","Ich bin damit einverstanden.","Buna razıyım."],
["worauf","neyi, neye","vo:rauf","Worauf wartest du?","Neyi bekliyorsun?"],
["worüber","ne hakkında","vo:rü:bır","Worüber habt ihr gesprochen?","Ne hakkında konuştunuz?"],
["sich verlassen auf","güvenmek","ziş ferlasın auf","Du kannst dich darauf verlassen.","Buna güvenebilirsin."],
["abhängen von","bağlı olmak","aphengın fon","Das hängt davon ab, wie viel es kostet.","Bu ne kadar tuttuğuna bağlı."],
["sich beschäftigen mit","uğraşmak","ziş beşeftigın mit","Ich beschäftige mich gerade damit.","Şu an bununla uğraşıyorum."],
["achten auf","dikkat etmek","ahtın auf","Achte bitte darauf, dass alles gespeichert ist.","Her şeyin kaydedildiğinden emin ol lütfen."],
["ankommen auf","bağlı olmak, önemli olmak","ankomın auf","Es kommt darauf an.","Duruma göre değişir."]],
p:[
["Es kommt darauf an, wie schnell wir reagieren.","Ne kadar hızlı tepki verdiğimize bağlı."],
["Ich habe nicht damit gerechnet.","Bunu beklemiyordum."],
["Woran liegt das Problem?","Sorun neden kaynaklanıyor?"],
["Kümmerst du dich darum, oder soll ich?","Sen mi ilgileniyorsun, ben mi?"],
["Ich bin damit völlig einverstanden.","Buna tamamen katılıyorum."]]},

{t:"Toplantı ve iş yazışması",s:"Tagesordnung, Protokoll, nachhaken",
g:`<p>Toplantı yönetmek ve yazışmak için B2 kalıpları:</p><div class="tw"><table><tr><th>Durum</th><th>Kalıp</th></tr><tr><td>Başlatmak</td><td>Lassen Sie uns anfangen. · Auf der Tagesordnung steht …</td></tr><tr><td>Söz almak</td><td>Darf ich kurz etwas ergänzen?</td></tr><tr><td>Söz kesilince</td><td>Lassen Sie mich bitte ausreden.</td></tr><tr><td>Netleştirmek</td><td>Habe ich Sie richtig verstanden, dass …?</td></tr><tr><td>Özetlemek</td><td>Fassen wir zusammen: …</td></tr><tr><td>Görev dağıtmak</td><td>Wer übernimmt das? · Bis wann?</td></tr><tr><td>Hatırlatma (e-posta)</td><td>Ich möchte kurz nachhaken bezüglich …</td></tr><tr><td>Gecikme özrü</td><td>Entschuldigen Sie die späte Rückmeldung.</td></tr></table></div><span class="n">Avusturya'da iş e-postalarında unvanlar (Ing., Mag., Dr.) sık kullanılır: "Sehr geehrter Herr <b>Ing.</b> Huber". Almanya'ya göre daha resmî bir hitap beklenir.</span>`,
w:[
["die Tagesordnung","gündem","di: ta:gısordnung","Was steht heute auf der Tagesordnung?","Bugün gündemde ne var?"],
["das Protokoll","tutanak","das proto:kol","Wer schreibt das Protokoll?","Tutanağı kim yazıyor?"],
["ergänzen","eklemek, tamamlamak","ergentsın","Darf ich noch etwas ergänzen?","Bir şey daha ekleyebilir miyim?"],
["ausreden","sözünü bitirmek","ausre:dın","Lassen Sie mich bitte ausreden.","Lütfen sözümü bitirmeme izin verin."],
["zusammenfassen","özetlemek","tsuzamınfasın","Ich fasse kurz zusammen.","Kısaca özetliyorum."],
["übernehmen","üstlenmek","ü:bırne:mın","Ich übernehme diese Aufgabe.","Bu görevi ben üstleniyorum."],
["nachhaken","takip etmek, hatırlatmak","na:hha:kın","Ich wollte kurz nachhaken.","Kısaca hatırlatmak istedim."],
["die Rückmeldung","geri bildirim","di: rükmeldung","Danke für die schnelle Rückmeldung.","Hızlı dönüş için teşekkürler."],
["abstimmen","koordine etmek / oylamak","apştimın","Das stimme ich mit dem Team ab.","Bunu ekiple koordine edeceğim."],
["der Zeitplan","zaman planı","de:r tsaytpla:n","Wir liegen im Zeitplan.","Plana uygun ilerliyoruz."],
["verschieben","ertelemek","ferşi:bın","Der Go-live wird um eine Woche verschoben.","Canlıya geçiş bir hafta erteleniyor."],
["die Rücksprache","danışma, görüşme","di: rükşpra:he","Nach Rücksprache mit dem Kunden …","Müşteriyle görüştükten sonra …"]],
p:[
["Habe ich Sie richtig verstanden, dass das Budget fix ist?","Doğru mu anladım, bütçe sabit mi?"],
["Entschuldigen Sie die späte Rückmeldung.","Geç dönüşüm için kusura bakmayın."],
["Ich möchte kurz bezüglich meiner letzten E-Mail nachhaken.","Son e-postamla ilgili kısaca hatırlatma yapmak istiyorum."],
["Wer übernimmt das und bis wann?","Bunu kim üstleniyor ve ne zamana kadar?"],
["Wir liegen gut im Zeitplan.","Zaman planına göre iyi gidiyoruz."]]},

{t:"İleri bağlayıcılar",s:"zwar … aber, sofern, insofern, wohingegen, sodass",
g:`<p>B2'de iki cümle arasındaki ilişkiyi daha ince kurarsın:</p><div class="tw"><table><tr><th>Bağlaç</th><th>Anlam</th><th>Fiil</th><th>Örnek</th></tr><tr><td>zwar … aber</td><td>gerçi … ama</td><td>2. sıra</td><td><b>Zwar</b> ist es teuer, <b>aber</b> gut.</td></tr><tr><td>sofern / soweit</td><td>…dığı sürece</td><td>sonda</td><td><b>Sofern</b> nichts dagegen spricht, …</td></tr><tr><td>wohingegen / während</td><td>oysa</td><td>sonda</td><td>…, <b>wohingegen</b> Wien teurer ist.</td></tr><tr><td>sodass / so … dass</td><td>öyle ki, böylece</td><td>sonda</td><td>Es regnete, <b>sodass</b> wir blieben.</td></tr><tr><td>indem</td><td>…erek</td><td>sonda</td><td>Man lernt, <b>indem</b> man übt.</td></tr><tr><td>infolgedessen</td><td>bunun sonucunda</td><td>hemen ardından</td><td><b>Infolgedessen</b> stieg der Preis.</td></tr><tr><td>dennoch</td><td>buna rağmen</td><td>hemen ardından</td><td><b>Dennoch</b> bleibe ich optimistisch.</td></tr></table></div><span class="n">Hepsinin listesi, filtre ve testi <b>Bağlaçlar</b> sekmesinde.</span>`,
w:[
["zwar","gerçi","tsva:r","Das ist zwar teuer, aber es lohnt sich.","Gerçi pahalı ama değer."],
["sofern","…dığı sürece","zo:fern","Sofern alles klappt, gehen wir am Montag live.","Her şey yolunda giderse pazartesi canlıya geçiyoruz."],
["soweit","bildiğim kadarıyla / …dığı kadar","zo:vayt","Soweit ich weiß, ist er im Urlaub.","Bildiğim kadarıyla izinde."],
["wohingegen","oysa","vo:hinge:gın","Ich mag Kaffee, wohingegen sie Tee bevorzugt.","Ben kahve severim, oysa o çayı tercih eder."],
["sodass","öyle ki, böylece","zo:das","Der Server fiel aus, sodass niemand arbeiten konnte.","Sunucu çöktü, öyle ki kimse çalışamadı."],
["indem","…erek","inde:m","Wir sparen Zeit, indem wir automatisieren.","Otomasyonla zaman kazanıyoruz."],
["dennoch","buna rağmen","denoh","Es war schwierig, dennoch haben wir es geschafft.","Zordu, buna rağmen başardık."],
["infolgedessen","bunun sonucunda","infolgedesın","Infolgedessen wurde das Projekt gestoppt.","Bunun sonucunda proje durduruldu."],
["folglich","dolayısıyla","folkliş","Die Daten fehlen, folglich ist der Bericht unvollständig.","Veriler eksik, dolayısıyla rapor eksik."],
["hingegen","buna karşın","hinge:gın","Berlin ist groß, Wien hingegen gemütlicher.","Berlin büyük, Viyana ise daha samimi."],
["insofern","bu açıdan","inzo:fern","Insofern hast du recht.","Bu açıdan haklısın."],
["ohnehin","zaten","o:nehin","Ich muss ohnehin in die Stadt.","Zaten şehre gitmem gerekiyor."]],
p:[
["Zwar habe ich wenig Zeit, aber ich helfe dir gern.","Gerçi vaktim az ama sana memnuniyetle yardım ederim."],
["Sofern nichts dagegen spricht, starten wir morgen.","Bir engel yoksa yarın başlıyoruz."],
["Man lernt eine Sprache am besten, indem man sie spricht.","Bir dili en iyi konuşarak öğrenirsin."],
["Das Update war fehlerhaft, sodass wir es zurückrollen mussten.","Güncelleme hatalıydı, bu yüzden geri almak zorunda kaldık."],
["Soweit ich weiß, ist das kein Problem.","Bildiğim kadarıyla bu sorun değil."]]}
]});

LV.push({id:"C1",name:"İleri",units:[
{t:"Akademik ve resmî üslup",s:"Nominalstil, Passiv, Genitiv zincirleri",
g:`<p>C1 yazılı Almancası; isim zincirleri, Passiv ve Genitiv ile yoğun, kişisiz bir üsluptur.</p><div class="tw"><table><tr><th>Günlük</th><th>Resmî / akademik</th></tr><tr><td>Wir haben untersucht, wie …</td><td><b>Untersucht wurde</b>, inwiefern …</td></tr><tr><td>Das zeigt, dass …</td><td><b>Daraus geht hervor</b>, dass …</td></tr><tr><td>Viele Leute meinen …</td><td><b>Es wird vielfach die Auffassung vertreten</b>, …</td></tr><tr><td>Das ist wichtig, weil …</td><td><b>Von zentraler Bedeutung ist</b> dabei …</td></tr><tr><td>Am Ende …</td><td><b>Abschließend lässt sich festhalten</b>, …</td></tr></table></div><span class="n">Yazıda "ich" yerine kişisiz yapılar tercih edilir: <b>Es lässt sich feststellen</b>, <b>Es ist davon auszugehen</b>, <b>Im Folgenden wird … dargestellt</b>.</span>`,
w:[
["hervorgehen","anlaşılmak, ortaya çıkmak","herfo:rge:ın","Aus der Analyse geht hervor, dass die Last zu hoch ist.","Analizden yükün çok yüksek olduğu anlaşılıyor."],
["die Auffassung","görüş, kanı","di: auffasung","Ich bin der Auffassung, dass wir warten sollten.","Beklememiz gerektiği kanısındayım."],
["vertreten","savunmak, temsil etmek","fertre:tın","Diese These wird oft vertreten.","Bu tez sıkça savunuluyor."],
["festhalten","saptamak","festhaltın","Abschließend lässt sich festhalten, dass …","Sonuç olarak şu saptanabilir: …"],
["davon ausgehen","…varsaymak","da:fon ausge:ın","Es ist davon auszugehen, dass die Kosten steigen.","Maliyetlerin artacağı varsayılmalı."],
["darstellen","sunmak, teşkil etmek","da:rştelın","Das stellt ein erhebliches Risiko dar.","Bu ciddi bir risk teşkil ediyor."],
["erheblich","kayda değer, ciddi","erhe:pliş","Die Leistung hat sich erheblich verbessert.","Performans kayda değer biçimde iyileşti."],
["inwiefern","ne ölçüde","invi:fern","Es ist fraglich, inwiefern das zutrifft.","Bunun ne ölçüde doğru olduğu tartışmalı."],
["zutreffen","doğru olmak, geçerli olmak","tsu:trefın","Das trifft nicht auf alle Fälle zu.","Bu her durum için geçerli değil."],
["die Voraussetzung","ön koşul","di: forausetsung","Eine stabile Datenbank ist Voraussetzung.","Stabil bir veritabanı ön koşul."],
["maßgeblich","belirleyici","ma:sge:pliş","Er war maßgeblich am Erfolg beteiligt.","Başarıda belirleyici rol oynadı."],
["hinsichtlich","bakımından","hinziştliş","Hinsichtlich der Sicherheit gibt es Bedenken.","Güvenlik bakımından endişeler var."]],
p:[
["Aus den Daten geht eindeutig hervor, dass die Nutzung gestiegen ist.","Verilerden kullanımın arttığı açıkça anlaşılıyor."],
["Es ist davon auszugehen, dass sich der Trend fortsetzt.","Eğilimin süreceği varsayılmalı."],
["Im Folgenden wird die Vorgehensweise dargestellt.","Aşağıda izlenen yöntem sunulmaktadır."],
["Abschließend lässt sich festhalten, dass das Projekt erfolgreich war.","Sonuç olarak projenin başarılı olduğu söylenebilir."],
["Hinsichtlich der Kosten besteht noch Klärungsbedarf.","Maliyetler bakımından hâlâ netleştirilmesi gereken noktalar var."]]},

{t:"Genişletilmiş partisip yapıları",s:"die von uns entwickelte Lösung",
g:`<p>Almanca, Türkçe gibi uzun sıfat tamlamaları kurar. Artikel ile isim arasına koca bir bilgi bloğu girer:</p><div class="tw"><table><tr><th>İlgi cümlesi</th><th>Partisip yapısı</th></tr><tr><td>die Lösung, die von uns entwickelt wurde</td><td>die <b>von uns entwickelte</b> Lösung</td></tr><tr><td>die Preise, die seit Jahren steigen</td><td>die <b>seit Jahren steigenden</b> Preise</td></tr><tr><td>die Aufgaben, die noch zu erledigen sind</td><td>die <b>noch zu erledigenden</b> Aufgaben</td></tr></table></div><p>Okuma taktiği: artikeli gör → ismi bul (bloğun sonu) → aradaki her şey ismi niteler. Türkçeye çevirirken sıra neredeyse aynı kalır.</p><span class="n"><b>zu + Partizip I</b> = "-ilmesi gereken": die <b>zu prüfenden</b> Dokumente = kontrol edilmesi gereken belgeler.</span>`,
w:[
["entwickelt","geliştirilmiş","entvikılt","Die von uns entwickelte App ist kostenlos.","Bizim geliştirdiğimiz uygulama ücretsiz."],
["zu erledigend","halledilmesi gereken","tsu: erle:digınt","Hier ist die Liste der noch zu erledigenden Aufgaben.","İşte hâlâ halledilmesi gereken görevlerin listesi."],
["zu prüfend","kontrol edilmesi gereken","tsu: prü:fınt","Die zu prüfenden Dokumente liegen bereit.","Kontrol edilecek belgeler hazır."],
["zunehmend","artan / giderek","tsu:ne:mınt","Die zunehmende Digitalisierung verändert alles.","Artan dijitalleşme her şeyi değiştiriyor."],
["bestehend","mevcut","beşte:ınt","Die bestehende Infrastruktur ist veraltet.","Mevcut altyapı eskimiş."],
["vorliegend","eldeki, mevcut","fo:rli:gınt","Der vorliegende Bericht fasst alles zusammen.","Elinizdeki rapor her şeyi özetliyor."],
["genannt","adı geçen","genant","Die oben genannten Punkte sind wichtig.","Yukarıda adı geçen noktalar önemli."],
["erwähnt","bahsedilen","erve:nt","Das erwähnte Problem ist inzwischen gelöst.","Bahsedilen sorun bu arada çözüldü."],
["beauftragt","görevlendirilmiş","beauftra:kt","Die beauftragte Firma beginnt im Mai.","Görevlendirilen firma mayısta başlıyor."],
["anhaltend","süregelen","anhaltınt","Die anhaltende Hitze belastet viele.","Süregelen sıcaklık pek çok kişiyi zorluyor."],
["bewährt","kanıtlanmış, denenmiş","beve:rt","Wir setzen auf bewährte Methoden.","Kanıtlanmış yöntemlere güveniyoruz."],
["veraltet","eskimiş, güncelliğini yitirmiş","feraltıt","Die Software ist völlig veraltet.","Yazılım tamamen eskimiş."]],
p:[
["Die seit Monaten geplante Migration wurde erfolgreich abgeschlossen.","Aylardır planlanan geçiş başarıyla tamamlandı."],
["Die im Vertrag genannten Fristen sind einzuhalten.","Sözleşmede belirtilen sürelere uyulmalıdır."],
["Die noch offenen Fragen klären wir morgen.","Hâlâ açık olan soruları yarın netleştiririz."],
["Das von der Behörde verlangte Formular fehlt noch.","Dairenin istediği form hâlâ eksik."],
["Die vorliegende Analyse basiert auf aktuellen Daten.","Elinizdeki analiz güncel verilere dayanıyor."]]},

{t:"Modal partiküller",s:"ja, doch, eben, halt, wohl, schon, mal, denn",
g:`<p>Modal partiküller cümleye duygu ve ton katar; çevirisi zordur ama anadil konuşmacılarını en çok ayırt eden şeydir.</p><div class="tw"><table><tr><th>Partikül</th><th>İşlev</th><th>Örnek</th></tr><tr><td>ja</td><td>bilinen şey ("ya, malum")</td><td>Das weißt du <b>ja</b>.</td></tr><tr><td>doch</td><td>itiraz, hatırlatma, ısrar</td><td>Komm <b>doch</b> mit! · Das habe ich <b>doch</b> gesagt!</td></tr><tr><td>eben / halt</td><td>değiştirilemez durum</td><td>Das ist <b>eben</b> so.</td></tr><tr><td>wohl</td><td>tahmin</td><td>Er ist <b>wohl</b> krank.</td></tr><tr><td>schon</td><td>güven verme / "gerçi"</td><td>Das klappt <b>schon</b>. · Schön ist es <b>schon</b>, aber …</td></tr><tr><td>mal</td><td>emri yumuşatma</td><td>Schau <b>mal</b>!</td></tr><tr><td>denn</td><td>soruya merak/şaşkınlık</td><td>Was ist <b>denn</b> los?</td></tr><tr><td>eigentlich</td><td>konuyu açma, "acaba"</td><td>Wie heißt du <b>eigentlich</b>?</td></tr></table></div><span class="n">Partiküller vurgusuzdur ve genelde fiilden sonra, cümlenin ortasında durur. Birden fazlası birleşebilir: Komm <b>doch mal</b> vorbei!</span>`,
w:[
["ja","(malum, ya)","ya:","Du weißt ja, wie das ist.","Nasıl olduğunu biliyorsun ya."],
["doch","(ısrar, itiraz)","doh","Das habe ich dir doch gesagt!","Bunu sana söylemiştim ya!"],
["eben","işte öyle","e:bın","Das ist eben so.","İşte böyle."],
["wohl","herhalde","vo:l","Das wird wohl nichts mehr.","Bu iş herhalde olmayacak."],
["schon","merak etme / gerçi","şo:n","Keine Sorge, das klappt schon.","Merak etme, olur."],
["mal","bir (yumuşatma)","ma:l","Kannst du mal kurz kommen?","Bir dakika gelebilir misin?"],
["denn","(sorudaki merak)","den","Was ist denn passiert?","Ne oldu ki?"],
["eigentlich","acaba, aslında","aygıntliş","Was machst du eigentlich beruflich?","Acaba mesleğin ne?"],
["bloß","sadece / (uyarı)","blo:s","Mach das bloß nicht!","Sakın bunu yapma!"],
["ruhig","rahatça","ru:iş","Frag ruhig, wenn du etwas brauchst.","Bir şeye ihtiyacın olursa çekinmeden sor."],
["etwa","(şaşkın soru) yoksa","etva","Bist du etwa schon fertig?","Yoksa bitirdin mi bile?"],
["ohnehin","zaten","o:nehin","Das wollte ich ohnehin machen.","Bunu zaten yapmak istiyordum."]],
p:[
["Komm doch mal vorbei!","Bir uğrasana!"],
["Das ist halt so, da kann man nichts machen.","İşte böyle, yapacak bir şey yok."],
["Wie war das eigentlich mit dem Termin?","Randevu meselesi neydi bu arada?"],
["Das wird schon wieder.","Düzelir, merak etme."],
["Sie ist ja auch erst seit einer Woche hier.","Ne de olsa daha bir haftadır burada."]]},

{t:"Haber dili: Konjunktiv I ve mesafe",s:"Laut Bericht habe …, angeblich, soll",
g:`<p>Gazetecilik dilinde yazar kendini bilgiden uzak tutar. Bunun araçları:</p><div class="tw"><table><tr><th>Araç</th><th>Örnek</th><th>Mesafe</th></tr><tr><td>Konjunktiv I</td><td>Der Sprecher sagte, man <b>habe</b> alles im Griff.</td><td>nötr aktarma</td></tr><tr><td>sollen</td><td>Der CEO <b>soll</b> zurücktreten.</td><td>söylenti</td></tr><tr><td>wollen</td><td>Er <b>will</b> nichts bemerkt haben.</td><td>kişinin kendi iddiası</td></tr><tr><td>angeblich / vermeintlich</td><td>der <b>angebliche</b> Täter</td><td>şüpheli</td></tr><tr><td>Konjunktiv II</td><td>Sie sagten, sie <b>hätten</b> nichts gewusst.</td><td>Konj. I = Präsens ise</td></tr></table></div><p>Aktarma fiilleri: äußern, betonen, einräumen (kabul etmek), bestreiten (inkâr etmek), versichern (temin etmek), dementieren (yalanlamak).</p><span class="n"><b>vermeintlich</b> = "sanılan ama aslında öyle olmayan": der vermeintliche Fehler = hata sanılan şey.</span>`,
w:[
["einräumen","kabul etmek (itiraf)","aynroymın","Der Minister räumte ein, Fehler gemacht zu haben.","Bakan hata yaptığını kabul etti."],
["bestreiten","inkâr etmek","beştraytın","Er bestreitet, davon gewusst zu haben.","Bundan haberi olduğunu inkâr ediyor."],
["versichern","temin etmek","ferzişırn","Die Firma versichert, die Daten seien sicher.","Şirket verilerin güvende olduğunu temin ediyor."],
["dementieren","yalanlamak","dementi:rın","Die Regierung dementierte die Berichte.","Hükümet haberleri yalanladı."],
["äußern","dile getirmek","oysırn","Er äußerte sich nicht zu den Vorwürfen.","Suçlamalar hakkında açıklama yapmadı."],
["der Vorwurf","suçlama","de:r fo:rvurf","Die Vorwürfe wiegen schwer.","Suçlamalar ağır."],
["vermeintlich","sanılan","fermayntliş","Der vermeintliche Fehler war ein Feature.","Hata sanılan şey bir özellikti."],
["mutmaßlich","olduğu tahmin edilen","mutma:sliş","Der mutmaßliche Grund war ein Stromausfall.","Muhtemel sebep bir elektrik kesintisiydi."],
["die Stellungnahme","resmî açıklama","di: ştelungna:me","Die Firma hat eine Stellungnahme veröffentlicht.","Şirket resmî bir açıklama yayımladı."],
["laut eigenen Angaben","kendi beyanına göre","laut aygının anga:bın","Laut eigenen Angaben war er zu Hause.","Kendi beyanına göre evdeymiş."],
["zufolge","…e göre","tsufolge","Ersten Berichten zufolge gab es keine Verletzten.","İlk haberlere göre yaralı yok."],
["die Schlagzeile","manşet","di: şla:ktsayle","Das war gestern in allen Schlagzeilen.","Bu dün bütün manşetlerdeydi."]],
p:[
["Der Konzern räumte ein, die Daten nicht ausreichend geschützt zu haben.","Şirket verileri yeterince korumadığını kabul etti."],
["Einem Sprecher zufolge sei der Schaden gering.","Bir sözcüye göre zarar küçükmüş."],
["Der Politiker will von nichts gewusst haben.","Politikacı hiçbir şeyden haberi olmadığını iddia ediyor."],
["Die Vorwürfe wurden umgehend dementiert.","Suçlamalar derhâl yalanlandı."],
["Zu den Gerüchten wollte sich niemand äußern.","Kimse söylentiler hakkında açıklama yapmak istemedi."]]},

{t:"Cümle yapısı: Vorfeld, Satzklammer, Nachfeld",s:"vurgu için öğe sırası",
g:`<p>Almanca cümle bir <b>çerçeve</b>dir (Satzklammer): çekimli fiil 2. sırada, diğer fiil parçaları sonda. Aradaki öğelerin sırası vurguyu belirler.</p><div class="tw"><table><tr><th>Vorfeld</th><th>Fiil 1</th><th>Mittelfeld</th><th>Fiil 2</th><th>Nachfeld</th></tr><tr><td>Gestern</td><td>habe</td><td>ich dem Kunden das Konzept</td><td>gezeigt</td><td></td></tr><tr><td>Das Konzept</td><td>habe</td><td>ich gestern dem Kunden</td><td>gezeigt</td><td></td></tr><tr><td>Ich</td><td>habe</td><td>mit ihm</td><td>gesprochen</td><td>über das Budget.</td></tr></table></div><p>Mittelfeld kuralı (TeKaMoLo): <b>Te</b>mporal (ne zaman) – <b>Ka</b>usal (neden) – <b>Mo</b>dal (nasıl) – <b>Lo</b>kal (nerede): Ich fahre <b>morgen wegen des Termins mit dem Zug nach Wien</b>.</p><span class="n">Vorfeld'e (başa) konulan öğe vurgulanır. Yeni ve önemli bilgi genelde Mittelfeld'in <b>sonuna</b>, fiile yakın konur.</span>`,
w:[
["das Vorfeld","cümle başı (1. pozisyon)","das fo:rfelt","Im Vorfeld steht oft das Thema.","Cümle başında genellikle konu durur."],
["betonen","vurgulamak","beto:nın","Mit der Wortstellung kann man etwas betonen.","Sözcük dizilimiyle bir şey vurgulanabilir."],
["die Reihenfolge","sıra","di: rayınfolge","Die Reihenfolge ist wichtig.","Sıra önemli."],
["zunächst","ilk olarak","tsu:ne:şst","Zunächst prüfen wir die Logs.","İlk olarak logları kontrol ediyoruz."],
["anschließend","ardından","anşli:sınt","Anschließend starten wir das System neu.","Ardından sistemi yeniden başlatıyoruz."],
["dabei","bu sırada, bunda","dabay","Dabei ist ein Fehler aufgetreten.","Bu sırada bir hata oluştu."],
["somit","böylece","zo:mit","Somit ist das Problem gelöst.","Böylece sorun çözüldü."],
["zudem","ayrıca","tsude:m","Zudem fehlen noch einige Daten.","Ayrıca bazı veriler hâlâ eksik."],
["vielmehr","daha ziyade","fi:lme:r","Es geht nicht um Geld, vielmehr um Zeit.","Mesele para değil, daha ziyade zaman."],
["keineswegs","asla, hiç de","kaynısve:ks","Das ist keineswegs selbstverständlich.","Bu hiç de olağan değil."],
["durchaus","pekâlâ, tamamen","durşaus","Das ist durchaus möglich.","Bu pekâlâ mümkün."],
["lediglich","yalnızca","le:digliş","Es fehlt lediglich eine Unterschrift.","Yalnızca bir imza eksik."]],
p:[
["Gerade das hatte ich nicht erwartet.","Tam da bunu beklemiyordum."],
["Morgen fahre ich wegen des Termins mit dem Zug nach Wien.","Yarın randevu nedeniyle trenle Viyana'ya gidiyorum."],
["Es geht dabei keineswegs nur um die Kosten.","Burada mesele hiç de yalnızca maliyet değil."],
["Zunächst analysieren wir die Ursache, anschließend beheben wir den Fehler.","Önce nedeni analiz ediyoruz, ardından hatayı gideriyoruz."],
["Das ist durchaus eine Überlegung wert.","Bu pekâlâ düşünülmeye değer."]]},

{t:"Kelime türetme",s:"un-, miss-, -los, -haft, -mäßig, -weise",
g:`<p>Önek ve sonekleri tanımak C1 kelime dağarcığını hızla büyütür:</p><div class="tw"><table><tr><th>Ek</th><th>Anlam</th><th>Örnek</th></tr><tr><td>un-</td><td>olumsuzluk</td><td>klar → <b>un</b>klar</td></tr><tr><td>miss-</td><td>yanlış, kötü</td><td>verstehen → <b>miss</b>verstehen</td></tr><tr><td>-los</td><td>-sız</td><td>Arbeit → arbeits<b>los</b></td></tr><tr><td>-haft</td><td>-ımsı, özelliğinde</td><td>Fehler → fehler<b>haft</b></td></tr><tr><td>-mäßig</td><td>-e göre, bakımından</td><td>Zeit → zeit<b>mäßig</b></td></tr><tr><td>-weise</td><td>-ce, şekilde</td><td>Beispiel → beispiels<b>weise</b></td></tr><tr><td>-reich / -arm</td><td>çok / az içeren</td><td>erfolg<b>reich</b>, fett<b>arm</b></td></tr><tr><td>-fähig</td><td>-ebilen</td><td>leistungs<b>fähig</b></td></tr></table></div><span class="n">Birleşik isimlerde son kelime cinsiyeti belirler: das Haus + <b>die Tür</b> = <b>die</b> Haustür. Araya sıkça <b>-s-</b> girer: Arbeit<b>s</b>platz.</span>`,
w:[
["unklar","belirsiz","unkla:r","Die Ursache ist noch unklar.","Neden hâlâ belirsiz."],
["missverstehen","yanlış anlamak","misferşte:ın","Sie haben mich missverstanden.","Beni yanlış anladınız."],
["das Missverständnis","yanlış anlaşılma","das misferştentnis","Das war ein Missverständnis.","Bu bir yanlış anlaşılmaydı."],
["fehlerhaft","hatalı","fe:lırhaft","Die Daten sind fehlerhaft.","Veriler hatalı."],
["zeitmäßig","zaman açısından","tsaytme:siş","Zeitmäßig wird es knapp.","Zaman açısından sıkışık olacak."],
["beispielsweise","örneğin","bayşpi:lsvayze","Beispielsweise könnten wir die Tabelle archivieren.","Örneğin tabloyu arşivleyebiliriz."],
["möglicherweise","muhtemelen","mö:klişırvayze","Möglicherweise liegt es am Speicher.","Muhtemelen bellekten kaynaklanıyor."],
["leistungsfähig","güçlü, verimli","laystungsfe:iş","Der neue Server ist sehr leistungsfähig.","Yeni sunucu çok güçlü."],
["erfolgreich","başarılı","erfolkrayş","Die Migration war erfolgreich.","Geçiş başarılıydı."],
["ratlos","çaresiz, ne yapacağını bilmeyen","ra:tlo:s","Wir waren zunächst ratlos.","İlk başta ne yapacağımızı bilemedik."],
["sinnvoll","anlamlı, mantıklı","zinfol","Das ist eine sinnvolle Lösung.","Bu mantıklı bir çözüm."],
["fragwürdig","şüpheli, sorgulanabilir","fra:kvürdiş","Diese Methode ist fragwürdig.","Bu yöntem sorgulanabilir."]],
p:[
["Möglicherweise handelt es sich um ein Missverständnis.","Muhtemelen bir yanlış anlaşılma söz konusu."],
["Zeitmäßig schaffen wir das nicht vor Freitag.","Zaman açısından bunu cumadan önce yetiştiremeyiz."],
["Das ist zwar sinnvoll, aber kostenmäßig schwierig.","Bu mantıklı ama maliyet açısından zor."],
["Die Daten waren teilweise fehlerhaft.","Veriler kısmen hatalıydı."],
["Ich war völlig ratlos.","Tamamen çaresizdim."]]},

{t:"Deyimler ve kalıp ifadeler",s:"Daumen drücken, auf dem Laufenden halten",
g:`<p>C1'de deyimleri anlamak ve yerinde kullanmak beklenir:</p><div class="tw"><table><tr><th>Deyim</th><th>Kelimesi kelimesine</th><th>Anlamı</th></tr><tr><td>Ich drücke dir die Daumen.</td><td>Başparmaklarını sıkıyorum.</td><td>Şans diliyorum.</td></tr><tr><td>Das ist nicht mein Bier.</td><td>Bu benim biram değil.</td><td>Beni ilgilendirmez.</td></tr><tr><td>Ich verstehe nur Bahnhof.</td><td>Sadece istasyon anlıyorum.</td><td>Hiçbir şey anlamıyorum.</td></tr><tr><td>Da steckt der Wurm drin.</td><td>İçinde kurt var.</td><td>Bir terslik var.</td></tr><tr><td>Tomaten auf den Augen haben</td><td>Gözünde domates olmak</td><td>Göreni görmemek</td></tr><tr><td>auf dem Laufenden halten</td><td>Akışta tutmak</td><td>Haberdar etmek</td></tr><tr><td>unter vier Augen</td><td>Dört göz altında</td><td>Baş başa</td></tr></table></div><span class="n">İş e-postalarında en kullanışlı olan: <b>Ich halte Sie auf dem Laufenden</b> (Sizi gelişmelerden haberdar ederim).</span>`,
w:[
["die Daumen drücken","şans dilemek","di: daumın drükın","Ich drücke dir die Daumen für morgen!","Yarın için şans diliyorum!"],
["auf dem Laufenden halten","haberdar etmek","auf de:m laufındın haltın","Ich halte Sie auf dem Laufenden.","Sizi gelişmelerden haberdar ederim."],
["unter vier Augen","baş başa","untır fi:r augın","Können wir unter vier Augen sprechen?","Baş başa konuşabilir miyiz?"],
["nur Bahnhof verstehen","hiçbir şey anlamamak","nu:r ba:nho:f ferşte:ın","Bei dem Vortrag habe ich nur Bahnhof verstanden.","Sunumdan hiçbir şey anlamadım."],
["der Wurm drin sein","bir terslik olmak","de:r vurm drin zayn","In dem Projekt ist der Wurm drin.","Bu projede bir terslik var."],
["auf der Hand liegen","apaçık olmak","auf de:r hant li:gın","Die Lösung liegt auf der Hand.","Çözüm apaçık ortada."],
["ins Fettnäpfchen treten","pot kırmak","ins fetnepfşın tre:tın","Mit der Frage bin ich ins Fettnäpfchen getreten.","Bu soruyla pot kırdım."],
["den Nagel auf den Kopf treffen","tam üstüne basmak","de:n na:gıl auf de:n kopf trefın","Damit hast du den Nagel auf den Kopf getroffen.","Tam üstüne bastın."],
["unter Druck stehen","baskı altında olmak","untır druk şte:ın","Das Team steht unter großem Druck.","Ekip büyük baskı altında."],
["etwas auf die lange Bank schieben","ertelemek, sürüncemede bırakmak","etvas auf di: lange bank şi:bın","Wir sollten das nicht auf die lange Bank schieben.","Bunu sürüncemede bırakmamalıyız."],
["Hand in Hand gehen","el ele gitmek","hant in hant ge:ın","Qualität und Sicherheit gehen Hand in Hand.","Kalite ve güvenlik el ele gider."],
["Schwein haben","şanslı olmak","şvayn ha:bın","Da hast du aber Schwein gehabt!","Şanslıymışsın ama!"]],
p:[
["Ich drücke dir ganz fest die Daumen!","Sana çok şans diliyorum!"],
["Bitte halten Sie mich auf dem Laufenden.","Lütfen beni gelişmelerden haberdar edin."],
["Das ist nicht mein Bier.","Beni ilgilendirmez."],
["Da haben wir noch mal Glück gehabt.","Bu sefer de şansımız yaver gitti."],
["Lass uns das nicht auf die lange Bank schieben.","Bunu sürüncemede bırakmayalım."]]},

{t:"Akademik bağlaçlar",s:"demzufolge, insofern als, wenngleich, zumal",
g:`<p>C1 yazılı dilinin bağlaçları:</p><div class="tw"><table><tr><th>Bağlaç</th><th>Anlam</th><th>Fiil</th></tr><tr><td>wenngleich / obgleich</td><td>-diği hâlde (resmî obwohl)</td><td>sonda</td></tr><tr><td>zumal</td><td>üstelik … olduğundan</td><td>sonda</td></tr><tr><td>insofern als / insoweit als</td><td>…dığı ölçüde</td><td>sonda</td></tr><tr><td>demzufolge / demnach</td><td>buna göre</td><td>hemen ardından</td></tr><tr><td>infolgedessen</td><td>bunun sonucu olarak</td><td>hemen ardından</td></tr><tr><td>indes / indessen</td><td>bununla birlikte / bu sırada</td><td>hemen ardından</td></tr><tr><td>nichtsdestotrotz</td><td>her şeye rağmen</td><td>hemen ardından</td></tr><tr><td>geschweige denn</td><td>bırakın … -ı</td><td>—</td></tr></table></div><span class="n"><b>zumal</b> sebebe ek bir gerekçe katar: Ich nehme das Angebot an, <b>zumal</b> das Gehalt gut ist = Teklifi kabul ediyorum, üstelik maaş da iyi.</span>`,
w:[
["wenngleich","-diği hâlde","venglayş","Wenngleich die Kosten hoch sind, lohnt sich die Investition.","Maliyetler yüksek olsa da yatırım değer."],
["obgleich","-e rağmen (resmî)","opglayş","Obgleich er müde war, arbeitete er weiter.","Yorgun olmasına rağmen çalışmaya devam etti."],
["zumal","üstelik … olduğundan","tsuma:l","Ich bleibe zu Hause, zumal es regnet.","Evde kalıyorum, üstelik yağmur da yağıyor."],
["insofern als","…dığı ölçüde","inzo:fern als","Das ist insofern problematisch, als niemand zuständig ist.","Kimse sorumlu olmadığı ölçüde bu sorunlu."],
["demzufolge","buna göre","de:mtsufolge","Demzufolge müssen wir umplanen.","Buna göre planı değiştirmeliyiz."],
["demnach","buna göre","de:mna:h","Demnach ist die Frist bereits abgelaufen.","Buna göre süre çoktan dolmuş."],
["indes","bununla birlikte","indes","Die Zahlen sind gut, indes bleibt das Risiko.","Rakamlar iyi, bununla birlikte risk sürüyor."],
["nichtsdestotrotz","her şeye rağmen","niştsdestotrots","Nichtsdestotrotz halten wir am Plan fest.","Her şeye rağmen plana sadık kalıyoruz."],
["geschweige denn","bırakın … -ı","geşvayge den","Er spricht kaum Englisch, geschweige denn Deutsch.","Zar zor İngilizce konuşuyor, bırakın Almancayı."],
["mithin","dolayısıyla (resmî)","mithin","Die Daten sind unvollständig, mithin nicht verwertbar.","Veriler eksik, dolayısıyla kullanılamaz."],
["wohingegen","oysa","vo:hinge:gın","Die alte Version war stabil, wohingegen die neue abstürzt.","Eski sürüm stabildi, oysa yenisi çöküyor."],
["ungeachtet","-e bakmaksızın","unge:ahtıt","Ungeachtet der Kritik wurde das Gesetz beschlossen.","Eleştirilere bakılmaksızın yasa kabul edildi."]],
p:[
["Wenngleich das Ergebnis positiv ist, bleiben Fragen offen.","Sonuç olumlu olsa da bazı sorular açık kalıyor."],
["Ich nehme das Angebot an, zumal die Firma in Wien sitzt.","Teklifi kabul ediyorum, üstelik şirket Viyana'da."],
["Demzufolge ist eine Anpassung der Strategie erforderlich.","Buna göre stratejinin uyarlanması gerekiyor."],
["Er hat keine Zeit zum Lesen, geschweige denn zum Schreiben.","Okumaya vakti yok, bırakın yazmayı."],
["Nichtsdestotrotz sollten wir die Risiken im Blick behalten.","Her şeye rağmen riskleri göz önünde tutmalıyız."]]},

{t:"Tartışma ve müzakere",s:"einwenden, zu bedenken geben, Kompromiss",
g:`<p>C1 düzeyinde fikir tartışmak, itiraz etmek ve uzlaşmak:</p><div class="tw"><table><tr><th>İşlev</th><th>Kalıp</th></tr><tr><td>İtiraz</td><td>Dagegen ließe sich einwenden, dass … · Ich gebe zu bedenken, dass …</td></tr><tr><td>Kısmen katılma</td><td>Das ist ein berechtigter Einwand, allerdings …</td></tr><tr><td>Vurgulama</td><td>Entscheidend ist doch, dass … · Man darf nicht außer Acht lassen, dass …</td></tr><tr><td>Uzlaşma</td><td>Könnten wir uns darauf einigen, dass …? · Ich komme Ihnen entgegen, indem …</td></tr><tr><td>Konuya dönme</td><td>Um auf den Punkt zurückzukommen …</td></tr><tr><td>Netleştirme</td><td>Worauf ich hinauswill, ist …</td></tr></table></div><span class="n">Almanca konuşulan iş kültürüne göre doğrudan itiraz kaba sayılmaz; ama Konjunktiv II ile yumuşatılması (<b>ließe sich</b>, <b>wäre es nicht sinnvoller</b>) çok profesyonel durur.</span>`,
w:[
["einwenden","itiraz etmek","aynvendın","Dagegen ließe sich einwenden, dass es teuer ist.","Buna pahalı olduğu itirazı yapılabilir."],
["der Einwand","itiraz","de:r aynvant","Das ist ein berechtigter Einwand.","Bu haklı bir itiraz."],
["zu bedenken geben","dikkate sunmak","tsu: bedenkın ge:bın","Ich gebe zu bedenken, dass die Zeit knapp ist.","Zamanın kısıtlı olduğunu hatırlatmak isterim."],
["außer Acht lassen","göz ardı etmek","ausır aht lasın","Wir dürfen die Kosten nicht außer Acht lassen.","Maliyetleri göz ardı edemeyiz."],
["sich einigen","anlaşmak, uzlaşmak","ziş aynigın","Wir haben uns auf einen Termin geeinigt.","Bir tarihte uzlaştık."],
["der Kompromiss","uzlaşma","de:r kompromis","Das ist ein fairer Kompromiss.","Bu adil bir uzlaşma."],
["entgegenkommen","orta yolu bulmak, jest yapmak","entge:gınkomın","Wir kommen Ihnen beim Preis entgegen.","Fiyatta size jest yapıyoruz."],
["hinauswollen","bir şeyi kastetmek","hinausvolın","Worauf willst du hinaus?","Ne demek istiyorsun?"],
["berechtigt","haklı, yerinde","bereştişt","Ihre Kritik ist berechtigt.","Eleştiriniz yerinde."],
["abwägen","tartmak, değerlendirmek","apve:gın","Wir müssen Vor- und Nachteile abwägen.","Artıları ve eksileri tartmalıyız."],
["überzeugend","ikna edici","ü:bırtsoygınt","Das Argument ist überzeugend.","Argüman ikna edici."],
["verhandeln","müzakere etmek","ferhandıln","Wir verhandeln noch über den Preis.","Fiyatı hâlâ müzakere ediyoruz."]],
p:[
["Das ist ein berechtigter Einwand, allerdings sehe ich das etwas anders.","Bu haklı bir itiraz, ancak ben biraz farklı görüyorum."],
["Man darf nicht außer Acht lassen, dass das System veraltet ist.","Sistemin eskimiş olduğu göz ardı edilmemeli."],
["Könnten wir uns darauf einigen, die Entscheidung zu vertagen?","Kararı ertelemekte uzlaşabilir miyiz?"],
["Worauf ich hinauswill, ist Folgendes:","Söylemek istediğim şu:"],
["Wäre es nicht sinnvoller, zuerst zu testen?","Önce test etmek daha mantıklı olmaz mıydı?"]]},

{t:"Resmî yazışma",s:"Hiermit, beiliegend, umgehend, verbindlich",
g:`<p>Kurumlara, mülk sahiplerine ve resmî dairelere yazılan mektupların kalıpları:</p><div class="tw"><table><tr><th>Bölüm</th><th>Kalıp</th></tr><tr><td>Konu (Betreff)</td><td>Betreff: Kündigung des Mietvertrags</td></tr><tr><td>Giriş</td><td><b>Hiermit</b> kündige ich … · Bezugnehmend auf Ihr Schreiben vom …</td></tr><tr><td>Ek</td><td><b>Beiliegend</b> / Anbei erhalten Sie …</td></tr><tr><td>Talep</td><td>Ich bitte Sie, … <b>umgehend</b> zu …</td></tr><tr><td>Son tarih</td><td>… bis spätestens 30.11.</td></tr><tr><td>Onay isteme</td><td>Bitte bestätigen Sie mir den Eingang dieses Schreibens.</td></tr><tr><td>Kapanış</td><td>Für Rückfragen stehe ich Ihnen gern zur Verfügung. Mit freundlichen Grüßen</td></tr></table></div><span class="n">Almanca konuşulan ülkelerde resmî işler hâlâ büyük ölçüde mektup ve imzalı belgeyle yürür. "Hiermit" ile başlayan cümle, belgenin kendisinin hukuki işlem olduğunu gösterir.</span>`,
w:[
["hiermit","işbu (belge) ile","hi:rmit","Hiermit kündige ich meinen Vertrag.","İşbu yazıyla sözleşmemi feshediyorum."],
["beiliegend","ekte","bayli:gınt","Beiliegend sende ich Ihnen die Unterlagen.","Belgeleri ekte gönderiyorum."],
["anbei","ekte","anbay","Anbei finden Sie meinen Lebenslauf.","Özgeçmişimi ekte bulabilirsiniz."],
["umgehend","derhâl","umge:ınt","Bitte antworten Sie umgehend.","Lütfen derhâl cevap verin."],
["verbindlich","bağlayıcı","ferbintliş","Das Angebot ist verbindlich.","Teklif bağlayıcıdır."],
["spätestens","en geç","şpe:tıstıns","Bitte zahlen Sie spätestens bis Montag.","Lütfen en geç pazartesiye kadar ödeyin."],
["bezugnehmend auf","…e atfen","betsu:kne:mınt auf","Bezugnehmend auf unser Telefonat …","Telefon görüşmemize atfen …"],
["der Eingang","alındı, giriş","de:r ayngang","Bitte bestätigen Sie den Eingang.","Lütfen alındığını onaylayın."],
["kündigen","feshetmek","kündigın","Ich möchte fristgerecht kündigen.","Süresinde fesih yapmak istiyorum."],
["fristgerecht","süresinde","fristgereşt","Die Zahlung erfolgte fristgerecht.","Ödeme süresinde yapıldı."],
["die Rückfrage","ek soru","di: rükfra:ge","Für Rückfragen stehe ich gern zur Verfügung.","Ek sorularınız için hazırım."],
["der Widerspruch","itiraz (resmî)","de:r vi:dırşpruh","Ich lege Widerspruch gegen den Bescheid ein.","Karara itiraz ediyorum."]],
p:[
["Hiermit kündige ich den Mietvertrag fristgerecht zum 31. Januar.","İşbu yazıyla kira sözleşmesini 31 Ocak itibarıyla süresinde feshediyorum."],
["Bezugnehmend auf Ihr Schreiben vom 3. März teile ich Ihnen Folgendes mit:","3 Mart tarihli yazınıza atfen size şunu bildiririm:"],
["Bitte bestätigen Sie mir den Eingang dieses Schreibens.","Lütfen bu yazının alındığını bana teyit edin."],
["Anbei erhalten Sie die gewünschten Unterlagen.","İstenen belgeleri ekte bulabilirsiniz."],
["Für Rückfragen stehe ich Ihnen jederzeit gern zur Verfügung.","Ek sorularınız için her zaman hizmetinizdeyim."]]},

{t:"Avusturya Almancası ve üslup",s:"Jänner, Paradeiser, Grüß Gott, Matura",
g:`<p>Avusturya'da standart Almanca biraz farklıdır (Österreichisches Deutsch). Viyana'da günlük hayatta şu farkları duyarsın:</p><div class="tw"><table><tr><th>Almanya</th><th>Avusturya</th><th>Anlam</th></tr><tr><td>Januar</td><td>Jänner</td><td>ocak</td></tr><tr><td>Tomate</td><td>Paradeiser</td><td>domates</td></tr><tr><td>Kartoffel</td><td>Erdapfel</td><td>patates</td></tr><tr><td>Sahne</td><td>Schlagobers</td><td>krema</td></tr><tr><td>Brötchen</td><td>Semmel</td><td>küçük ekmek</td></tr><tr><td>Abitur</td><td>Matura</td><td>lise bitirme sınavı</td></tr><tr><td>Tschüss</td><td>Baba / Servus / Pfiat di</td><td>hoşça kal</td></tr><tr><td>Ich habe gesessen</td><td>Ich bin gesessen</td><td>oturdum</td></tr></table></div><p>Avusturya'da akademik ve mesleki unvanlar (Mag., Dipl.-Ing., Dr.) resmî yazışmada ve hitapta kullanılır: "Grüß Gott, Frau Magister!".</p><span class="n">Viyana kafelerinde: <b>ein Melange</b> (sütlü kahve), <b>ein Verlängerter</b> (uzatılmış espresso), <b>Zahlen, bitte!</b>. Garsona <b>Herr Ober</b> denir.</span>`,
w:[
["der Jänner","ocak (Avusturya)","de:r yenır","Im Jänner ist es in Wien kalt.","Ocakta Viyana soğuktur."],
["der Paradeiser","domates (Avusturya)","de:r paradayzır","Ein Kilo Paradeiser, bitte.","Bir kilo domates lütfen."],
["der Erdapfel","patates (Avusturya)","de:r e:rdapfıl","Erdäpfelsalat passt gut zum Schnitzel.","Patates salatası şnitzelle iyi gider."],
["das Schlagobers","krema (Avusturya)","das şla:ko:bırs","Einen Kaffee mit Schlagobers, bitte.","Kremalı bir kahve lütfen."],
["die Semmel","küçük ekmek (Avusturya)","di: zemıl","Zwei Semmeln zum Frühstück.","Kahvaltı için iki küçük ekmek."],
["die Matura","lise bitirme sınavı","di: matu:ra","Sie hat die Matura mit Auszeichnung bestanden.","Lise bitirme sınavını dereceyle geçti."],
["Servus","selam / hoşça kal (samimi)","zervus","Servus, wie geht's?","Selam, nasılsın?"],
["Grüß Gott","merhaba (resmî, Avusturya)","grü:s got","Grüß Gott, was darf es sein?","Merhaba, ne arzu edersiniz?"],
["die Melange","sütlü köpüklü kahve","di: melanj","Eine Melange und ein Stück Sachertorte, bitte.","Bir melange ve bir dilim Sacher pastası lütfen."],
["das Sackerl","poşet (Avusturya)","das zakırl","Brauchen Sie ein Sackerl?","Poşet ister misiniz?"],
["der Meldezettel","adres kayıt belgesi","de:r meldetsetıl","Für das Konto brauche ich den Meldezettel.","Hesap için adres kayıt belgesine ihtiyacım var."],
["die Trafik","tütün-gazete bayii","di: trafik","Fahrscheine bekommt man auch in der Trafik.","Biletleri bayiden de alabilirsin."]],
p:[
["Grüß Gott, ich hätte gern eine Melange.","Merhaba, bir melange alabilir miyim."],
["Brauchen Sie ein Sackerl?","Poşet ister misiniz?"],
["Ich muss mich innerhalb von drei Tagen beim Magistrat melden.","Üç gün içinde belediyeye adres kaydı yaptırmalıyım."],
["Servus, wir sehen uns morgen!","Selam, yarın görüşürüz!"],
["In Wien sagt man Jänner statt Januar.","Viyana'da Januar yerine Jänner denir."]]}
]});

