CONJ_THEORY.push(
{h:"1 · Sıra 0 bağlaçları (ADUSO)",p:"Fiil sırasını <b>hiç değiştirmez</b>, bağlaçtan sonra cümle normal sırayla devam eder: <b>A</b>ber, <b>D</b>enn, <b>U</b>nd, <b>S</b>ondern, <b>O</b>der.",t:[["Bağlaç","Anlam","Örnek"],["aber","ama","Es ist alt, <b>aber</b> es <b>funktioniert</b>."],["denn","çünkü","Ich gehe, <b>denn</b> ich <b>bin</b> müde."],["und","ve","Ich koche <b>und</b> sie <b>deckt</b> den Tisch."],["sondern","bilakis","Nicht heute, <b>sondern</b> morgen."],["oder","veya","Kommst du <b>oder</b> bleibst du?"]],tip:"aber, denn ve sondern'den önce <b>her zaman virgül</b> konur; und ve oder'den önce genelde konmaz."},
{h:"2 · Zarf bağlaçlar (fiil hemen sonra)",p:"deshalb, deswegen, trotzdem, dann, danach, sonst, außerdem, also, daher, dennoch, folglich… Bunlar cümlenin ilk öğesi sayılır, bu yüzden <b>çekimli fiil hemen ardından</b> gelir (devrik yapı).",t:[["Doğru","Yanlış"],["…, <b>deshalb bleibe ich</b> hier.","…, deshalb ich bleibe hier. ✗"],["<b>Trotzdem gehen wir</b> raus.","Trotzdem wir gehen raus. ✗"]],tip:"Zarf bağlaç cümlenin ortasına da gidebilir: Ich bleibe <b>deshalb</b> hier."},
{h:"3 · Yan cümle bağlaçları (fiil sonda)",p:"weil, dass, wenn, ob, als, obwohl, damit, bevor, nachdem, während, sobald, falls, sodass, indem, da… Yan cümlede <b>çekimli fiil en sona</b> gider.",list:["Yan cümle ile ana cümle arasında <b>her zaman virgül</b>: Ich weiß<b>,</b> dass du recht hast.","Yan cümle başta ise ana cümle <b>fiille</b> başlar: Wenn ich Zeit habe<b>, komme</b> ich. (fiil–virgül–fiil)","Perfekt'te yardımcı fiil sonda: …, weil ich lange <b>gearbeitet habe</b>.","Ayrılabilen fiil birleşir: …, wenn der Zug <b>ankommt</b>.","Modal fiil en sonda: …, weil ich arbeiten <b>muss</b>."]},
{h:"4 · Aynı anlam, üç yapı",t:[["Yapı","Örnek"],["denn (sıra 0)","Ich bleibe zu Hause, <b>denn</b> ich bin krank."],["deshalb (fiil hemen sonra)","Ich bin krank, <b>deshalb</b> bleibe ich zu Hause."],["weil (fiil sonda)","Ich bleibe zu Hause, <b>weil</b> ich krank bin."],["wegen (+ isim)","<b>Wegen</b> meiner Krankheit bleibe ich zu Hause."]],tip:"Zıtlıkta da aynı üçlü: <b>aber</b> / <b>trotzdem</b> / <b>obwohl</b> / <b>trotz</b> + Genitiv."},
{h:"5 · Cümle mi, isim mi?",t:[["Anlam","+ yan cümle","+ isim (edat)"],["rağmen","obwohl, obgleich","trotz + Genitiv"],["yüzünden","weil, da","wegen, aufgrund + Genitiv"],["sırasında","während","während + Genitiv"],["önce / sonra","bevor / nachdem","vor / nach + Dativ"],["için (amaç)","damit, um … zu","zu + Dativ, für + Akk."],["-den beri","seitdem","seit + Dativ"]],tip:"Resmî yazıda isim yapısı tercih edilir: <b>Nach Abschluss</b> der Tests … (Nachdem die Tests abgeschlossen sind …)."},
{h:"6 · Eşli bağlaçlar",t:[["Çift","Örnek"],["sowohl … als auch","<b>Sowohl</b> Ali <b>als auch</b> Can kamen."],["weder … noch","<b>Weder</b> er <b>noch</b> ich wussten es."],["entweder … oder","<b>Entweder</b> du rufst an <b>oder</b> du schreibst."],["nicht nur … sondern auch","<b>Nicht nur</b> billig, <b>sondern auch</b> gut."],["zwar … aber","<b>Zwar</b> teuer, <b>aber</b> gut."],["je … desto","<b>Je</b> mehr ich lese, <b>desto</b> mehr verstehe ich."]],tip:"je … desto: je'li kısımda fiil sonda, desto'lu kısımda fiil hemen karşılaştırmadan sonra."},
{h:"7 · zu + mastar yapıları",p:"um … zu, ohne … zu, statt … zu, ve birçok fiil/sıfattan sonra (Es ist wichtig, … zu …). Özne yazılmaz, iki cümlenin öznesi aynı olmalıdır.",list:["Ayrılabilen fiilde zu araya girer: um früh <b>aufzustehen</b>.","Modal yapı yok: um arbeiten <b>zu können</b>.","Özneler farklıysa yan cümle: <b>damit</b>, <b>ohne dass</b>, <b>anstatt dass</b>."]}
);

window.X={};
X["A1-1"]=[["Hallo, ich bin Mahsun.","Merhaba, ben Mahsun."],["Guten Morgen, wie geht es Ihnen?","Günaydın, nasılsınız?"],["Danke, sehr gut.","Teşekkürler, çok iyi."],["Bitte, gern geschehen.","Rica ederim."],["Entschuldigung, wie bitte?","Affedersiniz, efendim?"],["Ja, gern.","Evet, memnuniyetle."],["Nein, danke.","Hayır, teşekkürler."],["Guten Abend, Frau Weber.","İyi akşamlar Bayan Weber."],["Tschüss, bis morgen!","Hoşça kal, yarın görüşürüz!"],["Gute Nacht, schlaf gut!","İyi geceler, iyi uykular!"],["Auf Wiedersehen, Herr Schmidt.","Hoşça kalın Bay Schmidt."],["Wie geht's? — Es geht.","Nasılsın? — İdare eder."]];
