X["A1-15"]=[["Ich habe kein Auto.","Arabam yok."],["Das ist nicht teuer.","Bu pahalı değil."],["Ich komme heute nicht.","Bugün gelmiyorum."],["Er hat keine Zeit.","Onun vakti yok."],["Die Wohnung ist schön.","Daire güzel."],["Das Hotel ist nicht gut.","Otel iyi değil."],["Der Zug ist schnell.","Tren hızlı."],["Das Internet ist langsam.","İnternet yavaş."],["Deutsch ist nicht schwer.","Almanca zor değil."],["Das ist ganz einfach.","Bu çok basit."],["Das Wetter ist schlecht.","Hava kötü."],["Das Haus ist neu und groß.","Ev yeni ve büyük."]];
X["A1-16"]=[["Ich gehe nach Hause.","Eve gidiyorum."],["Wir fahren mit dem Bus.","Otobüsle gidiyoruz."],["Er fährt mit dem Auto.","O arabayla gidiyor."],["Ich gehe zum Supermarkt.","Süpermarkete gidiyorum."],["Sie geht zur Apotheke.","O eczaneye gidiyor."],["Wir fahren nach Wien.","Viyana'ya gidiyoruz."],["Fährst du mit der U-Bahn?","Metroyla mı gidiyorsun?"],["Der Zug kommt um acht.","Tren sekizde geliyor."],["Ich bin heute zu Hause.","Bugün evdeyim."],["Wie komme ich zur Bank?","Bankaya nasıl giderim?"],["Das Restaurant ist in dieser Straße.","Restoran bu sokakta."],["Kommst du mit ins Kino?","Sinemaya benimle gelir misin?"]];

X["A2-1"]=[["Ich stehe um sechs auf.","Altıda kalkarım."],["Wann stehst du auf?","Kaçta kalkarsın?"],["Er ruft seine Mutter an.","O annesini arıyor."],["Wir kaufen heute ein.","Bugün alışveriş yapıyoruz."],["Der Film fängt um acht an.","Film sekizde başlıyor."],["Ich höre um fünf auf.","Beşte bırakıyorum."],["Sie sieht abends fern.","O akşamları televizyon izler."],["Ich wache früh auf.","Erken uyanırım."],["Wir frühstücken um sieben.","Yedide kahvaltı yaparız."],["Normalerweise gehe ich um elf schlafen.","Normalde on birde yatarım."],["Danach dusche ich.","Ondan sonra duş alırım."],["Rufst du mich morgen an?","Yarın beni arar mısın?"]];
X["A2-2"]=[["Ich kann gut kochen.","İyi yemek yapabilirim."],["Kannst du mir helfen?","Bana yardım edebilir misin?"],["Ich muss heute arbeiten.","Bugün çalışmak zorundayım."],["Wir wollen nach Wien fahren.","Viyana'ya gitmek istiyoruz."],["Darf ich hier sitzen?","Buraya oturabilir miyim?"],["Du sollst mehr Wasser trinken.","Daha çok su içmelisin."],["Er will Deutsch lernen.","O Almanca öğrenmek istiyor."],["Hier darf man nicht parken.","Buraya park edilmez."],["Du musst nicht kommen.","Gelmen gerekmiyor."],["Ich mag Schokolade.","Çikolatayı severim."],["Leider kann ich nicht kommen.","Maalesef gelemiyorum."],["Was soll ich machen?","Ne yapmalıyım?"]];
X["A2-3"]=[["Ich habe Pizza gegessen.","Pizza yedim."],["Was hast du gemacht?","Ne yaptın?"],["Wir haben einen Film gesehen.","Bir film izledik."],["Er hat viel gearbeitet.","O çok çalıştı."],["Ich habe ein Buch gelesen.","Bir kitap okudum."],["Sie hat eine Mail geschrieben.","O bir e-posta yazdı."],["Hast du schon gegessen?","Yemek yedin mi?"],["Ich habe noch nicht gekocht.","Henüz yemek yapmadım."],["Wir haben Kaffee getrunken.","Kahve içtik."],["Gestern habe ich eingekauft.","Dün alışveriş yaptım."],["Ich habe meine Eltern besucht.","Annemle babamı ziyaret ettim."],["Hast du die Nachricht gelesen?","Mesajı okudun mu?"]];
X["A2-4"]=[["Ich bin nach Hause gegangen.","Eve gittim."],["Wann bist du gekommen?","Ne zaman geldin?"],["Wir sind nach Izmir gefahren.","İzmir'e gittik."],["Sie ist nach Wien geflogen.","O Viyana'ya uçtu."],["Ich bin zu Hause geblieben.","Evde kaldım."],["Was ist passiert?","Ne oldu?"],["Der Zug ist spät angekommen.","Tren geç vardı."],["Ich bin um sieben aufgestanden.","Yedide kalktım."],["Er ist letztes Jahr umgezogen.","O geçen yıl taşındı."],["Ich bin 1998 geboren.","1998'de doğdum."],["Ich war gestern im Büro.","Dün ofisteydim."],["Vor zwei Wochen bin ich angekommen.","İki hafta önce geldim."]];
X["A2-5"]=[["Diese Jacke ist schön.","Bu ceket güzel."],["Ich nehme diesen Pullover.","Bu kazağı alıyorum."],["Dieses Hemd ist zu klein.","Bu gömlek çok küçük."],["Die Hose passt mir nicht.","Pantolon bana olmuyor."],["Kann ich die Schuhe anprobieren?","Ayakkabıları deneyebilir miyim?"],["Welche Größe haben Sie?","Bedeniniz kaç?"],["Die Farbe steht dir gut.","Bu renk sana yakışıyor."],["Er trägt eine blaue Jacke.","O mavi bir ceket giyiyor."],["Der Mantel ist im Angebot.","Palto indirimde."],["Haben Sie das in Schwarz?","Bunun siyahı var mı?"],["Ich brauche neue Schuhe.","Yeni ayakkabıya ihtiyacım var."],["Wo ist die Umkleidekabine?","Deneme kabini nerede?"]];
X["A2-6"]=[["Ich möchte einen Tisch reservieren.","Bir masa ayırtmak istiyorum."],["Die Speisekarte, bitte.","Menü lütfen."],["Ich nehme die Suppe.","Çorbayı alıyorum."],["Was empfehlen Sie?","Ne tavsiye edersiniz?"],["Ist das scharf?","Bu acı mı?"],["Das Essen war lecker.","Yemek lezzetliydi."],["Die Rechnung, bitte.","Hesap lütfen."],["Wir zahlen getrennt.","Ayrı ayrı ödüyoruz."],["Zum Nachtisch nehme ich Eis.","Tatlı olarak dondurma alıyorum."],["Kann ich bestellen?","Sipariş verebilir miyim?"],["Noch ein Wasser, bitte.","Bir su daha lütfen."],["Das Trinkgeld ist für Sie.","Bahşiş sizin için."]];
X["A2-7"]=[["Es regnet heute.","Bugün yağmur yağıyor."],["Es schneit im Winter.","Kışın kar yağar."],["Die Sonne scheint.","Güneş parlıyor."],["Es ist sehr kalt.","Hava çok soğuk."],["Im Sommer ist es warm.","Yazın hava sıcak."],["Mir ist kalt.","Üşüyorum."],["Es sind zwanzig Grad.","Hava yirmi derece."],["Im Herbst ist es windig.","Sonbaharda rüzgârlı olur."],["Nimm einen Regenschirm mit!","Yanına şemsiye al!"],["Wie ist das Wetter in Wien?","Viyana'da hava nasıl?"],["Im Frühling blühen die Blumen.","İlkbaharda çiçekler açar."],["Morgen gibt es Schnee.","Yarın kar var."]];
X["A2-8"]=[["Mein Kopf tut weh.","Başım ağrıyor."],["Ich habe Bauchschmerzen.","Karnım ağrıyor."],["Mir tut der Rücken weh.","Sırtım ağrıyor."],["Das Kind hat Fieber.","Çocuğun ateşi var."],["Ich bin erkältet.","Soğuk algınlığım var."],["Ich brauche ein Medikament.","Bir ilaca ihtiyacım var."],["Die Praxis ist heute geschlossen.","Muayenehane bugün kapalı."],["Ich gehe zur Apotheke.","Eczaneye gidiyorum."],["Ich fühle mich nicht gut.","Kendimi iyi hissetmiyorum."],["Gute Besserung!","Geçmiş olsun!"],["Sie hat Halsschmerzen.","Onun boğazı ağrıyor."],["Bleib gesund!","Sağlıklı kal!"]];
X["A2-9"]=[["Gehen Sie geradeaus.","Düz gidin."],["Biegen Sie links ab.","Sola dönün."],["Die Post ist rechts.","Postane sağda."],["Nehmen Sie den Bus.","Otobüse binin."],["Geh an der Ampel rechts.","Işıkta sağa git."],["Das Café ist um die Ecke.","Kafe köşede."],["Ist es weit von hier?","Buradan uzak mı?"],["Steigen Sie hier aus.","Burada inin."],["Sie müssen einmal umsteigen.","Bir kez aktarma yapmanız gerekiyor."],["Komm bitte her!","Lütfen buraya gel!"],["Gibt es eine Bank in der Nähe?","Yakında banka var mı?"],["Nach der Kreuzung links.","Kavşaktan sonra sola."]];
X["A2-10"]=[["Ich helfe dir.","Sana yardım ediyorum."],["Kannst du mir das Salz geben?","Bana tuzu verebilir misin?"],["Ich kenne ihn.","Onu tanıyorum."],["Ich gebe ihm das Buch.","Kitabı ona veriyorum."],["Wien gefällt mir.","Viyana hoşuma gidiyor."],["Das Essen schmeckt mir.","Yemeğin tadı hoşuma gidiyor."],["Wem gehört das Auto?","Araba kimin?"],["Das gehört mir.","Bu benim."],["Ich danke Ihnen.","Size teşekkür ederim."],["Ich zeige dir die Stadt.","Sana şehri gösteriyorum."],["Wir fahren mit ihr.","Onunla gidiyoruz."],["Besuchst du uns?","Bizi ziyaret eder misin?"]];
X["A2-11"]=[["Ich war gestern müde.","Dün yorgundum."],["Wo warst du?","Neredeydin?"],["Wir hatten keine Zeit.","Vaktimiz yoktu."],["Er hatte Fieber.","Onun ateşi vardı."],["Früher gab es hier einen Park.","Eskiden burada bir park vardı."],["Ich konnte nicht schlafen.","Uyuyamadım."],["Wir mussten warten.","Beklemek zorunda kaldık."],["Sie wollte Ärztin werden.","O doktor olmak istiyordu."],["Als Kind war ich ruhig.","Çocukken sakindim."],["Damals wohnten wir in Ankara.","O zamanlar Ankara'da oturuyorduk."],["Das Wetter war schön.","Hava güzeldi."],["Früher habe ich viel gelesen.","Eskiden çok okurdum."]];
X["A2-12"]=[["Berlin ist größer als Wien.","Berlin Viyana'dan büyük."],["Ich bin älter als mein Bruder.","Kardeşimden büyüğüm."],["Der Zug ist schneller als der Bus.","Tren otobüsten hızlı."],["Tee ist billiger als Kaffee.","Çay kahveden ucuz."],["Heute geht es mir besser.","Bugün daha iyiyim."],["Er ist so groß wie ich.","O benim kadar uzun."],["Das ist am besten.","En iyisi bu."],["Ich trinke lieber Tee.","Çay içmeyi tercih ederim."],["Wien ist teurer als Istanbul.","Viyana İstanbul'dan pahalı."],["Sie ist jünger als ich.","O benden genç."],["Ich arbeite mehr als früher.","Eskisinden daha çok çalışıyorum."],["Das gefällt mir am besten.","En çok bunu beğeniyorum."]];
X["A2-13"]=[["Die Besprechung beginnt um zehn.","Toplantı onda başlıyor."],["Mein Kollege ist krank.","İş arkadaşım hasta."],["Der Chef ist im Büro.","Şef ofiste."],["Das Projekt ist wichtig.","Proje önemli."],["Ich arbeite beim Kunden.","Müşteride çalışıyorum."],["Die Firma ist groß.","Şirket büyük."],["Heute bin ich im Homeoffice.","Bugün evden çalışıyorum."],["Ich nehme Urlaub.","İzin alıyorum."],["Die Frist ist morgen.","Son tarih yarın."],["Das ist meine Aufgabe.","Bu benim görevim."],["Schönen Feierabend!","İyi akşamlar (mesai sonu)!"],["Im Anhang finden Sie die Datei.","Dosyayı ekte bulabilirsiniz."]];
X["A2-14"]=[["Ich lese gern.","Okumayı severim."],["Was machst du in deiner Freizeit?","Boş zamanında ne yaparsın?"],["Wir reisen gern.","Seyahat etmeyi severiz."],["Er joggt jeden Morgen.","O her sabah koşar."],["Ich gehe ins Fitnessstudio.","Spor salonuna gidiyorum."],["Am Wochenende wandern wir.","Hafta sonu doğa yürüyüşü yaparız."],["Ich höre gern Musik.","Müzik dinlemeyi severim."],["Gehen wir ins Kino?","Sinemaya gidelim mi?"],["Am liebsten koche ich.","En çok yemek yapmayı severim."],["Wir treffen uns am Samstag.","Cumartesi buluşuyoruz."],["Mein Hobby ist Fotografieren.","Hobim fotoğraf çekmek."],["Ich spiele nicht gern Fußball.","Futbol oynamayı sevmem."]];
X["A2-15"]=[["Ich rufe Sie zurück.","Sizi geri arıyorum."],["Ich verbinde Sie.","Sizi bağlıyorum."],["Die Leitung ist besetzt.","Hat meşgul."],["Kann ich eine Nachricht hinterlassen?","Mesaj bırakabilir miyim?"],["Ich kann ihn nicht erreichen.","Ona ulaşamıyorum."],["Ich muss den Termin absagen.","Randevuyu iptal etmem gerekiyor."],["Können wir den Termin verschieben?","Randevuyu erteleyebilir miyiz?"],["Passt Ihnen Montag?","Pazartesi size uyar mı?"],["Wir vereinbaren einen Termin.","Bir randevu ayarlıyoruz."],["Können Sie das buchstabieren?","Bunu harf harf söyleyebilir misiniz?"],["Ich telefoniere gerade.","Şu an telefondayım."],["Wie ist Ihre Telefonnummer?","Telefon numaranız nedir?"]];
X["A2-16"]=[["Ich bin müde, aber ich arbeite.","Yorgunum ama çalışıyorum."],["Kommst du oder bleibst du?","Geliyor musun yoksa kalıyor musun?"],["Ich gehe, denn es ist spät.","Gidiyorum, çünkü geç oldu."],["Nicht Tee, sondern Kaffee.","Çay değil, kahve."],["Es regnet, deshalb bleibe ich hier.","Yağmur yağıyor, bu yüzden burada kalıyorum."],["Ich bin krank, trotzdem arbeite ich.","Hastayım, yine de çalışıyorum."],["Zuerst esse ich, dann schlafe ich.","Önce yerim, sonra uyurum."],["Beeil dich, sonst kommst du zu spät.","Acele et, yoksa geç kalacaksın."],["Das Hotel ist billig und schön.","Otel ucuz ve güzel."],["Ich spreche Deutsch und auch Englisch.","Almanca ve İngilizce de konuşuyorum."],["Die Wohnung ist klein, außerdem ist sie laut.","Daire küçük, ayrıca gürültülü."],["Er kommt nicht, denn er ist krank.","O gelmiyor, çünkü hasta."]];
X["A2-17"]=[["Ich freue mich auf den Urlaub.","Tatili dört gözle bekliyorum."],["Freust du dich?","Seviniyor musun?"],["Er interessiert sich für Fußball.","O futbolla ilgileniyor."],["Ich erinnere mich an dich.","Seni hatırlıyorum."],["Wir beeilen uns.","Acele ediyoruz."],["Setz dich, bitte.","Otur lütfen."],["Ich ruhe mich aus.","Dinleniyorum."],["Sie zieht sich schnell an.","O hızlıca giyiniyor."],["Darf ich mich vorstellen?","Kendimi tanıtabilir miyim?"],["Ich fühle mich gut.","Kendimi iyi hissediyorum."],["Ich gewöhne mich an Wien.","Viyana'ya alışıyorum."],["Er kümmert sich um die Kinder.","O çocuklarla ilgileniyor."]];

X["B1-1"]=[["Ich komme nicht, weil ich krank bin.","Gelmiyorum çünkü hastayım."],["Ich glaube, dass er recht hat.","Bence o haklı."],["Wenn ich Zeit habe, komme ich.","Vaktim olursa gelirim."],["Ich weiß nicht, ob sie kommt.","Onun gelip gelmeyeceğini bilmiyorum."],["Obwohl es kalt ist, gehe ich raus.","Hava soğuk olmasına rağmen dışarı çıkıyorum."],["Ich hoffe, dass du kommst.","Umarım gelirsin."],["Weißt du, wann der Zug fährt?","Trenin ne zaman kalktığını biliyor musun?"],["Er sagt, dass er müde ist.","Yorgun olduğunu söylüyor."],["Wenn es regnet, bleiben wir zu Hause.","Yağmur yağarsa evde kalırız."],["Ich lerne Deutsch, weil ich nach Wien ziehe.","Almanca öğreniyorum çünkü Viyana'ya taşınıyorum."],["Ich bin sicher, dass es klappt.","Olacağından eminim."],["Weil ich müde war, bin ich früh gegangen.","Yorgun olduğum için erken gittim."]];
X["B1-2"]=[["Als ich jung war, habe ich viel gelesen.","Gençken çok okurdum."],["Während ich arbeite, höre ich Musik.","Çalışırken müzik dinlerim."],["Bevor ich schlafe, lese ich.","Uyumadan önce okurum."],["Nachdem wir gegessen hatten, gingen wir spazieren.","Yemekten sonra yürüyüşe çıktık."],["Plötzlich klingelte das Telefon.","Aniden telefon çaldı."],["Zuerst waren wir in Köln.","Önce Köln'deydik."],["Schließlich haben wir den Weg gefunden.","Sonunda yolu bulduk."],["Erzähl mal, was ist passiert?","Anlat bakalım, ne oldu?"],["Seitdem ich in Wien wohne, spreche ich mehr Deutsch.","Viyana'da yaşadığımdan beri daha çok Almanca konuşuyorum."],["Wir haben viel erlebt.","Çok şey yaşadık."],["Als ich ankam, war es dunkel.","Vardığımda hava karanlıktı."],["Wenn ich in Izmir bin, gehe ich ans Meer.","İzmir'deyken denize giderim."]];
X["B1-3"]=[["Ich werde morgen anrufen.","Yarın arayacağım."],["Es wird bald regnen.","Yakında yağmur yağacak."],["Wir werden nach Wien umziehen.","Viyana'ya taşınacağız."],["Du wirst das schaffen.","Bunu başaracaksın."],["Was hast du morgen vor?","Yarın ne yapmayı düşünüyorsun?"],["Nächstes Jahr werde ich selbstständig arbeiten.","Gelecek yıl serbest çalışacağım."],["Er wird wahrscheinlich später kommen.","Muhtemelen daha sonra gelecek."],["Ich verspreche, ich werde pünktlich sein.","Söz veriyorum, zamanında olacağım."],["Wir planen eine Reise nach Italien.","İtalya'ya bir seyahat planlıyoruz."],["In der Zukunft möchte ich mehr reisen.","Gelecekte daha çok seyahat etmek istiyorum."],["Es wird kalt.","Hava soğuyor."],["Mein Bruder wird Vater.","Kardeşim baba oluyor."]];
X["B1-4"]=[["Könnten Sie mir helfen?","Bana yardım edebilir miydiniz?"],["Ich hätte gern einen Kaffee.","Bir kahve alabilir miyim."],["Würden Sie das Fenster öffnen?","Pencereyi açar mıydınız?"],["Das wäre schön.","Bu güzel olurdu."],["Du solltest mehr schlafen.","Daha çok uyumalısın."],["Ich würde gern mitkommen.","Seve seve gelirdim."],["Könnten wir später anfangen?","Daha geç başlayabilir miydik?"],["Ich hätte eine Frage.","Bir sorum olacaktı."],["An deiner Stelle würde ich warten.","Senin yerinde olsam beklerdim."],["Das müsste funktionieren.","Bunun çalışması gerekir."],["Ich würde lieber zu Hause bleiben.","Evde kalmayı tercih ederdim."],["Wäre es möglich, früher zu kommen?","Daha erken gelmek mümkün olur muydu?"]];
X["B1-5"]=[["Wenn ich Zeit hätte, würde ich reisen.","Vaktim olsa seyahat ederdim."],["Wenn ich reich wäre, würde ich ein Haus kaufen.","Zengin olsam bir ev alırdım."],["Falls du Hilfe brauchst, ruf mich an.","Yardıma ihtiyacın olursa beni ara."],["Beeil dich, sonst verpassen wir den Bus.","Acele et, yoksa otobüsü kaçıracağız."],["Ich wünschte, ich wäre in Wien.","Keşke Viyana'da olsam."],["Wenn ich das gewusst hätte, wäre ich gekommen.","Bunu bilseydim gelirdim."],["Was würdest du machen?","Sen ne yapardın?"],["Das ist mir egal.","Benim için fark etmez."],["Wenn es nicht regnen würde, könnten wir grillen.","Yağmur yağmasa mangal yapabilirdik."],["Hätte ich mehr Geld, würde ich mehr sparen.","Daha çok param olsa daha çok biriktirirdim."],["Wenn ich die Möglichkeit hätte, würde ich im Ausland arbeiten.","İmkânım olsa yurtdışında çalışırdım."],["Unter einer Bedingung komme ich mit.","Bir şartla gelirim."]];
X["B1-6"]=[["Meiner Meinung nach ist das richtig.","Bence bu doğru."],["Ich finde, dass Wien schön ist.","Bence Viyana güzel."],["Da hast du recht.","Orada haklısın."],["Das sehe ich anders.","Ben bunu farklı görüyorum."],["Einerseits ist es teuer, andererseits ist es gut.","Bir yandan pahalı, öte yandan iyi."],["Der Vorteil ist der Preis.","Avantajı fiyat."],["Der Nachteil ist die Lage.","Dezavantajı konum."],["Das überzeugt mich nicht.","Bu beni ikna etmiyor."],["Da stimme ich dir zu.","Bu konuda sana katılıyorum."],["Eigentlich ist das keine schlechte Idee.","Aslında bu kötü bir fikir değil."],["Das stimmt, allerdings ist es kompliziert.","Doğru, ancak karmaşık."],["Was ist deine Meinung?","Senin fikrin ne?"]];
X["B1-7"]=[["Das ist der Mann, der hier wohnt.","Bu burada oturan adam."],["Das ist die Frau, die Deutsch spricht.","Bu Almanca konuşan kadın."],["Das ist das Buch, das ich lese.","Bu okuduğum kitap."],["Der Film, den ich gesehen habe, war gut.","İzlediğim film iyiydi."],["Die Kollegin, mit der ich arbeite, ist nett.","Birlikte çalıştığım meslektaş nazik."],["Das ist alles, was ich weiß.","Bildiğim her şey bu."],["Die Stadt, in der ich wohne, ist groß.","Oturduğum şehir büyük."],["Die Leute, denen ich helfe, sind dankbar.","Yardım ettiğim insanlar minnettar."],["Ich suche jemanden, der kochen kann.","Yemek yapabilen birini arıyorum."],["Das ist der Grund, warum ich lerne.","Öğrenmemin sebebi bu."],["Das Hotel, das du empfohlen hast, ist super.","Tavsiye ettiğin otel süper."],["Der Freund, dem ich geschrieben habe, antwortet nicht.","Yazdığım arkadaş cevap vermiyor."]];
X["B1-8"]=[["Ich bin froh, dass du hier bist.","Burada olduğuna sevindim."],["Sie ist traurig.","O üzgün."],["Ich ärgere mich über den Lärm.","Gürültüye sinir oluyorum."],["Es tut mir leid.","Üzgünüm."],["Wir verstehen uns gut.","İyi anlaşıyoruz."],["Sie streiten sich oft.","Sık sık tartışırlar."],["Ich vermisse dich.","Seni özlüyorum."],["Ich bin stolz auf dich.","Seninle gurur duyuyorum."],["Er hat gute Laune.","Keyfi yerinde."],["Ich bin ein bisschen enttäuscht.","Biraz hayal kırıklığına uğradım."],["Mach dir keine Sorgen.","Endişelenme."],["Sie hat sich in ihn verliebt.","O ona âşık oldu."]];
X["B1-9"]=[["Ich lese die Nachrichten online.","Haberleri internetten okuyorum."],["Laut der Zeitung steigen die Preise.","Gazeteye göre fiyatlar artıyor."],["Angeblich kommt morgen ein Sturm.","Söylendiğine göre yarın fırtına geliyor."],["Die Medien berichten über die Wahl.","Medya seçimi haberleştiriyor."],["Ich habe einen Artikel gelesen.","Bir makale okudum."],["Die Sendung beginnt um acht.","Program sekizde başlıyor."],["Was ist die Quelle?","Kaynak ne?"],["Das ist ein aktuelles Thema.","Bu güncel bir konu."],["Es gibt zu viel Werbung.","Çok fazla reklam var."],["Ich habe gelesen, dass die Mieten steigen.","Kiraların arttığını okudum."],["Die Ergebnisse wurden veröffentlicht.","Sonuçlar yayımlandı."],["Man sollte nicht alles glauben.","Her şeye inanmamak lazım."]];
X["B1-10"]=[["Wir müssen die Umwelt schützen.","Çevreyi korumalıyız."],["Das Problem ist der Verkehr.","Sorun trafik."],["Wir brauchen eine Lösung.","Bir çözüme ihtiyacımız var."],["Man muss den Müll trennen.","Çöpü ayrıştırmak gerekir."],["Ich spare Energie.","Enerji tasarrufu yapıyorum."],["Der Klimawandel ist ein großes Problem.","İklim değişikliği büyük bir sorun."],["Das liegt daran, dass es zu viele Autos gibt.","Bunun nedeni çok fazla araba olması."],["Das hat schlimme Folgen.","Bunun kötü sonuçları var."],["Die Gesellschaft verändert sich.","Toplum değişiyor."],["Jeder kann etwas tun.","Herkes bir şey yapabilir."],["Eine Lösung wäre, mehr Bus zu fahren.","Bir çözüm daha çok otobüsle gitmek olurdu."],["In meinem Heimatland ist das anders.","Benim ülkemde bu farklı."]];
X["B1-11"]=[["Das Haus wird gebaut.","Ev inşa ediliyor."],["Das Auto wird repariert.","Araba tamir ediliyor."],["Die Brücke wurde 1990 gebaut.","Köprü 1990'da inşa edildi."],["Das System wird neu gestartet.","Sistem yeniden başlatılıyor."],["Die Daten wurden gelöscht.","Veriler silindi."],["Hier wird Deutsch gesprochen.","Burada Almanca konuşulur."],["Der Fehler wurde behoben.","Hata giderildi."],["Die Firma wurde 1980 gegründet.","Şirket 1980'de kuruldu."],["Wir wurden eingeladen.","Davet edildik."],["Das muss heute erledigt werden.","Bunun bugün halledilmesi gerekiyor."],["Rauchen ist hier verboten.","Burada sigara içmek yasak."],["Das Paket ist geliefert worden.","Paket teslim edildi."]];
X["B1-12"]=[["Die Heizung funktioniert nicht.","Kalorifer çalışmıyor."],["Das Gerät ist kaputt.","Cihaz bozuk."],["Ich möchte mich beschweren.","Şikâyet etmek istiyorum."],["Ich möchte das zurückgeben.","Bunu iade etmek istiyorum."],["Haben Sie den Kassenbon?","Fişiniz var mı?"],["Das Handy hat zwei Jahre Garantie.","Telefonun iki yıl garantisi var."],["Kann ich das umtauschen?","Bunu değiştirebilir miyim?"],["Der Flug hatte Verspätung.","Uçuş rötar yaptı."],["Das war ein Fehler.","Bu bir hataydı."],["Wir erstatten Ihnen das Geld.","Paranızı iade ediyoruz."],["Wir müssen das klären.","Bunu netleştirmemiz gerekiyor."],["Das ist schon das zweite Mal.","Bu zaten ikinci kez."]];
X["B1-13"]=[["Ich bewerbe mich bei einer Firma in Wien.","Viyana'da bir şirkete başvuruyorum."],["Ich habe fünf Jahre Erfahrung.","Beş yıllık deneyimim var."],["Mein Lebenslauf ist fertig.","Özgeçmişim hazır."],["Ich habe morgen ein Vorstellungsgespräch.","Yarın bir iş görüşmem var."],["Die Stelle ist interessant.","Pozisyon ilginç."],["Das Gehalt ist gut.","Maaş iyi."],["Ich bin für die Datenbank verantwortlich.","Veritabanından sorumluyum."],["Meine Stärke ist Teamarbeit.","Güçlü yönüm takım çalışması."],["Ich mache eine Weiterbildung.","Bir mesleki eğitim alıyorum."],["Ich habe gute Englischkenntnisse.","İyi İngilizce bilgim var."],["Wann können Sie anfangen?","Ne zaman başlayabilirsiniz?"],["Ich arbeite seit fünf Jahren mit SAP.","Beş yıldır SAP ile çalışıyorum."]];
X["B1-14"]=[["Ich möchte ein Konto eröffnen.","Bir hesap açmak istiyorum."],["Ich überweise die Miete.","Kirayı havale ediyorum."],["Die Kaution ist hoch.","Depozito yüksek."],["Ich unterschreibe den Mietvertrag.","Kira sözleşmesini imzalıyorum."],["Bitte füllen Sie das Formular aus.","Lütfen formu doldurun."],["Unterschreiben Sie hier.","Buraya imza atın."],["Ich habe alle Unterlagen dabei.","Tüm belgeler yanımda."],["Ich brauche eine Versicherung.","Bir sigortaya ihtiyacım var."],["Die Behörde ist heute geschlossen.","Resmî daire bugün kapalı."],["Für die Anmeldung brauche ich den Pass.","Kayıt için pasaporta ihtiyacım var."],["Die Miete ist am Monatsanfang fällig.","Kira ay başında ödenir."],["Muss ich einen Termin machen?","Randevu almam gerekiyor mu?"]];
X["B1-15"]=[["Ich lerne, um besser zu sprechen.","Daha iyi konuşmak için öğreniyorum."],["Ich spare, um zu reisen.","Seyahat etmek için para biriktiriyorum."],["Ich erkläre es, damit du es verstehst.","Anlayasın diye açıklıyorum."],["Er ging, ohne etwas zu sagen.","Bir şey söylemeden gitti."],["Statt zu warten, rufe ich an.","Beklemek yerine arıyorum."],["Nicht heute, sondern morgen.","Bugün değil, yarın."],["Ich trinke weder Kaffee noch Tee.","Ne kahve ne çay içerim."],["Entweder du kommst oder du rufst an.","Ya gelirsin ya da ararsın."],["Je mehr ich übe, desto besser wird es.","Ne kadar çok pratik yaparsam o kadar iyi oluyor."],["Ich spreche sowohl Türkisch als auch Englisch.","Hem Türkçe hem İngilizce konuşuyorum."],["Außerdem ist es billiger.","Ayrıca daha ucuz."],["Zumindest hast du es versucht.","En azından denedin."]];
X["B1-16"]=[["Also, wo waren wir?","Pekâlâ, nerede kalmıştık?"],["Genau, das meine ich!","Aynen, onu kastediyorum!"],["Na ja, es geht.","Eh işte, idare eder."],["Das ist halt so.","İşte öyle."],["Echt? Das wusste ich nicht.","Gerçekten mi? Bilmiyordum."],["Keine Ahnung.","Hiçbir fikrim yok."],["Alles klar, bis später!","Tamamdır, sonra görüşürüz!"],["Ach so, jetzt verstehe ich.","Haa, şimdi anladım."],["Mal sehen, ob es klappt.","Bakalım olacak mı."],["Übrigens, hast du morgen Zeit?","Bu arada, yarın vaktin var mı?"],["So ein Quatsch!","Ne saçmalık!"],["Komm doch mal vorbei!","Bir uğrasana!"]];

X["B2-1"]=[["Wegen des Regens bleiben wir zu Hause.","Yağmur yüzünden evde kalıyoruz."],["Trotz der Kälte gehen wir spazieren.","Soğuğa rağmen yürüyüşe çıkıyoruz."],["Während des Meetings war ich still.","Toplantı sırasında sessizdim."],["Das ist das Auto meines Bruders.","Bu kardeşimin arabası."],["Aufgrund eines Fehlers fiel der Server aus.","Bir hata nedeniyle sunucu çöktü."],["Innerhalb einer Stunde war alles erledigt.","Bir saat içinde her şey halledildi."],["Statt eines Hotels nehmen wir eine Wohnung.","Otel yerine bir daire tutuyoruz."],["Die Meinung der Kunden ist wichtig.","Müşterilerin görüşü önemli."],["Außerhalb der Stadt ist es ruhig.","Şehir dışında sakin."],["Bezüglich Ihrer Frage melde ich mich morgen.","Sorunuzla ilgili yarın dönüş yapacağım."],["Am Ende des Tages war ich müde.","Günün sonunda yorgundum."],["Infolge des Streiks fuhren keine Züge.","Grev sonucunda hiç tren çalışmadı."]];
X["B2-2"]=[["Ich habe einen neuen Laptop.","Yeni bir dizüstü bilgisayarım var."],["Der neue Kollege ist nett.","Yeni meslektaş nazik."],["Wir suchen eine große Wohnung.","Büyük bir daire arıyoruz."],["Das ist ein schönes Haus.","Bu güzel bir ev."],["Ich trinke gern heißen Tee.","Sıcak çay içmeyi severim."],["Mit dem alten System gibt es Probleme.","Eski sistemle sorunlar var."],["Sie trägt ein rotes Kleid.","O kırmızı bir elbise giyiyor."],["Die neuen Mitarbeiter beginnen morgen.","Yeni çalışanlar yarın başlıyor."],["Er hat einen guten Job.","İyi bir işi var."],["Ich wohne in einer kleinen Stadt.","Küçük bir şehirde oturuyorum."],["Frisches Brot schmeckt am besten.","Taze ekmeğin tadı en iyisi."],["Das ist die aktuelle Version.","Bu güncel sürüm."]];
X["B2-3"]=[["Das schlafende Kind ist ruhig.","Uyuyan çocuk sakin."],["Die laufende Wartung dauert noch.","Süren bakım hâlâ devam ediyor."],["Das reparierte Auto fährt wieder.","Tamir edilen araba yeniden çalışıyor."],["Die geplante Reise fällt aus.","Planlanan seyahat iptal."],["Steigende Preise sind ein Problem.","Artan fiyatlar bir sorun."],["Das gelöste Problem kam nicht zurück.","Çözülen sorun geri gelmedi."],["Alle betroffenen Kunden wurden informiert.","Etkilenen tüm müşteriler bilgilendirildi."],["Der gestern installierte Patch funktioniert.","Dün kurulan yama çalışıyor."],["Das ist ein abgeschlossenes Projekt.","Bu tamamlanmış bir proje."],["Bitte beachten Sie die folgenden Punkte.","Lütfen aşağıdaki noktalara dikkat edin."],["Das Hotel ist ausgebucht.","Otel tamamen dolu."],["Die wachsende Stadt braucht mehr Wohnungen.","Büyüyen şehrin daha çok daireye ihtiyacı var."]];
X["B2-4"]=[["Er sagt, er sei krank.","Hasta olduğunu söylüyor."],["Sie meint, sie habe keine Zeit.","Vakti olmadığını söylüyor."],["Der Chef sagt, das Projekt sei wichtig.","Şef projenin önemli olduğunu söylüyor."],["Er behauptet, er habe nichts gesehen.","Hiçbir şey görmediğini iddia ediyor."],["Sie erklärte, sie werde kommen.","Geleceğini açıkladı."],["Er meint, er könne das allein.","Bunu tek başına yapabileceğini söylüyor."],["Der Kunde sagt, das System sei langsam.","Müşteri sistemin yavaş olduğunu söylüyor."],["Laut Bericht sei alles in Ordnung.","Rapora göre her şey yolundaymış."],["Sie fragte, ob ich Zeit hätte.","Vaktim olup olmadığını sordu."],["Er gab an, er sei zu Hause gewesen.","Evde olduğunu belirtti."],["Die Firma teilt mit, man habe den Fehler gefunden.","Şirket hatayı bulduklarını bildiriyor."],["Sie sagen, sie hätten alles getestet.","Her şeyi test ettiklerini söylüyorlar."]];
X["B2-5"]=[["Das lässt sich leicht lösen.","Bu kolayca çözülebilir."],["Das Problem ist lösbar.","Sorun çözülebilir."],["Die Aufgabe ist bis Freitag zu erledigen.","Görev cumaya kadar halledilmeli."],["Das Fenster lässt sich nicht öffnen.","Pencere açılmıyor."],["Ich bin ab acht erreichbar.","Sekizden itibaren ulaşılabilirim."],["Der Server ist wieder verfügbar.","Sunucu yeniden kullanılabilir."],["Das ist in einer Woche machbar.","Bu bir haftada yapılabilir."],["Hier spricht man Deutsch.","Burada Almanca konuşulur."],["Das Formular ist online auszufüllen.","Form internetten doldurulmalı."],["Der Text lässt sich gut übersetzen.","Metin kolayca çevrilebilir."],["Diese Fehler sind zu vermeiden.","Bu hatalardan kaçınılmalı."],["Ihre Entscheidung ist nachvollziehbar.","Kararınız anlaşılır."]];
X["B2-6"]=[["Er muss krank sein.","Hasta olmalı."],["Das dürfte reichen.","Bu muhtemelen yeter."],["Das könnte ein Fehler sein.","Bu bir hata olabilir."],["Sie soll sehr reich sein.","Çok zengin olduğu söyleniyor."],["Er will nichts gewusst haben.","Hiçbir şey bilmediğini iddia ediyor."],["Sie muss den Bus verpasst haben.","Otobüsü kaçırmış olmalı."],["Du hättest früher kommen sollen.","Daha erken gelmeliydin."],["Das hätte schlimmer sein können.","Daha kötü olabilirdi."],["Er ist wohl schon zu Hause.","Herhalde çoktan evdedir."],["Anscheinend ist niemand da.","Görünüşe göre kimse yok."],["Das dürfte kein Problem sein.","Bu muhtemelen sorun olmaz."],["Offenbar hat er die Mail nicht gelesen.","Anlaşılan e-postayı okumamış."]];
X["B2-7"]=[["Ich wäre gern gekommen.","Gelmeyi isterdim."],["Wenn ich das gewusst hätte, hätte ich angerufen.","Bunu bilseydim arardım."],["Er tut so, als ob er nichts wüsste.","Hiçbir şey bilmiyormuş gibi yapıyor."],["Ich hätte fast den Zug verpasst.","Az kalsın treni kaçırıyordum."],["Wir hätten früher anfangen sollen.","Daha erken başlamalıydık."],["Sie redet, als wäre sie die Chefin.","Şefmiş gibi konuşuyor."],["Hätte ich nur mehr Zeit gehabt!","Keşke daha çok vaktim olsaydı!"],["Ich hätte das anders gemacht.","Ben bunu farklı yapardım."],["Beinahe wäre ich gefallen.","Az kalsın düşüyordum."],["Ohne deine Hilfe hätte ich es nicht geschafft.","Senin yardımın olmasa başaramazdım."],["Es sieht aus, als ob es regnen würde.","Yağmur yağacakmış gibi görünüyor."],["Wäre er pünktlich gewesen, hätten wir den Zug bekommen.","O zamanında gelseydi treni yakalardık."]];
X["B2-8"]=[["Bei Fragen rufen Sie mich an.","Sorularınız olursa beni arayın."],["Nach der Installation starten Sie neu.","Kurulumdan sonra yeniden başlatın."],["Die Umsetzung dauert drei Monate.","Uygulama üç ay sürüyor."],["Wir müssen eine Entscheidung treffen.","Bir karar vermeliyiz."],["Die Überprüfung ist abgeschlossen.","Kontrol tamamlandı."],["Zur Senkung der Kosten sparen wir Energie.","Maliyetleri düşürmek için enerji tasarrufu yapıyoruz."],["Vor der Migration machen wir ein Backup.","Geçişten önce yedek alıyoruz."],["Die Genehmigung fehlt noch.","Onay hâlâ eksik."],["Trotz der Probleme lief alles gut.","Sorunlara rağmen her şey iyi gitti."],["Die Verbesserung ist deutlich.","İyileşme belirgin."],["Nach dem Ausfall lief das System wieder.","Kesintiden sonra sistem yeniden çalıştı."],["Ich stehe Ihnen gern zur Verfügung.","Memnuniyetle hizmetinizdeyim."]];
X["B2-9"]=[["Das kommt nicht in Frage.","Bu söz konusu değil."],["Wir stellen Ihnen einen Laptop zur Verfügung.","Size bir dizüstü bilgisayar sağlıyoruz."],["Gib mir Bescheid!","Bana haber ver!"],["Das neue Gesetz tritt morgen in Kraft.","Yeni yasa yarın yürürlüğe giriyor."],["Der Preis spielt eine Rolle.","Fiyat rol oynuyor."],["Wir müssen Maßnahmen ergreifen.","Önlem almamız gerekiyor."],["Er übte Kritik an dem Projekt.","Projeyi eleştirdi."],["Bitte nimm Rücksicht auf die anderen.","Lütfen diğerlerini dikkate al."],["Wir ziehen eine andere Lösung in Betracht.","Başka bir çözümü değerlendiriyoruz."],["Sie brachte ihre Freude zum Ausdruck.","Sevincini dile getirdi."],["Wir nehmen die Hilfe gern in Anspruch.","Yardımdan memnuniyetle yararlanıyoruz."],["Wer trifft die Entscheidung?","Kararı kim veriyor?"]];
X["B2-10"]=[["Ich warte auf den Bus.","Otobüsü bekliyorum."],["Ich warte darauf.","Onu bekliyorum."],["Worauf wartest du?","Neyi bekliyorsun?"],["Wir sprechen über das Projekt.","Proje hakkında konuşuyoruz."],["Worüber sprecht ihr?","Ne hakkında konuşuyorsunuz?"],["Ich kümmere mich darum.","Ben ilgileniyorum."],["Denk daran!","Bunu unutma!"],["Es kommt darauf an.","Duruma göre değişir."],["Das hängt vom Wetter ab.","Bu havaya bağlı."],["Ich freue mich darauf, dass du kommst.","Gelmeni dört gözle bekliyorum."],["Ich bin damit zufrieden.","Bundan memnunum."],["Woran denkst du?","Ne düşünüyorsun?"]];
X["B2-11"]=[["Was steht auf der Tagesordnung?","Gündemde ne var?"],["Wer schreibt das Protokoll?","Tutanağı kim yazıyor?"],["Darf ich etwas ergänzen?","Bir şey ekleyebilir miyim?"],["Lassen Sie mich bitte ausreden.","Lütfen sözümü bitirmeme izin verin."],["Ich fasse kurz zusammen.","Kısaca özetliyorum."],["Wer übernimmt diese Aufgabe?","Bu görevi kim üstleniyor?"],["Ich wollte kurz nachhaken.","Kısaca hatırlatmak istedim."],["Danke für die schnelle Rückmeldung.","Hızlı dönüş için teşekkürler."],["Wir liegen im Zeitplan.","Plana uygun ilerliyoruz."],["Der Termin wird verschoben.","Toplantı erteleniyor."],["Das stimme ich mit dem Team ab.","Bunu ekiple koordine edeceğim."],["Habe ich Sie richtig verstanden?","Sizi doğru anladım mı?"]];
X["B2-12"]=[["Das ist zwar teuer, aber gut.","Gerçi pahalı ama iyi."],["Sofern es klappt, fahren wir morgen.","Olursa yarın gidiyoruz."],["Soweit ich weiß, ist sie im Urlaub.","Bildiğim kadarıyla izinde."],["Es regnete, sodass wir zu Hause blieben.","Yağmur yağdı, bu yüzden evde kaldık."],["Man lernt, indem man spricht.","İnsan konuşarak öğrenir."],["Es war schwer, dennoch haben wir es geschafft.","Zordu, buna rağmen başardık."],["Ich mag Tee, wohingegen er Kaffee mag.","Ben çayı severim, oysa o kahveyi sever."],["Die Daten fehlen, folglich ist der Bericht falsch.","Veriler eksik, dolayısıyla rapor yanlış."],["Infolgedessen wurde der Termin abgesagt.","Bunun sonucunda toplantı iptal edildi."],["Berlin ist laut, Wien hingegen ruhig.","Berlin gürültülü, Viyana ise sakin."],["Insofern hast du recht.","Bu açıdan haklısın."],["Ich muss ohnehin einkaufen.","Zaten alışveriş yapmam gerekiyor."]];
X["C1-1"]=[["Aus der Studie geht hervor, dass Schlaf wichtig ist.","Çalışmadan uykunun önemli olduğu anlaşılıyor."],["Es ist davon auszugehen, dass die Preise steigen.","Fiyatların artacağı varsayılmalı."],["Dies stellt ein großes Risiko dar.","Bu büyük bir risk teşkil ediyor."],["Abschließend lässt sich festhalten, dass es funktioniert.","Sonuç olarak çalıştığı saptanabilir."],["Die Leistung hat sich erheblich verbessert.","Performans kayda değer biçimde iyileşti."],["Ich bin der Auffassung, dass wir warten sollten.","Beklememiz gerektiği kanısındayım."],["Das trifft nicht auf alle zu.","Bu herkes için geçerli değil."],["Hinsichtlich der Kosten gibt es Fragen.","Maliyetler bakımından sorular var."],["Eine gute Planung ist Voraussetzung.","İyi bir planlama ön koşul."],["Im Folgenden wird das Ergebnis dargestellt.","Aşağıda sonuç sunulmaktadır."],["Er war maßgeblich am Projekt beteiligt.","Projede belirleyici rol oynadı."],["Es ist fraglich, inwiefern das stimmt.","Bunun ne ölçüde doğru olduğu tartışmalı."]];
X["C1-2"]=[["Die von uns entwickelte Software ist stabil.","Bizim geliştirdiğimiz yazılım stabil."],["Die seit Jahren steigenden Mieten sind ein Problem.","Yıllardır artan kiralar bir sorun."],["Die noch offenen Fragen klären wir morgen.","Hâlâ açık soruları yarın netleştiririz."],["Die zu prüfenden Daten liegen vor.","Kontrol edilecek veriler mevcut."],["Die oben genannten Punkte sind wichtig.","Yukarıda adı geçen noktalar önemli."],["Die bestehende Lösung ist veraltet.","Mevcut çözüm eskimiş."],["Der vorliegende Bericht ist vollständig.","Elinizdeki rapor eksiksiz."],["Das erwähnte Problem ist gelöst.","Bahsedilen sorun çözüldü."],["Wir setzen auf bewährte Methoden.","Kanıtlanmış yöntemlere güveniyoruz."],["Die anhaltende Kälte ist anstrengend.","Süregelen soğuk yorucu."],["Die beauftragte Firma beginnt bald.","Görevlendirilen firma yakında başlıyor."],["Die zunehmende Digitalisierung verändert die Arbeit.","Artan dijitalleşme işi değiştiriyor."]];
X["C1-3"]=[["Das weißt du ja.","Bunu biliyorsun ya."],["Komm doch mit!","Gelsene!"],["Das ist eben so.","İşte böyle."],["Er ist wohl krank.","Herhalde hasta."],["Das klappt schon.","Olur, merak etme."],["Schau mal!","Bir baksana!"],["Was ist denn los?","Ne oldu ki?"],["Wie heißt du eigentlich?","Adın neydi bu arada?"],["Mach das bloß nicht!","Sakın bunu yapma!"],["Frag ruhig!","Çekinmeden sor!"],["Bist du etwa schon fertig?","Yoksa bitirdin mi bile?"],["Das habe ich doch gesagt!","Bunu söylemiştim ya!"]];
X["C1-4"]=[["Der Sprecher sagte, alles sei unter Kontrolle.","Sözcü her şeyin kontrol altında olduğunu söyledi."],["Der Minister soll zurücktreten.","Bakanın istifa edeceği söyleniyor."],["Er will nichts bemerkt haben.","Hiçbir şey fark etmediğini iddia ediyor."],["Die Firma räumte Fehler ein.","Şirket hataları kabul etti."],["Er bestreitet die Vorwürfe.","Suçlamaları inkâr ediyor."],["Die Regierung dementierte den Bericht.","Hükümet haberi yalanladı."],["Einem Bericht zufolge gibt es keine Verletzten.","Bir habere göre yaralı yok."],["Der vermeintliche Fehler war keiner.","Hata sanılan şey hata değildi."],["Die Firma hat eine Stellungnahme veröffentlicht.","Şirket resmî bir açıklama yayımladı."],["Der mutmaßliche Grund war ein Stromausfall.","Muhtemel neden bir elektrik kesintisiydi."],["Er äußerte sich nicht dazu.","Bu konuda açıklama yapmadı."],["Das stand in allen Schlagzeilen.","Bu bütün manşetlerdeydi."]];
X["C1-5"]=[["Gestern habe ich den Kunden angerufen.","Dün müşteriyi aradım."],["Den Kunden habe ich gestern angerufen.","Müşteriyi dün aradım."],["Zunächst prüfen wir die Daten.","İlk olarak verileri kontrol ediyoruz."],["Anschließend schreiben wir den Bericht.","Ardından raporu yazıyoruz."],["Somit ist alles klar.","Böylece her şey net."],["Zudem fehlt eine Unterschrift.","Ayrıca bir imza eksik."],["Das ist keineswegs einfach.","Bu hiç de kolay değil."],["Das ist durchaus möglich.","Bu pekâlâ mümkün."],["Es fehlt lediglich ein Dokument.","Yalnızca bir belge eksik."],["Es geht nicht um Geld, vielmehr um Zeit.","Mesele para değil, daha ziyade zaman."],["Dabei ist ein Problem aufgetreten.","Bu sırada bir sorun oluştu."],["Ich fahre morgen wegen der Arbeit mit dem Zug nach Wien.","Yarın iş nedeniyle trenle Viyana'ya gidiyorum."]];
X["C1-6"]=[["Die Lage ist unklar.","Durum belirsiz."],["Das war ein Missverständnis.","Bu bir yanlış anlaşılmaydı."],["Die Daten sind fehlerhaft.","Veriler hatalı."],["Zeitmäßig wird es eng.","Zaman açısından sıkışık olacak."],["Möglicherweise kommt er später.","Muhtemelen daha sonra gelir."],["Beispielsweise könnten wir früher anfangen.","Örneğin daha erken başlayabiliriz."],["Der Server ist sehr leistungsfähig.","Sunucu çok güçlü."],["Das Projekt war erfolgreich.","Proje başarılıydı."],["Ich war völlig ratlos.","Tamamen çaresizdim."],["Das ist eine sinnvolle Idee.","Bu mantıklı bir fikir."],["Diese Methode ist fragwürdig.","Bu yöntem sorgulanabilir."],["Er ist arbeitslos.","O işsiz."]];
X["C1-7"]=[["Ich drücke dir die Daumen!","Sana şans diliyorum!"],["Ich halte Sie auf dem Laufenden.","Sizi haberdar ederim."],["Können wir unter vier Augen sprechen?","Baş başa konuşabilir miyiz?"],["Ich verstehe nur Bahnhof.","Hiçbir şey anlamıyorum."],["Da ist der Wurm drin.","Burada bir terslik var."],["Die Lösung liegt auf der Hand.","Çözüm apaçık ortada."],["Ich bin ins Fettnäpfchen getreten.","Pot kırdım."],["Du hast den Nagel auf den Kopf getroffen.","Tam üstüne bastın."],["Wir stehen unter Druck.","Baskı altındayız."],["Schieb das nicht auf die lange Bank!","Bunu sürüncemede bırakma!"],["Da hast du Schwein gehabt!","Şanslıymışsın!"],["Das ist nicht mein Bier.","Beni ilgilendirmez."]];
X["C1-8"]=[["Wenngleich es teuer ist, kaufe ich es.","Pahalı olsa da alıyorum."],["Obgleich sie müde war, blieb sie.","Yorgun olmasına rağmen kaldı."],["Ich bleibe hier, zumal es regnet.","Burada kalıyorum, üstelik yağmur da yağıyor."],["Demzufolge müssen wir handeln.","Buna göre harekete geçmeliyiz."],["Demnach ist die Frist abgelaufen.","Buna göre süre dolmuş."],["Nichtsdestotrotz machen wir weiter.","Her şeye rağmen devam ediyoruz."],["Er kann kaum laufen, geschweige denn rennen.","Zar zor yürüyor, bırakın koşmayı."],["Die Zahlen sind gut, indes bleibt ein Risiko.","Rakamlar iyi, bununla birlikte bir risk kalıyor."],["Ungeachtet der Kritik ging das Projekt weiter.","Eleştirilere bakılmaksızın proje devam etti."],["Die Daten sind alt, mithin unbrauchbar.","Veriler eski, dolayısıyla kullanışsız."],["Das alte System war stabil, wohingegen das neue abstürzt.","Eski sistem stabildi, oysa yenisi çöküyor."],["Das ist insofern schwierig, als niemand Zeit hat.","Kimsenin vakti olmadığı ölçüde bu zor."]];
X["C1-9"]=[["Das ist ein berechtigter Einwand.","Bu haklı bir itiraz."],["Ich gebe zu bedenken, dass die Zeit knapp ist.","Zamanın kısıtlı olduğunu hatırlatırım."],["Wir dürfen die Risiken nicht außer Acht lassen.","Riskleri göz ardı edemeyiz."],["Wir haben uns auf einen Preis geeinigt.","Bir fiyatta uzlaştık."],["Das ist ein fairer Kompromiss.","Bu adil bir uzlaşma."],["Wir kommen Ihnen gern entgegen.","Size memnuniyetle orta yolu öneriyoruz."],["Worauf willst du hinaus?","Ne demek istiyorsun?"],["Wir müssen die Vor- und Nachteile abwägen.","Artıları ve eksileri tartmalıyız."],["Das Argument ist überzeugend.","Argüman ikna edici."],["Wir verhandeln noch.","Hâlâ müzakere ediyoruz."],["Dagegen ließe sich einwenden, dass es zu teuer ist.","Buna çok pahalı olduğu itirazı yapılabilir."],["Wäre es nicht besser, zu warten?","Beklemek daha iyi olmaz mıydı?"]];
X["C1-10"]=[["Hiermit kündige ich meinen Vertrag.","İşbu yazıyla sözleşmemi feshediyorum."],["Anbei finden Sie die Rechnung.","Faturayı ekte bulabilirsiniz."],["Beiliegend sende ich Ihnen meinen Pass.","Pasaportumu ekte gönderiyorum."],["Bitte antworten Sie umgehend.","Lütfen derhâl cevap verin."],["Das Angebot ist verbindlich.","Teklif bağlayıcıdır."],["Bitte zahlen Sie spätestens am Freitag.","Lütfen en geç cuma günü ödeyin."],["Bitte bestätigen Sie den Eingang.","Lütfen alındığını onaylayın."],["Die Kündigung erfolgte fristgerecht.","Fesih süresinde yapıldı."],["Bezugnehmend auf Ihre Mail sende ich die Daten.","E-postanıza atfen verileri gönderiyorum."],["Ich lege Widerspruch ein.","İtiraz ediyorum."],["Für Rückfragen stehe ich gern zur Verfügung.","Ek sorularınız için hazırım."],["Mit freundlichen Grüßen, Mahsun Ak","Saygılarımla, Mahsun Ak"]];
X["C1-11"]=[["Im Jänner ist es in Wien kalt.","Ocakta Viyana soğuk."],["Ein Kilo Paradeiser, bitte.","Bir kilo domates lütfen."],["Ich esse gern Erdäpfel.","Patates yemeyi severim."],["Eine Melange, bitte.","Bir melange lütfen."],["Zwei Semmeln, bitte.","İki küçük ekmek lütfen."],["Grüß Gott, Frau Huber!","Merhaba Bayan Huber!"],["Servus, wie geht's?","Selam, nasılsın?"],["Brauchen Sie ein Sackerl?","Poşet ister misiniz?"],["Ich brauche einen Meldezettel.","Adres kayıt belgesine ihtiyacım var."],["Sie hat die Matura gemacht.","Lise bitirme sınavını verdi."],["In der Trafik kaufe ich eine Zeitung.","Bayiden bir gazete alıyorum."],["Kaffee mit Schlagobers, bitte.","Kremalı kahve lütfen."]];

window.BOOKS=[];
BOOKS.push({id:"a1-berlin",lv:"A1",t:"Ein Tag in Berlin",tr:"Berlin'de bir gün",em:"🏙️",c:["#0a84ff","#5e5ce6"],p:[
"Das ist Lukas. Lukas ist dreißig Jahre alt. Er wohnt in Berlin. Er hat eine kleine Wohnung im Zentrum. Die Wohnung hat zwei Zimmer, eine Küche und ein Bad. Lukas wohnt allein. Er ist nicht verheiratet. Er hat aber eine Katze. Die Katze heißt Mimi. Mimi ist schwarz und weiß.",
"Es ist Montag. Es ist sechs Uhr. Der Wecker klingelt. Lukas ist noch müde. Er bleibt noch fünf Minuten im Bett. Dann steht er auf. Er geht ins Bad. Er duscht und putzt die Zähne. Mimi sitzt vor der Tür. Sie hat Hunger.",
"Lukas geht in die Küche. Er gibt Mimi das Essen. Dann macht er Kaffee. Er trinkt seinen Kaffee mit Milch und ohne Zucker. Er isst ein Brötchen mit Käse. Das Brötchen ist frisch. Lukas hört Radio. Im Radio sagt eine Frau: Heute ist es sonnig in Berlin.",
"Um halb acht geht Lukas aus dem Haus. Er sagt: Tschüss, Mimi! Die Straße ist schon voll. Viele Leute gehen zur Arbeit. Lukas geht zur U-Bahn. Die U-Bahn-Station ist nicht weit. Er geht nur fünf Minuten zu Fuß.",
"Die U-Bahn kommt. Lukas steigt ein. Die U-Bahn ist sehr voll. Lukas steht. Er hat keinen Platz. Neben ihm steht eine alte Frau. Ein junger Mann steht auf. Er sagt: Bitte, setzen Sie sich. Die Frau sagt: Danke, das ist sehr nett.",
"Lukas fährt sechs Stationen. Dann steigt er aus. Er arbeitet in einem Büro am Alexanderplatz. Das Büro ist im zehnten Stock. Lukas nimmt den Aufzug. Er ist Informatiker. Er arbeitet mit Computern. Seine Arbeit ist interessant, aber manchmal auch stressig.",
"Im Büro sagt Lukas: Guten Morgen! Seine Kollegin heißt Sara. Sara kommt aus Italien. Sie spricht Italienisch, Englisch und Deutsch. Sara sagt: Guten Morgen, Lukas! Wie geht es dir? Lukas sagt: Gut, danke. Und dir? Sara sagt: Auch gut. Aber ich bin ein bisschen müde.",
"Lukas setzt sich an seinen Tisch. Er macht den Computer an. Er hat heute viele E-Mails. Er liest die E-Mails und antwortet. Um zehn Uhr hat er eine Besprechung. Die Besprechung dauert eine Stunde. Der Chef heißt Herr Wagner. Herr Wagner ist streng, aber fair.",
"In der Besprechung sprechen sie über ein neues Projekt. Das Projekt ist für eine Bank. Herr Wagner sagt: Das Projekt ist sehr wichtig. Wir haben nur drei Monate Zeit. Lukas denkt: Drei Monate ist nicht viel. Aber er sagt nichts. Sara macht Notizen.",
"Um zwölf Uhr hat Lukas Hunger. Er geht mit Sara in die Kantine. Heute gibt es Nudeln mit Tomatensoße oder Fisch mit Kartoffeln. Lukas nimmt die Nudeln. Sara nimmt den Fisch. Sie trinken Wasser. Das Essen kostet sechs Euro. Es ist nicht teuer.",
"Beim Essen fragt Sara: Was machst du am Wochenende? Lukas sagt: Ich weiß es noch nicht. Vielleicht gehe ich ins Museum. Sara sagt: Gute Idee! In Berlin gibt es viele Museen. Ich gehe am Samstag ins Kino. Kommst du mit? Lukas sagt: Ja, gern!",
"Nach dem Essen trinken sie noch einen Kaffee. Dann gehen sie zurück ins Büro. Am Nachmittag arbeitet Lukas am Computer. Er schreibt ein Programm. Das Programm funktioniert nicht. Lukas sucht den Fehler. Er sucht eine Stunde. Endlich findet er den Fehler.",
"Um drei Uhr ruft seine Mutter an. Lukas sagt: Hallo, Mama! Ich bin noch im Büro. Seine Mutter fragt: Kommst du am Sonntag zum Essen? Lukas sagt: Ja, natürlich. Um wie viel Uhr? Seine Mutter sagt: Um eins. Ich koche Hähnchen. Lukas freut sich. Seine Mutter kocht sehr gut.",
"Um halb sechs macht Lukas Feierabend. Er sagt: Tschüss, Sara! Bis morgen! Sara sagt: Tschüss, Lukas! Schönen Abend! Lukas nimmt den Aufzug. Er geht aus dem Haus. Draußen scheint die Sonne. Es ist warm. Lukas fährt heute nicht mit der U-Bahn nach Hause.",
"Er geht zu Fuß. Er geht durch den Park. Im Park spielen Kinder. Ein Mann joggt. Zwei Frauen sitzen auf einer Bank und lachen. Ein Hund läuft über das Gras. Lukas mag den Park. Hier ist es ruhig und grün. Er bleibt ein bisschen und sieht die Bäume an.",
"Dann geht Lukas in einen Supermarkt. Er braucht Brot, Milch, Eier und Tomaten. Er kauft auch Katzenfutter für Mimi. Im Supermarkt ist es voll. Lukas wartet zehn Minuten an der Kasse. Er bezahlt mit Karte. Alles kostet zweiundzwanzig Euro.",
"Lukas kommt nach Hause. Mimi wartet schon an der Tür. Sie sagt: Miau! Lukas lacht und sagt: Hallo, Mimi! Hast du Hunger? Natürlich hat Mimi Hunger. Mimi hat immer Hunger. Lukas gibt ihr das Futter. Dann stellt er die Einkäufe in den Kühlschrank.",
"Jetzt kocht Lukas. Er macht ein Omelett mit Tomaten und Käse. Er kocht nicht oft, aber ein Omelett kann er gut machen. Er isst am Tisch in der Küche. Dazu trinkt er ein Glas Wasser. Das Omelett schmeckt gut. Lukas ist zufrieden.",
"Nach dem Essen wäscht Lukas das Geschirr. Dann ruft er seinen Freund Tom an. Tom wohnt in Hamburg. Lukas und Tom sind alte Freunde. Sie telefonieren eine halbe Stunde. Tom sagt: Komm doch mal nach Hamburg! Lukas sagt: Ja, vielleicht im Sommer.",
"Am Abend sitzt Lukas auf dem Sofa. Mimi liegt neben ihm. Lukas liest ein Buch. Das Buch ist ein Krimi. Es ist sehr spannend. Lukas liest und liest. Er sieht nicht auf die Uhr. Plötzlich ist es schon zehn Uhr.",
"Lukas denkt: Oh, es ist schon spät! Morgen muss ich wieder früh aufstehen. Er macht das Buch zu. Er geht ins Bad und putzt die Zähne. Dann geht er ins Schlafzimmer. Mimi kommt mit. Sie schläft immer auf dem Bett.",
"Lukas liegt im Bett. Er denkt an den Tag. Der Tag war gut. Die Arbeit war interessant. Das Essen war lecker. Der Park war schön. Er denkt auch an Samstag. Am Samstag geht er mit Sara ins Kino. Er freut sich.",
"Es ist Dienstag. Der Wecker klingelt wieder um sechs Uhr. Lukas steht auf. Heute regnet es. Der Himmel ist grau. Lukas nimmt seinen Regenschirm. Er fährt heute wieder mit der U-Bahn. Im Regen geht er nicht gern zu Fuß.",
"Die Woche ist lang. Lukas arbeitet viel. Das neue Projekt ist schwer. Jeden Tag gibt es eine Besprechung. Am Mittwoch arbeitet Lukas bis acht Uhr am Abend. Er ist sehr müde. Aber das Projekt geht gut. Herr Wagner ist zufrieden.",
"Am Donnerstag sagt Herr Wagner: Lukas, Sie machen gute Arbeit. Danke! Lukas freut sich sehr. Herr Wagner sagt nicht oft danke. Sara lacht und sagt: Super, Lukas! Am Freitag gehen alle Kollegen zusammen essen. Sie gehen in ein türkisches Restaurant.",
"Das Restaurant heißt Istanbul. Es ist klein, aber sehr gemütlich. Der Kellner ist freundlich. Lukas bestellt Döner mit Salat. Sara bestellt Linsensuppe und Reis. Zum Nachtisch essen alle Baklava. Lukas sagt: Das ist das beste Baklava in Berlin!",
"Am Samstag schläft Lukas lange. Er steht erst um zehn Uhr auf. Er frühstückt in Ruhe. Am Nachmittag geht er ins Museum. Das Museum ist sehr groß. Lukas sieht alte Bilder und Statuen. Es ist interessant, aber nach drei Stunden tun ihm die Füße weh.",
"Am Abend trifft Lukas Sara vor dem Kino. Sara sagt: Hallo! Ich habe schon die Karten. Der Film ist eine Komödie. Er ist sehr lustig. Lukas und Sara lachen viel. Nach dem Film trinken sie noch etwas in einer Bar. Sie sprechen über Filme, Musik und Reisen.",
"Am Sonntag fährt Lukas zu seiner Mutter. Sie wohnt in einem kleinen Haus am Stadtrand. Sie hat einen Garten mit vielen Blumen. Seine Mutter sagt: Da bist du ja! Komm rein, das Essen ist fertig. Das Hähnchen ist wunderbar. Lukas isst zwei Teller.",
"Am Abend ist Lukas wieder zu Hause. Mimi liegt auf dem Sofa. Lukas setzt sich neben sie. Er denkt: Berlin ist groß und laut, aber ich wohne gern hier. Ich habe eine gute Arbeit, gute Freunde und eine tolle Katze. Mimi sagt: Miau. Lukas lacht. Ende."]});

BOOKS.push({id:"a1-wohnung",lv:"A1",t:"Die neue Wohnung",tr:"Yeni daire",em:"🏠",c:["#ff9f0a","#ff375f"],p:[
"Anna ist fünfundzwanzig Jahre alt. Sie kommt aus Stuttgart. Sie ist Krankenschwester. Sie hat eine neue Arbeit in München. Die Arbeit beginnt in einem Monat. Anna braucht eine Wohnung in München. Aber Wohnungen in München sind teuer.",
"Anna sucht im Internet. Sie findet viele Anzeigen. Eine Wohnung ist schön, aber sie kostet zweitausend Euro. Das ist zu teuer. Eine andere Wohnung ist billig, aber sie ist sehr klein. Sie hat nur ein Zimmer und keine Küche. Anna ist ein bisschen traurig.",
"Dann findet sie eine gute Anzeige. Zwei Zimmer, Küche, Bad, Balkon. Neunhundert Euro warm. Die Wohnung liegt in der Nähe von einem Park. Anna ruft sofort an. Ein Mann sagt: Hallo, hier ist Berger. Anna sagt: Guten Tag, ich heiße Anna Schulz. Ist die Wohnung noch frei?",
"Herr Berger sagt: Ja, die Wohnung ist noch frei. Möchten Sie die Wohnung sehen? Anna sagt: Ja, gern! Wann geht es? Herr Berger sagt: Am Samstag um elf Uhr. Passt Ihnen das? Anna sagt: Ja, das passt sehr gut. Vielen Dank!",
"Am Samstag fährt Anna mit dem Zug nach München. Der Zug fährt zwei Stunden. Anna sieht aus dem Fenster. Sie sieht Felder, Wälder und kleine Dörfer. Sie ist ein bisschen nervös. Sie denkt: Hoffentlich ist die Wohnung schön.",
"In München nimmt Anna die U-Bahn. Dann geht sie zu Fuß. Die Straße ist ruhig. Es gibt viele Bäume. Das Haus ist alt und gelb. Es hat vier Stockwerke. Vor dem Haus wartet ein Mann mit grauen Haaren. Das ist Herr Berger.",
"Herr Berger sagt: Guten Tag, Frau Schulz! Herzlich willkommen. Die Wohnung ist im dritten Stock. Leider gibt es keinen Aufzug. Anna sagt: Kein Problem. Ich gehe gern zu Fuß. Sie gehen die Treppe hoch. Herr Berger öffnet die Tür.",
"Die Wohnung ist hell. Sie hat große Fenster. Das Wohnzimmer ist groß und schön. Der Boden ist aus Holz. Das Schlafzimmer ist kleiner, aber auch hell. Von dort sieht man den Park. Anna gefällt das sehr.",
"Die Küche ist nicht groß, aber praktisch. Es gibt einen Herd, einen Kühlschrank und eine Spülmaschine. Das Bad hat eine Dusche, aber keine Badewanne. Anna duscht sowieso lieber. Dann zeigt Herr Berger den Balkon. Der Balkon ist klein, aber sonnig.",
"Anna fragt: Wie hoch sind die Nebenkosten? Herr Berger sagt: Die Nebenkosten sind schon im Preis. Neunhundert Euro mit Heizung und Wasser. Strom und Internet zahlen Sie extra. Die Kaution ist zwei Monatsmieten. Anna denkt kurz nach.",
"Anna sagt: Die Wohnung gefällt mir sehr gut. Ich nehme sie! Herr Berger lacht und sagt: Sehr schön. Sie sind sympathisch. Ich schicke Ihnen den Mietvertrag per E-Mail. Sie können am ersten Juni einziehen. Anna ist sehr glücklich.",
"Zurück in Stuttgart erzählt Anna alles ihrer Freundin Lisa. Lisa sagt: Super! Herzlichen Glückwunsch! Brauchst du Hilfe beim Umzug? Anna sagt: Ja, sehr gern. Mein Bruder hat ein Auto, aber er hat nicht viel Zeit. Lisa sagt: Kein Problem, ich komme mit.",
"Jetzt muss Anna packen. Sie hat viele Sachen. Sie hat Kleidung, Bücher, Schuhe, Teller und Tassen. Sie packt alles in Kartons. Am Ende hat sie zwanzig Kartons. Anna sagt: So viele Sachen! Ich brauche nicht alles. Sie verkauft ein paar Sachen im Internet.",
"Am einunddreißigsten Mai kommt der Bruder von Anna. Er heißt Felix. Er hat einen großen Transporter gemietet. Felix, Lisa und Anna tragen die Kartons zum Auto. Das Sofa ist sehr schwer. Sie brauchen eine halbe Stunde für das Sofa.",
"Am ersten Juni fahren sie früh nach München. Die Fahrt dauert drei Stunden. Es gibt viel Verkehr auf der Autobahn. Im Auto hören sie Musik und singen. Lisa hat Brötchen und Kaffee dabei. Die Stimmung ist gut.",
"In München warten sie vor dem Haus. Herr Berger gibt Anna die Schlüssel. Er sagt: Viel Glück in der neuen Wohnung! Jetzt beginnt die schwere Arbeit. Sie tragen alle Kartons in den dritten Stock. Ohne Aufzug ist das nicht leicht.",
"Nach zwei Stunden sind alle Sachen in der Wohnung. Felix sagt: Ich kann nicht mehr! Meine Arme tun weh. Lisa lacht und sagt: Ich habe Hunger! Anna sagt: Ich lade euch zum Essen ein. Hier um die Ecke gibt es eine Pizzeria.",
"Die Pizzeria ist klein und gemütlich. Sie essen Pizza und trinken Limonade. Felix isst eine ganze Pizza und noch einen Salat. Anna sagt: Danke für eure Hilfe. Ohne euch geht das nicht. Felix sagt: Gern geschehen, Schwesterchen.",
"Am Abend fahren Felix und Lisa zurück nach Stuttgart. Anna ist jetzt allein in der neuen Wohnung. Überall stehen Kartons. Das Bett ist noch nicht fertig. Anna schläft in der ersten Nacht auf dem Sofa. Aber sie ist glücklich.",
"Am nächsten Morgen packt Anna die Kartons aus. Sie stellt die Bücher ins Regal. Sie hängt die Kleidung in den Schrank. Sie stellt die Teller und Tassen in die Küche. Am Nachmittag baut sie das Bett auf. Das dauert lange.",
"Dann geht Anna einkaufen. Sie braucht noch viele Dinge. Sie kauft eine Lampe, einen Teppich und zwei Pflanzen. Für den Balkon kauft sie einen kleinen Tisch und zwei Stühle. Alles zusammen kostet hundertfünfzig Euro.",
"Am Abend klingelt es an der Tür. Vor der Tür steht eine Frau mit einem Kuchen. Sie sagt: Hallo! Ich bin Frau Huber. Ich wohne unter Ihnen im zweiten Stock. Willkommen im Haus! Anna sagt: Oh, danke! Das ist so nett. Kommen Sie doch rein!",
"Frau Huber ist etwa siebzig Jahre alt. Sie wohnt schon vierzig Jahre in dem Haus. Sie kennt alle Nachbarn. Sie trinken Kaffee und essen Kuchen. Frau Huber erzählt: Der Mann im ersten Stock spielt Klavier. Er spielt sehr schön, aber manchmal auch spät.",
"Frau Huber fragt: Was machen Sie beruflich? Anna sagt: Ich bin Krankenschwester. Ich arbeite ab Montag im Krankenhaus hier in der Nähe. Frau Huber sagt: Wunderbar! Dann wohnen Sie nah an der Arbeit. Das ist praktisch.",
"Am Montag beginnt die neue Arbeit. Anna geht zu Fuß zum Krankenhaus. Sie braucht nur fünfzehn Minuten. Die Kolleginnen sind nett. Die Arbeit ist anstrengend, aber Anna liebt ihren Beruf. Sie hilft gern Menschen.",
"Nach einer Woche ist die Wohnung fertig. Alles hat seinen Platz. Die Pflanzen stehen am Fenster. Der Teppich liegt im Wohnzimmer. An der Wand hängen Fotos von ihrer Familie. Anna sitzt auf dem Balkon und trinkt Tee.",
"Am Wochenende lädt Anna Frau Huber und die anderen Nachbarn ein. Der Mann aus dem ersten Stock heißt Herr Kraus. Er bringt Wein mit. Im vierten Stock wohnt eine junge Familie mit zwei Kindern. Die Kinder heißen Ben und Mia.",
"Alle sitzen zusammen im Wohnzimmer. Anna hat Salat, Brot und Käse gemacht. Die Kinder spielen auf dem Balkon. Herr Kraus erzählt Witze. Alle lachen. Frau Huber sagt: So ein schöner Abend! Früher haben wir oft zusammen gefeiert.",
"Später spielt Herr Kraus im ersten Stock Klavier. Die Musik kommt durch das Fenster. Anna hört zu. Sie denkt: Ich habe eine schöne Wohnung, nette Nachbarn und eine gute Arbeit. München ist jetzt mein Zuhause.",
"Am Abend ruft Anna ihre Mutter an. Sie sagt: Mama, es geht mir sehr gut hier. Die Wohnung ist toll und die Nachbarn sind wunderbar. Ihre Mutter sagt: Das freut mich so, mein Schatz. Wir besuchen dich bald. Anna lächelt. Ende."]});

BOOKS.push({id:"a1-cafe",lv:"A1",t:"Treffpunkt Café Mondo",tr:"Buluşma noktası: Café Mondo",em:"☕",c:["#ac8e68","#ff9f0a"],p:[
"In einer kleinen Straße in Köln gibt es ein Café. Das Café heißt Mondo. Es ist nicht groß. Es hat zehn Tische und eine kleine Terrasse. Die Besitzerin heißt Elena. Elena kommt aus Griechenland. Sie wohnt seit zwanzig Jahren in Deutschland.",
"Das Café öffnet jeden Morgen um sieben Uhr. Elena kommt schon um sechs. Sie backt Kuchen und macht Brötchen. Ihr Apfelkuchen ist berühmt. Alle Leute in der Straße kennen ihn. Elena sagt immer: Der Kuchen ist mit Liebe gemacht.",
"Um sieben Uhr kommt der erste Gast. Das ist Herr Schmitz. Er ist Rentner. Er kommt jeden Tag. Er bestellt immer das Gleiche: einen schwarzen Kaffee und ein Croissant. Er liest die Zeitung. Er sagt nicht viel, aber er ist freundlich.",
"Elena sagt: Guten Morgen, Herr Schmitz! Wie immer? Herr Schmitz sagt: Ja, bitte. Wie immer. Elena bringt den Kaffee und das Croissant. Herr Schmitz liest die Zeitung. Manchmal sagt er: Oh, das ist ja interessant! Aber er erklärt nie, was er liest.",
"Um acht Uhr kommen viele Leute. Sie haben wenig Zeit. Sie gehen zur Arbeit. Sie nehmen Kaffee zum Mitnehmen. Ein Mann im Anzug sagt: Einen Cappuccino, bitte. Schnell, bitte! Elena lacht und sagt: Immer mit der Ruhe! Der Kaffee kommt sofort.",
"Um neun Uhr wird es ruhiger. Dann kommt Jonas. Jonas ist Student. Er studiert Architektur. Er kommt oft mit seinem Laptop. Er arbeitet im Café, weil es zu Hause zu laut ist. Er wohnt mit drei Freunden in einer WG.",
"Jonas bestellt einen Tee und ein Stück Apfelkuchen. Er sagt: Elena, dein Kuchen ist der beste in Köln! Elena sagt: Danke, Jonas! Aber du isst zu viel Kuchen. Du brauchst auch mal Gemüse! Jonas lacht. Er arbeitet bis mittags.",
"Heute sitzt eine junge Frau am Tisch neben Jonas. Sie hat ein Buch auf Deutsch und ein Wörterbuch. Sie liest langsam. Manchmal sucht sie ein Wort im Wörterbuch. Jonas sieht sie an. Sie sieht ein bisschen verzweifelt aus.",
"Jonas fragt: Entschuldigung, kann ich helfen? Die Frau sagt: Oh, danke! Ich lerne Deutsch. Ich verstehe dieses Wort nicht. Sie zeigt auf das Wort Feierabend. Jonas erklärt: Feierabend ist das Ende von der Arbeit. Dann hast du frei.",
"Die Frau lacht und sagt: Ah, jetzt verstehe ich! Danke! Ich heiße Ayşe. Ich komme aus der Türkei, aus Izmir. Jonas sagt: Freut mich! Ich bin Jonas. Was machst du in Köln? Ayşe sagt: Ich bin Ingenieurin. Ich arbeite seit drei Monaten hier.",
"Ayşe und Jonas sprechen lange. Ayşe erzählt von Izmir. Es gibt dort das Meer und viel Sonne. Jonas sagt: Das klingt wunderbar! In Köln regnet es so oft. Ayşe lacht und sagt: Ja, das stimmt. Ich vermisse die Sonne.",
"Elena bringt zwei Stück Kuchen an den Tisch. Sie sagt: Das ist ein Geschenk vom Haus. Für die neue Freundschaft! Ayşe sagt: Oh, vielen Dank! Das ist so nett. Ayşe probiert den Kuchen. Sie sagt: Mmh, sehr lecker!",
"Ab jetzt kommt Ayşe oft ins Café Mondo. Sie trifft Jonas und lernt Deutsch. Jonas hilft ihr mit der Grammatik. Ayşe hilft Jonas mit Mathematik. Er hat bald eine Prüfung in Statik. Ayşe ist Ingenieurin, sie kann das sehr gut.",
"Am Mittwoch ist das Café besonders voll. Am Mittwochabend gibt es den Sprachtreff. Leute aus vielen Ländern kommen. Sie sprechen Deutsch zusammen. Es gibt Menschen aus Spanien, Brasilien, Polen, Japan und Syrien.",
"Elena macht an diesem Abend Musik. Es gibt Tee und kleine Snacks. Jeder Tisch hat ein Thema. Am ersten Tisch sprechen die Leute über Essen. Am zweiten Tisch sprechen sie über Reisen. Am dritten Tisch sprechen sie über Arbeit.",
"Ayşe sitzt am Tisch mit dem Thema Essen. Ein Mann aus Spanien erzählt von Paella. Eine Frau aus Japan erzählt von Sushi. Ayşe erzählt von Menemen. Das ist ein türkisches Frühstück mit Eiern, Tomaten und Paprika. Alle sagen: Das wollen wir probieren!",
"Ayşe hat eine Idee. Sie fragt Elena: Darf ich nächste Woche Menemen im Café kochen? Für den Sprachtreff? Elena sagt: Natürlich! Das ist eine tolle Idee. Wir machen einen internationalen Abend. Jeder bringt etwas aus seinem Land mit.",
"Eine Woche später ist der internationale Abend. Das Café ist voll. Auf den Tischen stehen viele Gerichte. Es gibt Paella, Sushi, Pierogi, Hummus und Menemen. Elena hat natürlich ihren Apfelkuchen gebacken. Es riecht wunderbar.",
"Sogar Herr Schmitz kommt. Er kommt sonst nie am Abend. Er probiert alles. Er sagt: Das Menemen ist ausgezeichnet! Ayşe ist sehr stolz. Herr Schmitz erzählt: Ich war vor dreißig Jahren in der Türkei. In Antalya. Es war wunderschön.",
"An diesem Abend redet Herr Schmitz viel. Er erzählt von seinen Reisen. Er war in Italien, in Griechenland, in Marokko und in Ägypten. Alle hören zu. Elena flüstert zu Jonas: So viel hat er in zehn Jahren nicht gesprochen!",
"Spät am Abend sind alle satt und glücklich. Ein Mann aus Brasilien spielt Gitarre. Die Leute singen. Elena sagt: Das ist der schönste Abend im Café Mondo! Wir machen das jetzt jeden Monat. Alle klatschen.",
"Im Herbst hat Jonas seine Prüfung. Er ist sehr nervös. Am Morgen kommt er ins Café. Er kann nichts essen. Elena sagt: Du schaffst das! Ayşe schickt ihm eine Nachricht: Viel Glück! Du kannst das! Jonas geht zur Universität.",
"Am Nachmittag kommt Jonas zurück ins Café. Er lacht. Er ruft: Ich habe bestanden! Mit einer Zwei! Alle im Café klatschen. Ayşe umarmt ihn. Jonas sagt: Danke, Ayşe! Ohne deine Hilfe hätte ich das nicht geschafft.",
"Auch Ayşe macht Fortschritte. Ihr Deutsch wird jeden Tag besser. Sie liest jetzt Bücher ohne Wörterbuch. Bei der Arbeit spricht sie nur noch Deutsch. Ihr Chef sagt: Ihr Deutsch ist wirklich sehr gut geworden!",
"Im Winter ist es kalt und dunkel in Köln. Aber im Café Mondo ist es warm. Elena macht heißen Kakao mit Sahne. Die Fenster sind voller Lichter. Draußen schneit es. Drinnen sitzen die Freunde zusammen und erzählen.",
"Eines Tages kommt Herr Schmitz nicht. Auch am nächsten Tag kommt er nicht. Elena macht sich Sorgen. Sie sagt: Das ist nicht normal. Er kommt jeden Tag seit zehn Jahren. Jonas sagt: Weißt du, wo er wohnt? Elena sagt: Ja, in der Nummer zwölf.",
"Elena, Jonas und Ayşe gehen zu seinem Haus. Sie klingeln. Nach langer Zeit öffnet Herr Schmitz die Tür. Er hat eine Erkältung. Er hat Fieber und Husten. Er sagt: Oh, ihr seid es! Kommt rein. Ich bin seit zwei Tagen krank.",
"Elena bringt ihm Suppe. Ayşe geht zur Apotheke und kauft Medikamente. Jonas macht Tee. Herr Schmitz ist sehr gerührt. Er sagt: Ich lebe allein. Meine Frau ist vor fünf Jahren gestorben. Ich habe keine Familie mehr. Aber jetzt habe ich euch.",
"Nach einer Woche ist Herr Schmitz wieder gesund. Er kommt wieder ins Café. Er bestellt wie immer einen schwarzen Kaffee und ein Croissant. Aber er liest heute keine Zeitung. Er setzt sich zu Jonas und Ayşe an den Tisch.",
"Elena sieht ihre Gäste an. Sie lächelt. Sie denkt: Ein Café ist mehr als Kaffee und Kuchen. Ein Café ist ein Ort für Menschen. Hier finden Menschen Freunde. Sie bringt einen großen Apfelkuchen an den Tisch. Für alle. Ende."]});

BOOKS.push({id:"a1-familie",lv:"A1",t:"Familie Yılmaz in Wien",tr:"Yılmaz ailesi Viyana'da",em:"🎡",c:["#ff375f","#bf5af2"],p:[
"Das ist Familie Yılmaz. Der Vater heißt Emre. Er ist vierzig Jahre alt. Er ist Ingenieur. Die Mutter heißt Zeynep. Sie ist achtunddreißig Jahre alt. Sie ist Lehrerin. Sie haben zwei Kinder. Der Sohn heißt Can. Er ist zwölf. Die Tochter heißt Elif. Sie ist acht.",
"Familie Yılmaz kommt aus Istanbul. Seit einem Monat wohnt die Familie in Wien. Emre hat hier eine neue Arbeit. Er arbeitet bei einer großen Firma. Die Firma baut Brücken und Straßen. Emre spricht gut Deutsch. Er hat in Istanbul zwei Jahre Deutsch gelernt.",
"Zeynep spricht noch nicht so gut Deutsch. Sie lernt jeden Tag. Sie macht einen Deutschkurs. Der Kurs ist am Vormittag, von neun bis zwölf Uhr. In ihrem Kurs sind Menschen aus vielen Ländern. Die Lehrerin heißt Frau Gruber. Sie ist sehr geduldig.",
"Die Wohnung von Familie Yılmaz ist im zweiten Bezirk. Sie hat drei Zimmer. Can und Elif haben jeder ein eigenes Zimmer. Das finden sie toll. In Istanbul hatten sie nur ein Zimmer zusammen. Die Wohnung hat auch einen kleinen Balkon.",
"Am Morgen frühstückt die Familie zusammen. Es gibt Brot, Käse, Oliven, Tomaten und Gurken. Zeynep macht Tee. Türkischer Tee ist wichtig für die Familie. Emre sagt: Ohne Tee kann ich nicht arbeiten! Die Kinder trinken Milch.",
"Can und Elif gehen in eine Schule in der Nähe. Die Schule ist nur zehn Minuten zu Fuß. Can ist in der zweiten Klasse vom Gymnasium. Elif ist in der dritten Klasse von der Volksschule. In Österreich heißt die Grundschule Volksschule.",
"Der erste Schultag war schwer für Can. Er hat nicht alles verstanden. Die Lehrer sprechen schnell. Die anderen Kinder sprechen auch Dialekt. Can war traurig. Am Abend hat er gesagt: Mama, ich will zurück nach Istanbul!",
"Zeynep hat ihn in den Arm genommen. Sie hat gesagt: Ich verstehe dich, mein Schatz. Am Anfang ist alles schwer. Aber du lernst schnell. In ein paar Monaten sprichst du besser Deutsch als ich! Can hat ein bisschen gelacht.",
"Elif hat weniger Probleme. Sie ist offen und spricht mit allen. In ihrer Klasse ist ein Mädchen. Sie heißt Lena. Lena und Elif sitzen nebeneinander. Lena hilft Elif mit den Wörtern. Elif zeigt Lena türkische Spiele. Sie sind schnell beste Freundinnen.",
"Am Wochenende macht die Familie Ausflüge. Wien ist eine schöne Stadt. Es gibt viele alte Gebäude, Kirchen und Paläste. Am ersten Samstag besuchen sie das Schloss Schönbrunn. Das Schloss ist riesig. Es hat über tausend Zimmer.",
"Hinter dem Schloss ist ein großer Garten. Dort gibt es auch einen Zoo. Der Zoo ist sehr alt. Elif liebt die Pandas. Can findet die Elefanten am besten. Sie bleiben den ganzen Tag. Am Abend sind alle müde, aber glücklich.",
"Am Sonntag gehen sie in den Prater. Der Prater ist ein großer Park mit einem Vergnügungspark. Dort steht das Riesenrad. Das Riesenrad ist über hundert Jahre alt. Die Familie fährt mit dem Riesenrad. Von oben sieht man ganz Wien.",
"Elif hat ein bisschen Angst. Sie hält die Hand von ihrem Vater. Emre sagt: Schau, da ist der Stephansdom! Und da ist die Donau! Elif sieht aus dem Fenster. Jetzt hat sie keine Angst mehr. Sie sagt: Papa, das ist so schön!",
"Nach dem Riesenrad essen sie etwas. Es gibt Würstel mit Senf und Brot. Zeynep probiert ein Wiener Schnitzel. Sie sagt: Es ist gut, aber unser Köfte ist besser! Alle lachen. Can isst zwei Portionen Pommes.",
"Zeynep hat eine Idee. Sie möchte einen Markt finden. Sie vermisst den Markt in Istanbul. Ihre Nachbarin sagt: Gehen Sie zum Naschmarkt! Dort gibt es alles. Am Samstag geht Zeynep mit Elif zum Naschmarkt.",
"Der Naschmarkt ist lang und bunt. Es gibt Obst, Gemüse, Käse, Gewürze und Fisch. Es gibt auch türkische Stände. Zeynep findet Oliven, Börek und Simit. Ein Verkäufer spricht Türkisch. Er kommt aus Konya. Zeynep freut sich sehr.",
"Der Verkäufer heißt Mehmet. Er wohnt seit dreißig Jahren in Wien. Er sagt: Willkommen in Wien! Am Anfang ist es schwer. Aber Wien ist eine gute Stadt. Die Menschen sind nett, wenn man sie kennt. Er schenkt Elif einen Simit.",
"Im Deutschkurs lernt Zeynep viel. Heute lernen sie das Thema Einkaufen. Frau Gruber fragt: Zeynep, was kaufen Sie am Markt? Zeynep sagt: Ich kaufe Tomaten, Gurken und Brot. Und Oliven, natürlich! Alle lachen. Frau Gruber sagt: Sehr gut!",
"Zeynep hat eine Freundin im Kurs. Sie heißt Maria und kommt aus Rumänien. Maria hat auch zwei Kinder. Nach dem Kurs trinken sie zusammen Kaffee. Sie sprechen Deutsch. Manchmal fehlen die Wörter. Dann zeigen sie mit den Händen.",
"Can hat jetzt einen Freund. Er heißt David. David spielt Fußball in einem Verein. Er fragt Can: Spielst du auch Fußball? Can sagt: Ja, sehr gern! In Istanbul habe ich jeden Tag gespielt. David sagt: Komm doch mit zum Training!",
"Am Dienstag geht Can zum Training. Der Trainer heißt Herr Novak. Er sagt: Zeig mal, was du kannst! Can spielt sehr gut. Er schießt zwei Tore. Herr Novak sagt: Super! Du kannst gern in unserem Team spielen. Can ist überglücklich.",
"Jetzt geht Can gern in die Schule. Seine Freunde helfen ihm. Er versteht jeden Tag mehr. Sein Lieblingsfach ist Mathematik. In Mathe braucht man nicht so viel Deutsch, sagt er. Seine Lehrerin sagt: Can ist sehr klug.",
"Im Herbst wird es kalt in Wien. Die Blätter sind gelb und rot. Es regnet oft. Die Familie kauft warme Jacken. Elif bekommt eine rote Mütze. Sie sagt: In Istanbul war es nie so kalt! Emre sagt: Warte nur, bis der Winter kommt.",
"Im Dezember schneit es. Elif und Can haben noch nie so viel Schnee gesehen. Sie bauen einen Schneemann im Park. Der Schneemann hat eine Karotte als Nase. Can macht ein Foto. Er schickt das Foto an seine Oma in Istanbul.",
"Im Dezember gibt es in Wien viele Weihnachtsmärkte. Die Familie besucht den Markt vor dem Rathaus. Es gibt viele Lichter. Es riecht nach Zimt und Äpfeln. Die Kinder trinken Kinderpunsch. Zeynep kauft eine kleine Kerze.",
"Zum Jahresende kommt die Oma aus Istanbul zu Besuch. Sie heißt Fatma. Sie bleibt zwei Wochen. Sie bringt viele Geschenke mit. Sie bringt Baklava, Lokum und türkischen Kaffee. Die Kinder freuen sich sehr.",
"Oma Fatma spricht kein Deutsch. Aber Elif ist ihre Übersetzerin. Im Café sagt Elif zum Kellner: Meine Oma möchte einen Tee, bitte. Ohne Zucker. Der Kellner lächelt und sagt: Natürlich! Oma Fatma ist sehr stolz auf Elif.",
"Am letzten Abend sitzt die Familie zusammen. Oma Fatma fragt: Seid ihr hier glücklich? Emre denkt nach. Dann sagt er: Am Anfang war es schwer. Aber jetzt geht es uns gut. Die Kinder haben Freunde. Wir lernen jeden Tag.",
"Zeynep sagt: Ich vermisse Istanbul, das Meer und unsere Familie. Aber Wien ist auch schön. Hier haben wir neue Freunde. Can sagt: Und ich habe ein Fußballteam! Elif sagt: Und ich habe Lena! Alle lachen. Oma Fatma lächelt.",
"Im Frühling macht Zeynep die Deutschprüfung. Sie besteht die Prüfung mit gut. Sie bekommt ein Zertifikat. Am Abend feiert die Familie. Emre kocht Köfte. Zeynep sagt auf Deutsch: Ich bin so froh! Jetzt bin ich wirklich in Wien angekommen. Ende."]});

BOOKS.push({id:"a1-hund",lv:"A1",t:"Wo ist Bello?",tr:"Bello nerede?",em:"🐕",c:["#30d158","#0fb5ae"],p:[
"Paul ist zehn Jahre alt. Er wohnt mit seinen Eltern in einem kleinen Dorf in Bayern. Das Dorf hat nur tausend Einwohner. Es gibt eine Kirche, eine Bäckerei, einen kleinen Laden und eine Schule. Rund um das Dorf gibt es Wiesen, Wälder und Berge.",
"Paul hat einen Hund. Der Hund heißt Bello. Bello ist braun und hat lange Ohren. Er ist fünf Jahre alt. Bello ist sehr lieb, aber auch ein bisschen frech. Er spielt gern mit dem Ball. Er läuft gern über die Wiese. Und er liebt Würstchen.",
"Jeden Morgen geht Paul mit Bello spazieren. Sie gehen zur Bäckerei. Die Bäckerin heißt Frau Maier. Sie gibt Bello immer ein kleines Stück Brot. Bello wartet schon an der Tür. Er weiß genau: Bei Frau Maier gibt es etwas!",
"Dann geht Paul zur Schule. Bello bleibt zu Hause. Er liegt im Garten und schläft. Manchmal bellt er, wenn der Postbote kommt. Der Postbote heißt Herr Bauer. Er hat ein bisschen Angst vor Bello. Aber Bello will nur spielen.",
"Heute ist Samstag. Es gibt keine Schule. Die Sonne scheint. Paul sagt: Bello, komm! Wir gehen in den Wald! Bello springt und bellt. Er liebt den Wald. Paul nimmt einen Rucksack mit. Im Rucksack sind Wasser, ein Apfel und ein Ball.",
"Im Wald ist es kühl und ruhig. Die Vögel singen. Paul wirft den Ball. Bello läuft und holt den Ball. Paul wirft den Ball noch einmal. Und noch einmal. Bello ist nie müde. Paul lacht. Er sagt: Du bist der beste Hund der Welt!",
"Plötzlich sieht Bello etwas. Ein Reh steht zwischen den Bäumen. Bello bellt laut. Das Reh springt weg. Bello läuft hinter dem Reh her. Paul ruft: Bello! Bello, komm zurück! Aber Bello hört nicht. Er läuft tief in den Wald.",
"Paul läuft auch. Er ruft immer wieder: Bello! Bello! Aber er sieht Bello nicht mehr. Er hört ihn auch nicht mehr. Der Wald ist groß. Paul bleibt stehen. Er ist allein. Er hat Angst. Wo ist Bello?",
"Paul sucht eine Stunde lang. Er ruft und ruft. Seine Stimme ist schon heiser. Bello kommt nicht. Paul weint. Dann denkt er: Ich muss nach Hause gehen. Ich muss Mama und Papa fragen. Sie helfen mir bestimmt.",
"Paul läuft nach Hause. Seine Mutter arbeitet im Garten. Sie sieht Paul. Er weint. Sie fragt: Paul, was ist los? Wo ist Bello? Paul erzählt alles. Seine Mutter nimmt ihn in den Arm. Sie sagt: Keine Angst. Wir finden Bello. Ganz sicher.",
"Pauls Vater kommt aus dem Haus. Er sagt: Wir gehen sofort in den Wald. Ich nehme das Auto. Die Mutter sagt: Ich rufe die Nachbarn an. Vielleicht können sie helfen. Paul nimmt die Leine und ein Würstchen mit. Bello liebt Würstchen.",
"Viele Nachbarn kommen. Frau Maier von der Bäckerei kommt. Herr Bauer, der Postbote, kommt auch. Sogar der Bürgermeister kommt. Alle wollen helfen. Der Vater sagt: Wir gehen in Gruppen in den Wald. Jede Gruppe sucht in einer anderen Richtung.",
"Paul geht mit seinem Vater und Herrn Bauer. Herr Bauer sagt: Weißt du, Paul, ich hatte immer ein bisschen Angst vor Bello. Aber er ist ein guter Hund. Wir finden ihn. Paul lächelt ein bisschen. Er denkt: Herr Bauer ist nett.",
"Sie suchen am Fluss. Sie suchen bei der alten Hütte. Sie suchen auf dem Hügel. Aber sie finden Bello nicht. Es wird langsam dunkel. Der Vater sagt: Wir müssen bald nach Hause. Im Dunkeln können wir nichts sehen. Paul ist sehr traurig.",
"Zu Hause sitzt Paul am Fenster. Er sieht in den Garten. Er wartet. Seine Mutter macht ihm einen Tee. Sie sagt: Bello ist klug. Er findet bestimmt den Weg nach Hause. Paul sagt nichts. Er kann nicht essen. Er denkt nur an Bello.",
"In der Nacht kann Paul nicht schlafen. Draußen regnet es. Paul denkt: Bello ist allein im Wald. Es ist kalt und nass. Hat er Hunger? Hat er Angst? Paul steht auf und sieht aus dem Fenster. Aber er sieht nur Regen.",
"Am Sonntagmorgen ist der Regen vorbei. Die Sonne scheint wieder. Paul steht früh auf. Er schreibt Plakate. Auf den Plakaten steht: Hund verloren! Name: Bello. Farbe: braun. Lange Ohren. Bitte anrufen! Darunter steht die Telefonnummer.",
"Paul und seine Mutter hängen die Plakate im Dorf auf. Sie hängen ein Plakat an die Bäckerei. Ein Plakat hängt am Laden. Ein Plakat hängt an der Kirche. Auch in das Nachbardorf fahren sie. Dort hängen sie auch Plakate auf.",
"Am Nachmittag klingelt das Telefon. Paul läuft zum Telefon. Eine Frau sagt: Hallo, hier ist Frau Lang. Ich wohne auf einem Bauernhof hinter dem Wald. Hier ist ein brauner Hund mit langen Ohren. Ist das Ihr Hund?",
"Paul ruft: Mama! Papa! Vielleicht ist es Bello! Der Vater nimmt sofort die Autoschlüssel. Sie fahren zum Bauernhof. Der Weg ist lang und schmal. Paul sitzt im Auto und ist sehr nervös. Ist es wirklich Bello?",
"Am Bauernhof wartet eine alte Frau. Neben ihr steht ein Hund. Er ist braun. Er hat lange Ohren. Er ist schmutzig. Aber Paul erkennt ihn sofort. Er springt aus dem Auto und ruft: Bello! Der Hund dreht den Kopf. Dann bellt er und läuft zu Paul.",
"Bello springt an Paul hoch. Er leckt sein Gesicht. Er wedelt mit dem Schwanz. Paul lacht und weint gleichzeitig. Er sagt: Bello, du dummer Hund! Wo warst du? Ich habe dich so vermisst! Bello bellt. Er ist auch sehr glücklich.",
"Frau Lang erzählt: Heute Morgen war der Hund in meinem Stall. Er lag bei den Kühen. Er war nass und müde. Ich habe ihm Wasser und etwas zu essen gegeben. Dann habe ich im Dorf das Plakat gesehen. Pauls Vater sagt: Vielen, vielen Dank!",
"Frau Lang lädt die Familie zu Kaffee und Kuchen ein. Sie hat einen großen Bauernhof. Es gibt Kühe, Schweine, Hühner und zwei Pferde. Paul darf die Pferde streicheln. Frau Lang sagt: Komm doch mal wieder! Mit Bello natürlich.",
"Zu Hause badet Paul den Hund. Bello mag das Bad nicht. Er schüttelt sich. Jetzt ist auch Paul ganz nass. Die Mutter lacht. Dann bekommt Bello sein Lieblingsessen: Würstchen! Er frisst drei Würstchen auf einmal.",
"Am Abend kommen die Nachbarn. Sie wollen Bello sehen. Frau Maier bringt einen Kuchen. Herr Bauer streichelt Bello. Er sagt: Jetzt habe ich keine Angst mehr vor dir. Bello leckt seine Hand. Alle lachen.",
"Pauls Vater sagt: Danke an alle! Ihr wart wunderbar. Ohne euch hätten wir Bello nicht gefunden. Der Bürgermeister sagt: In unserem Dorf helfen wir uns. Das ist doch klar. Dann essen alle zusammen Kuchen im Garten.",
"In der Nacht schläft Bello nicht im Garten. Er schläft heute in Pauls Zimmer. Er liegt neben dem Bett. Paul streichelt seinen Kopf. Er sagt: Bello, versprich mir: Lauf nie wieder weg! Bello sieht ihn an und seufzt. Dann schläft er ein.",
"Am Montag geht Paul wieder zur Schule. Er erzählt seinen Freunden alles. Die Lehrerin sagt: Paul, schreib doch eine Geschichte darüber! Paul schreibt die Geschichte. Sie heißt: Wo ist Bello? Die Lehrerin hängt die Geschichte an die Wand.",
"Seitdem geht Paul mit Bello nur noch an der Leine in den Wald. Und jeden Samstag besuchen sie Frau Lang auf dem Bauernhof. Bello spielt mit den Hühnern. Paul reitet auf dem Pferd. Und Frau Lang hat immer ein Würstchen für Bello. Ende."]});

BOOKS.push({id:"a1-zug",lv:"A1",t:"Mit dem Zug nach München",tr:"Trenle Münih'e",em:"🚆",c:["#64d2ff","#0a84ff"],p:[
"Sofia ist dreiundzwanzig Jahre alt. Sie kommt aus Spanien, aus Madrid. Sie studiert seit einem Jahr in Frankfurt. Sie studiert Wirtschaft. Ihre Freundin Julia wohnt in München. Julia hat am Samstag Geburtstag. Sofia möchte sie besuchen.",
"Sofia sucht im Internet eine Fahrkarte. Mit dem Zug dauert die Fahrt etwa drei Stunden. Mit dem Bus dauert sie sechs Stunden. Der Zug ist teurer, aber schneller. Sofia findet ein Sparangebot. Die Fahrkarte kostet nur dreißig Euro. Sie kauft die Karte sofort.",
"Am Freitag packt Sofia ihren Koffer. Sie packt Kleidung für drei Tage ein. Sie packt auch ein Geschenk für Julia ein. Das Geschenk ist ein Buch und eine Kerze. Sie legt die Fahrkarte und ihren Ausweis auf den Tisch. Sie will nichts vergessen.",
"Am Samstag steht Sofia um sechs Uhr auf. Der Zug fährt um acht Uhr zwölf. Sofia trinkt schnell einen Kaffee. Dann nimmt sie die S-Bahn zum Hauptbahnhof. Die S-Bahn ist fast leer. Am Samstag schlafen viele Menschen lange.",
"Der Frankfurter Hauptbahnhof ist sehr groß. Es gibt viele Gleise. Überall sind Menschen mit Koffern. Sofia sieht auf die Anzeigetafel. Dort steht: ICE nach München, Abfahrt acht Uhr zwölf, Gleis neun. Sofia hat noch zwanzig Minuten Zeit.",
"Sofia kauft ein Brötchen und eine Flasche Wasser. Dann geht sie zum Gleis neun. Viele Leute warten schon. Eine Durchsage kommt: Achtung an Gleis neun. Der ICE nach München hat heute etwa fünfzehn Minuten Verspätung. Sofia seufzt. Typisch Deutsche Bahn!",
"Neben Sofia steht ein älterer Mann. Er hat einen Hut und einen großen Koffer. Er sagt: Verspätung, wie immer! Sofia lacht. Der Mann fragt: Fahren Sie auch nach München? Sofia sagt: Ja, ich besuche eine Freundin. Sie hat Geburtstag.",
"Der Mann heißt Herr Lehmann. Er fährt zu seiner Tochter. Sie wohnt auch in München. Sie hat ein Baby. Herr Lehmann sagt stolz: Ich bin seit zwei Wochen Opa! Er zeigt Sofia ein Foto auf dem Handy. Sofia sagt: Oh, wie süß!",
"Endlich kommt der Zug. Er ist weiß und lang. Sofia sucht ihren Wagen. Sie hat einen reservierten Platz in Wagen zwölf, Platz fünfundvierzig. Sie steigt ein. Der Zug ist voll. Sie findet ihren Platz am Fenster. Neben ihr sitzt eine junge Frau mit Kopfhörern.",
"Der Zug fährt los. Sofia sieht aus dem Fenster. Zuerst sieht sie die Stadt. Dann kommen Felder, Wälder und kleine Dörfer. Es ist Herbst. Die Bäume sind rot und gelb. Die Landschaft ist sehr schön.",
"Nach einer Stunde kommt der Schaffner. Er sagt: Guten Morgen, die Fahrkarten bitte! Sofia zeigt ihr Ticket auf dem Handy. Der Schaffner sagt: Und Ihren Ausweis, bitte. Sofia sucht in ihrer Tasche. Wo ist ihr Ausweis? Sie wird nervös.",
"Sofia sucht in der Jacke. Sie sucht im Rucksack. Der Ausweis ist nicht da. Dann denkt sie: Oh nein! Der Ausweis liegt noch zu Hause auf dem Tisch! Sie sagt: Es tut mir leid. Ich habe meinen Ausweis vergessen. Ich habe nur meinen Studentenausweis.",
"Der Schaffner sieht den Studentenausweis an. Er lächelt. Er sagt: Kein Problem. Der Studentenausweis hat ein Foto. Das reicht. Gute Fahrt! Sofia sagt: Vielen Dank! Sie ist sehr erleichtert. Die Frau neben ihr lacht und sagt: Glück gehabt!",
"Die Frau heißt Mia. Sie ist Musikerin. Sie spielt Geige in einem Orchester. Heute Abend hat sie ein Konzert in München. Sie sagt: Ich höre gerade das Stück für heute Abend. Ich bin ein bisschen nervös. Sofia sagt: Ich bin sicher, es wird toll.",
"Mia und Sofia sprechen lange. Mia erzählt von ihren Reisen mit dem Orchester. Sie war in Japan, in Amerika und in Australien. Sofia erzählt von Madrid. Mia sagt: Madrid! Da möchte ich auch mal hin. Spielen wir doch mal in Madrid!",
"Herr Lehmann kommt durch den Wagen. Er geht zum Bordrestaurant. Er fragt: Möchten Sie auch einen Kaffee? Ich lade Sie ein! Sofia und Mia sagen: Ja, gern! Herr Lehmann bringt drei Kaffee. Er sagt: Auf eine gute Reise!",
"Plötzlich bleibt der Zug stehen. Draußen sind nur Felder. Eine Durchsage kommt: Wegen einer Störung bleibt der Zug hier etwa zwanzig Minuten stehen. Wir bitten um Entschuldigung. Herr Lehmann sagt: Na, das wird ja eine lange Fahrt!",
"Sofia schreibt Julia eine Nachricht: Der Zug hat Verspätung. Ich komme etwa um zwölf Uhr an. Julia antwortet: Kein Problem! Ich warte am Bahnhof. Ich freue mich so! Sofia schickt ein Herz zurück. Sie freut sich auch.",
"Nach zwanzig Minuten fährt der Zug weiter. Die Fahrt ist jetzt ruhig. Sofia liest ein Buch. Mia schläft ein bisschen. Herr Lehmann löst ein Kreuzworträtsel. Er fragt: Ein Fluss in Deutschland mit vier Buchstaben? Sofia sagt: Main? Er sagt: Richtig!",
"Der Zug fährt durch Stuttgart. Dann geht es weiter nach Augsburg. Die Landschaft ändert sich. Jetzt sieht man schon die Berge. Die Alpen sind weit weg, aber man sieht sie gut. Sie haben schon Schnee auf den Gipfeln.",
"Um zwölf Uhr zehn kommt der Zug in München an. Eine Durchsage sagt: Sehr geehrte Fahrgäste, in wenigen Minuten erreichen wir München Hauptbahnhof. Bitte vergessen Sie Ihr Gepäck nicht. Wir wünschen Ihnen einen schönen Tag.",
"Sofia, Mia und Herr Lehmann steigen aus. Mia gibt Sofia eine Karte. Sie sagt: Das ist für mein Konzert heute Abend. Komm doch mit deiner Freundin! Sofia sagt: Wirklich? Danke! Das ist ein tolles Geschenk für Julias Geburtstag!",
"Herr Lehmann sagt: Auf Wiedersehen, meine Damen! Es war eine schöne Reise. Seine Tochter wartet am Gleis. Sie hat das Baby im Arm. Herr Lehmann nimmt das Baby. Er strahlt. Sofia winkt ihm zu.",
"Am Ende des Gleises steht Julia. Sie hat einen Luftballon in der Hand. Sie ruft: Sofia! Endlich! Die Freundinnen umarmen sich. Sofia sagt: Alles Gute zum Geburtstag! Julia sagt: Danke! Und jetzt gehen wir erst mal essen. Du hast bestimmt Hunger.",
"Sie gehen in ein bayerisches Restaurant. Es heißt Zum Löwen. Sofia bestellt Weißwurst mit Brezel. Julia bestellt Schweinebraten mit Knödel. Sofia probiert die Weißwurst. Sie sagt: Interessant! Aber ich bleibe lieber bei Paella.",
"Sofia gibt Julia das Geschenk. Julia freut sich über das Buch und die Kerze. Dann zeigt Sofia die Konzertkarte. Julia sagt: Ein Konzert? Heute Abend? Wie hast du das gemacht? Sofia erzählt von Mia. Julia lacht: Du findest überall Freunde!",
"Am Nachmittag zeigt Julia ihr München. Sie gehen zum Marienplatz. Dort steht das Rathaus. Um fünf Uhr tanzen die Figuren am Rathausturm. Viele Touristen machen Fotos. Dann gehen sie in den Englischen Garten. Dort surfen Leute im Fluss!",
"Am Abend gehen sie ins Konzert. Der Saal ist groß und elegant. Das Orchester spielt Mozart. Sofia sieht Mia auf der Bühne. Mia spielt wunderbar. Am Ende klatschen alle lange. Nach dem Konzert treffen sie Mia. Julia sagt: Danke! Das war mein schönster Geburtstag!",
"Am Sonntag frühstücken Julia und Sofia lange. Dann besuchen sie ein Museum. Am Montagmorgen fährt Sofia zurück nach Frankfurt. Diesmal hat der Zug keine Verspätung. Sofia ist fast enttäuscht. Sie denkt: Mit Verspätung war es lustiger.",
"Zu Hause sieht Sofia ihren Ausweis auf dem Tisch. Sie lacht. Sie schreibt auf einen Zettel: Ausweis nicht vergessen! Den Zettel klebt sie an die Tür. Dann schreibt sie Mia eine Nachricht: Danke für alles! Bis bald in Madrid! Ende."]});

BOOKS.push({id:"a1-arbeit",lv:"A1",t:"Mein erster Arbeitstag",tr:"İlk iş günüm",em:"💼",c:["#5e5ce6","#bf5af2"],p:[
"Ich heiße Deniz. Ich bin achtundzwanzig Jahre alt. Ich komme aus Ankara. Ich bin Informatikerin. Seit zwei Wochen wohne ich in Hamburg. Morgen beginnt meine neue Arbeit. Ich arbeite bei einer Logistikfirma. Ich bin sehr aufgeregt.",
"Am Abend bereite ich alles vor. Ich lege meine Kleidung auf den Stuhl. Ich nehme eine blaue Hose, eine weiße Bluse und eine graue Jacke. Ich packe meine Tasche. In der Tasche sind mein Laptop, ein Heft und ein Kuli. Ich stelle den Wecker auf sechs Uhr.",
"Ich kann nicht gut schlafen. Ich denke an morgen. Sind die Kollegen nett? Verstehe ich alles auf Deutsch? Ist die Arbeit schwer? Um Mitternacht schlafe ich endlich ein. Ich träume von Computern und Containern.",
"Um sechs Uhr klingelt der Wecker. Ich stehe sofort auf. Ich dusche und ziehe mich an. Ich frühstücke ein Müsli mit Joghurt und trinke einen Tee. Dann sehe ich in den Spiegel und sage: Du schaffst das, Deniz!",
"Ich fahre mit der U-Bahn zur Arbeit. Die Firma ist im Hafen. Der Hamburger Hafen ist riesig. Es gibt viele Schiffe und Container in allen Farben. Ich sehe Kräne und Lastwagen. Es riecht nach Wasser und Diesel.",
"Das Bürogebäude ist modern. Es ist aus Glas. Am Empfang sitzt eine Frau. Ich sage: Guten Morgen. Mein Name ist Deniz Kaya. Heute ist mein erster Arbeitstag. Die Frau lächelt und sagt: Herzlich willkommen, Frau Kaya! Einen Moment, bitte.",
"Ein Mann kommt die Treppe herunter. Er ist groß und hat einen Bart. Er sagt: Guten Morgen, Frau Kaya! Ich bin Thomas Becker, Ihr Teamleiter. Herzlich willkommen! Er gibt mir die Hand. Er sagt: Bei uns sagen alle du. Ich bin Thomas.",
"Ich sage: Gern! Ich bin Deniz. Thomas sagt: Komm, ich zeige dir zuerst das Büro. Wir gehen in den dritten Stock. Das Büro ist groß und hell. Es gibt viele Tische. An der Wand hängt ein großer Bildschirm. Darauf sieht man eine Karte mit Schiffen.",
"Thomas erklärt: Das ist unser Team. Wir sind acht Personen. Wir machen die Software für die Container. Wir wissen immer, wo jeder Container ist. Ich finde das sehr interessant. Thomas sagt: Und das ist dein Platz. Mein Tisch ist am Fenster. Ich sehe den Hafen!",
"Dann stellt Thomas mir das Team vor. Das ist Jana. Sie ist Programmiererin. Das ist Ole. Er macht die Datenbanken. Das ist Mehmet. Er kommt auch aus der Türkei, aus Bursa. Mehmet sagt auf Türkisch: Hoş geldin! Ich freue mich sehr.",
"Jana bekommt den Auftrag, mir alles zu zeigen. Sie ist sehr nett und geduldig. Sie zeigt mir den Computer. Sie gibt mir ein Passwort. Sie erklärt mir die Programme. Ich mache viele Notizen. Es sind viele neue Wörter.",
"Manchmal verstehe ich nicht alles. Jana spricht schnell. Ich sage: Entschuldigung, kannst du das bitte wiederholen? Jana sagt: Klar! Entschuldige, ich spreche zu schnell. Dann spricht sie langsamer. Ich verstehe jetzt alles.",
"Um zehn Uhr gibt es eine Besprechung. Das Team steht zusammen am großen Bildschirm. Jeder sagt kurz: Was mache ich heute? Gibt es Probleme? Das dauert nur fünfzehn Minuten. Thomas sagt: Das ist unser Daily. Wir machen das jeden Morgen.",
"Dann sagt Thomas: Deniz, möchtest du dich kurz vorstellen? Alle sehen mich an. Ich bin nervös. Ich sage: Hallo, ich heiße Deniz. Ich komme aus Ankara. Ich habe fünf Jahre bei einer Bank als Informatikerin gearbeitet. Ich freue mich auf die Arbeit mit euch.",
"Alle klatschen. Ole sagt: Willkommen! Und was machst du gern in der Freizeit? Ich sage: Ich lese gern und ich gehe gern schwimmen. Ole sagt: Ich schwimme auch! Wir können mal zusammen gehen. Ich freue mich. Das Team ist wirklich nett.",
"Um zwölf Uhr ist Mittagspause. Mehmet sagt: Komm, wir gehen zusammen essen! Es gibt eine Kantine im Erdgeschoss. Heute gibt es Fischbrötchen, Currywurst oder Gemüsesuppe. Ich nehme ein Fischbrötchen. Mehmet sagt: In Hamburg musst du Fischbrötchen essen!",
"Beim Essen erzählt Mehmet von seinem Leben in Hamburg. Er wohnt schon zehn Jahre hier. Er sagt: Am Anfang war das Wetter schlimm. Es regnet so oft! Aber jetzt liebe ich Hamburg. Die Stadt ist offen und international.",
"Mehmet gibt mir viele Tipps. Er sagt: Kauf dir eine gute Regenjacke. Geh am Wochenende an die Elbe. Und probier das Franzbrötchen beim Bäcker. Das ist eine Hamburger Spezialität! Ich schreibe alles in mein Heft.",
"Am Nachmittag bekomme ich meine erste Aufgabe. Ich soll einen kleinen Fehler im Programm finden. Ich suche und suche. Nach einer Stunde finde ich den Fehler. Ich korrigiere ihn. Jana prüft meine Arbeit. Sie sagt: Super, Deniz! Das ist richtig!",
"Um drei Uhr gibt es Kaffee und Kuchen. Heute hat Ole Geburtstag. Er hat einen Kuchen mitgebracht. Alle singen: Zum Geburtstag viel Glück! Ich singe auch mit. Ole ist ein bisschen rot im Gesicht. Der Kuchen ist mit Schokolade und sehr lecker.",
"Ich lerne in der Kaffeepause viel über die Firma. Es gibt mehr als zweihundert Mitarbeiter. Die Firma hat Büros in Rotterdam, Singapur und Istanbul. Thomas sagt: Vielleicht kannst du später mal nach Istanbul fahren. Wir brauchen dort manchmal Hilfe.",
"Um fünf Uhr sagt Thomas: Deniz, das war genug für den ersten Tag. Geh nach Hause und ruh dich aus. Ich sage: Danke! Es war ein toller Tag. Alle sagen: Tschüss, Deniz! Bis morgen! Ich nehme meine Tasche und gehe.",
"Draußen regnet es. Natürlich! Mehmet hatte recht. Ich habe keine Regenjacke. Ich werde nass. Aber das ist mir egal. Ich bin glücklich. Mein erster Arbeitstag war gut. Ich habe nette Kollegen und eine interessante Arbeit.",
"Zu Hause rufe ich meine Mutter in Ankara an. Sie fragt: Wie war es, mein Kind? Ich erzähle alles. Vom Hafen, vom Team, vom Fischbrötchen. Meine Mutter lacht. Sie sagt: Ich bin so stolz auf dich. Aber kauf dir eine Regenjacke!",
"Die erste Woche geht schnell vorbei. Jeden Tag lerne ich etwas Neues. Mein Deutsch wird besser. Ich verstehe jetzt auch die Witze von Ole. Am Freitag gehen alle zusammen in eine Bar am Hafen. Wir sitzen draußen und sehen die Schiffe.",
"Am Samstag kaufe ich eine Regenjacke. Sie ist gelb. Mehmet sagt: Jetzt bist du eine echte Hamburgerin! Am Sonntag gehe ich an die Elbe. Ich gehe am Wasser spazieren. Große Schiffe fahren vorbei. Ich esse ein Franzbrötchen. Es ist süß und schmeckt nach Zimt.",
"In der zweiten Woche habe ich ein großes Projekt. Ich soll eine neue Funktion programmieren. Die Funktion zeigt, wann ein Schiff im Hafen ankommt. Das ist wichtig für die Kunden. Ich arbeite mit Jana zusammen. Wir sind ein gutes Team.",
"Am Ende des Monats präsentiere ich die neue Funktion. Der Chef von der ganzen Abteilung ist auch da. Ich bin nervös, aber die Präsentation geht gut. Der Chef sagt: Sehr gute Arbeit, Frau Kaya. Willkommen in unserer Firma!",
"Nach der Präsentation gehe ich mit Ole schwimmen. Das Schwimmbad ist groß und modern. Wir schwimmen eine Stunde. Danach trinken wir eine heiße Schokolade. Ole sagt: Du bist erst einen Monat hier, aber es fühlt sich an wie ein Jahr.",
"Am Abend schreibe ich in mein Tagebuch: Vor einem Monat hatte ich Angst. Ich kannte niemanden in Hamburg. Jetzt habe ich Freunde und eine Arbeit, die ich liebe. Hamburg ist mein neues Zuhause. Auch wenn es oft regnet. Ende."]});

BOOKS.push({id:"a1-markt",lv:"A1",t:"Samstag auf dem Markt",tr:"Pazarda cumartesi",em:"🍎",c:["#ff9500","#30d158"],p:[
"Jeden Samstag gibt es in Freiburg einen großen Markt. Der Markt ist auf dem Platz vor dem Münster. Das Münster ist eine alte, große Kirche. Der Markt beginnt um sieben Uhr am Morgen und endet um eins. Hier kaufen viele Menschen frisches Obst und Gemüse.",
"Herr und Frau Weber gehen jeden Samstag auf den Markt. Sie sind beide Rentner. Er heißt Karl, sie heißt Gisela. Sie sind seit fünfundvierzig Jahren verheiratet. Sie haben drei Kinder und sieben Enkelkinder. Morgen kommt die ganze Familie zum Essen.",
"Gisela schreibt eine Einkaufsliste. Auf der Liste stehen: Kartoffeln, Karotten, Zwiebeln, Salat, Tomaten, Äpfel, Erdbeeren, Käse, Eier, Brot und Blumen. Karl liest die Liste. Er sagt: Das ist viel! Wir brauchen zwei Taschen. Gisela sagt: Nein, drei!",
"Um acht Uhr sind sie auf dem Markt. Es ist schon voll. Die Sonne scheint. Überall sind Stände mit bunten Farben. Rote Tomaten, gelbe Paprika, grüner Salat, orange Karotten. Es riecht nach Blumen, Brot und Kaffee. Karl sagt: Ich liebe den Samstag!",
"Zuerst gehen sie zum Gemüsestand von Frau Klein. Frau Klein hat einen Bauernhof. Ihr Gemüse ist immer frisch. Sie sagt: Guten Morgen, Familie Weber! Was darf es heute sein? Gisela sagt: Zwei Kilo Kartoffeln, bitte. Und ein Kilo Karotten.",
"Frau Klein legt die Kartoffeln auf die Waage. Zwei Kilo genau. Dann die Karotten. Gisela fragt: Haben Sie auch Spargel? Frau Klein sagt: Ja, der erste Spargel ist da! Er ist ganz frisch, von heute Morgen. Ein Kilo kostet zwölf Euro.",
"Karl sagt: Zwölf Euro? Das ist teuer! Gisela sagt: Aber die Kinder lieben Spargel. Wir nehmen zwei Kilo. Frau Klein lacht und sagt: Für Sie mache ich einen guten Preis. Zwei Kilo für zwanzig Euro. Karl sagt: Na gut. Danke schön!",
"Am nächsten Stand gibt es Obst. Der Verkäufer ist ein junger Mann. Er ruft laut: Erdbeeren! Frische Erdbeeren aus Baden! Probieren Sie mal! Er gibt Gisela eine Erdbeere. Sie probiert. Sie sagt: Mmh, die ist süß! Wir nehmen zwei Schalen.",
"Karl kauft auch Äpfel. Er fragt: Welche Äpfel sind gut zum Backen? Der Verkäufer sagt: Diese hier. Sie sind ein bisschen sauer. Perfekt für Apfelkuchen. Karl nimmt zwei Kilo. Gisela backt morgen einen Apfelkuchen. Sie backt den besten Apfelkuchen der Welt.",
"Dann gehen sie zum Käsestand. Hier gibt es viele Sorten Käse. Es gibt Käse aus der Schweiz, aus Frankreich und aus dem Schwarzwald. Der Verkäufer heißt Pierre. Er kommt aus dem Elsass. Er spricht Deutsch mit einem französischen Akzent.",
"Pierre fragt: Möchten Sie probieren? Er gibt Karl ein Stück Bergkäse. Karl sagt: Der ist sehr gut! Kräftig! Pierre gibt Gisela ein Stück Camembert. Sie sagt: Oh, der ist schön weich. Sie kaufen beide. Pierre packt den Käse in Papier ein.",
"Jetzt sind die Taschen schon schwer. Karl sagt: Ich brauche eine Pause! Sie gehen zu einem kleinen Stand. Dort gibt es Kaffee und Bratwurst. Die Freiburger Spezialität heißt Lange Rote. Das ist eine sehr lange, rote Wurst im Brötchen.",
"Karl bestellt eine Lange Rote mit Zwiebeln. Gisela nimmt nur einen Kaffee. Sie stehen an einem kleinen Tisch. Neben ihnen steht eine junge Frau mit einem Kinderwagen. Das Baby schläft. Die Frau sagt: Entschuldigung, wissen Sie, wo es Honig gibt?",
"Gisela sagt: Ja, der Honigstand ist dort hinten, neben der Kirche. Der Mann heißt Herr Wolf. Er hat eigene Bienen. Sein Honig ist wunderbar. Die junge Frau sagt: Vielen Dank! Ich bin neu in Freiburg. Ich kenne den Markt noch nicht.",
"Gisela fragt: Woher kommen Sie? Die Frau sagt: Ich komme aus Polen. Ich heiße Kasia. Mein Mann arbeitet an der Universität. Das ist mein Sohn Jan. Gisela sieht das Baby an. Sie sagt: Was für ein süßes Baby! Wie alt ist er? Kasia sagt: Vier Monate.",
"Karl und Gisela gehen mit Kasia zum Honigstand. Herr Wolf hat viele Sorten Honig. Es gibt Blütenhonig, Waldhonig und Lindenhonig. Kasia probiert alle. Sie kauft den Waldhonig. Herr Wolf schenkt ihr noch eine kleine Kerze aus Bienenwachs.",
"Kasia sagt: Die Menschen hier sind so freundlich! Gisela sagt: Ja, der Markt ist wie eine große Familie. Viele Leute kennen sich seit Jahren. Kommen Sie doch jeden Samstag! Kasia lächelt und sagt: Das mache ich. Sehr gern.",
"Jetzt fehlen noch Brot und Blumen. Am Brotstand gibt es viele Sorten. Es gibt Weißbrot, Roggenbrot, Vollkornbrot und Brezeln. Gisela kauft ein großes Bauernbrot und sechs Brezeln. Die Kinder essen Brezeln sehr gern.",
"Der letzte Stand ist der Blumenstand. Die Blumen sind wunderschön. Es gibt Tulpen, Rosen und Sonnenblumen. Karl sieht die Rosen an. Er sagt: Gisela, such dir Blumen aus. Ich lade dich ein. Gisela sagt: Aber Karl, das ist doch nicht nötig!",
"Karl sagt: Doch! Morgen ist ein besonderer Tag. Die ganze Familie kommt. Und du arbeitest so viel. Gisela sucht gelbe Tulpen aus. Sie sind ihre Lieblingsblumen. Karl bezahlt. Gisela gibt ihm einen Kuss. Die Verkäuferin lächelt.",
"Mit drei schweren Taschen gehen sie nach Hause. Sie wohnen nicht weit vom Markt. Aber die Taschen sind sehr schwer. Karl sagt: Nächstes Mal nehmen wir das Auto! Gisela lacht. Sie sagt das jede Woche. Und jede Woche gehen sie zu Fuß.",
"Zu Hause packen sie aus. Gisela stellt die Tulpen in eine Vase. Karl stellt den Käse in den Kühlschrank. Dann trinken sie zusammen Tee auf dem Balkon. Gisela sagt: Das war ein schöner Markt heute. Karl sagt: Ja. Wie immer.",
"Am Nachmittag backt Gisela den Apfelkuchen. Karl schält die Äpfel. Das Haus riecht nach Zimt und Butter. Dann bereiten sie das Essen für morgen vor. Karl schält den Spargel. Gisela macht die Soße. Es gibt Spargel mit Kartoffeln und Schinken.",
"Am Sonntag um zwölf Uhr klingelt es. Die erste Familie kommt. Das ist die Tochter mit ihrem Mann und zwei Kindern. Dann kommt der Sohn mit seiner Frau und drei Kindern. Zum Schluss kommt die jüngste Tochter mit zwei Kindern. Das Haus ist voll.",
"Die Kinder laufen in den Garten. Die Erwachsenen sitzen im Wohnzimmer. Alle reden gleichzeitig. Es ist laut, aber fröhlich. Gisela sagt: Das Essen ist fertig! Alle setzen sich an den großen Tisch. Es sind vierzehn Personen.",
"Der Spargel ist perfekt. Die Kinder essen die Kartoffeln und den Schinken. Sie mögen den Spargel nicht so gern. Aber die Erwachsenen essen viel. Der Sohn sagt: Mama, das ist der beste Spargel in ganz Baden! Gisela lächelt stolz.",
"Zum Nachtisch gibt es den Apfelkuchen und die Erdbeeren mit Sahne. Die Kinder essen zwei Stück Kuchen. Die Enkeltochter Lea sagt: Oma, wie machst du den Kuchen? Gisela sagt: Das ist ein Geheimnis. Aber dir erzähle ich es irgendwann.",
"Am Nachmittag gehen alle zusammen spazieren. Sie gehen durch die Altstadt. In Freiburg gibt es kleine Bäche in den Straßen. Sie heißen Bächle. Die Kinder spielen mit Booten aus Papier im Wasser. Es gibt eine Legende: Wer in ein Bächle tritt, heiratet einen Freiburger.",
"Am Abend fahren alle wieder nach Hause. Das Haus ist plötzlich still. Karl und Gisela sitzen auf dem Sofa. Sie sind müde, aber glücklich. Gisela sagt: Die Familie ist das Wichtigste. Karl nimmt ihre Hand. Er sagt: Und du bist das Wichtigste für mich.",
"Am nächsten Samstag gehen sie wieder auf den Markt. Kasia ist auch da. Mit Jan im Kinderwagen. Sie ruft: Frau Weber! Herr Weber! Sie bringt einen polnischen Kuchen mit. Für Sie, sagt sie. Gisela sagt: Siehst du, Karl? Der Markt ist wie eine große Familie. Ende."]});

BOOKS.push({id:"a1-wien",lv:"A1",t:"Ein Wochenende in Wien",tr:"Viyana'da bir hafta sonu",em:"🎻",c:["#ff2d55","#ff9f0a"],p:[
"Murat und Selin sind verheiratet. Sie wohnen in Istanbul. Murat ist Ingenieur, Selin ist Krankenschwester. Sie lernen beide Deutsch. Sie möchten vielleicht nach Wien ziehen. Aber zuerst wollen sie die Stadt sehen. Sie fliegen für ein Wochenende nach Wien.",
"Der Flug dauert zweieinhalb Stunden. Sie landen am Freitagabend am Flughafen Wien. Am Flughafen nehmen sie den Zug in die Stadt. Der Zug heißt City Airport Train. Er fährt nur sechzehn Minuten bis ins Zentrum. Murat sagt: Das ist schnell!",
"Ihr Hotel ist im ersten Bezirk. Der erste Bezirk ist das Zentrum von Wien. Das Hotel ist klein und alt, aber sehr schön. An der Rezeption sitzt ein älterer Herr. Er sagt: Grüß Gott! Herzlich willkommen in Wien! Selin flüstert: Was bedeutet Grüß Gott? Murat sagt: Das sagt man hier für Guten Tag.",
"Das Zimmer ist im vierten Stock. Es hat ein großes Bett und ein altes Fenster. Vom Fenster sieht man den Stephansdom. Der Dom ist hell beleuchtet. Selin sagt: Wie schön! Sie öffnen das Fenster. Man hört Glocken. Es ist zehn Uhr am Abend.",
"Am Samstagmorgen frühstücken sie im Hotel. Es gibt Semmeln, Butter, Marmelade, Käse und Schinken. Es gibt auch weiche Eier. Selin fragt: Was ist eine Semmel? Der Kellner lacht und sagt: Das ist ein Brötchen. In Österreich sagen wir Semmel.",
"Nach dem Frühstück gehen sie zum Stephansdom. Der Dom ist sehr alt und sehr hoch. Das Dach hat bunte Ziegel. Innen ist es dunkel und still. Viele Touristen sind da. Murat und Selin steigen auf den Turm. Es gibt dreihundertdreiundvierzig Stufen!",
"Oben sind sie müde, aber die Aussicht ist toll. Sie sehen ganz Wien. Sie sehen die Dächer, die Kirchen und den Prater mit dem Riesenrad. Murat sagt: Die Stadt ist so schön. Und so sauber! Selin sagt: Ja, und es gibt so viele Parks.",
"Dann gehen sie durch die Altstadt. Die Straßen sind schmal und alt. Es gibt viele Geschäfte und Cafés. Auf der Kärntner Straße spielt ein Mann Geige. Er spielt Mozart. Viele Leute bleiben stehen und hören zu. Selin gibt ihm zwei Euro.",
"Um elf Uhr gehen sie in ein Kaffeehaus. In Wien sind Kaffeehäuser sehr wichtig. Das Kaffeehaus heißt Café Central. Es ist sehr elegant. Es hat hohe Decken und große Lampen. Die Kellner tragen schwarze Anzüge. Hier haben früher berühmte Schriftsteller gesessen.",
"Der Kellner bringt die Karte. Es gibt viele Sorten Kaffee. Melange, Einspänner, Brauner, Verlängerter. Selin versteht nichts. Sie fragt den Kellner: Was ist eine Melange? Der Kellner erklärt: Das ist Kaffee mit Milch und Milchschaum. Wie ein Cappuccino.",
"Selin bestellt eine Melange. Murat bestellt einen Einspänner. Das ist Kaffee mit viel Schlagobers. Schlagobers ist in Österreich die Sahne. Dazu essen sie Sachertorte. Das ist eine Schokoladentorte mit Marmelade. Murat sagt: Die ist sehr süß, aber sehr gut!",
"Am Nachmittag besuchen sie das Schloss Schönbrunn. Sie fahren mit der U-Bahn. Die U-Bahn in Wien ist modern und pünktlich. Das Schloss ist gelb und riesig. Hier hat die Kaiserin Sisi gewohnt. Sie machen eine Führung durch das Schloss.",
"Die Zimmer sind voller Gold und Spiegel. Die Führerin erzählt viel über die Geschichte. Selin versteht nicht alles. Aber sie versteht: Sisi war schön, aber nicht glücklich. Sie war oft allein. Sie reiste viel. Selin sagt: Die arme Sisi!",
"Hinter dem Schloss ist ein großer Garten. Sie gehen auf einen kleinen Hügel. Dort steht die Gloriette. Das ist ein Gebäude mit einem Café. Von dort sieht man das Schloss und die Stadt. Sie trinken eine Limonade und ruhen sich aus.",
"Am Abend wollen sie typisch österreichisch essen. Sie gehen in ein Gasthaus. Es heißt Zum Schwarzen Kameel. Murat bestellt ein Wiener Schnitzel mit Erdäpfelsalat. Erdäpfel heißt Kartoffeln. Selin bestellt einen Tafelspitz. Das ist gekochtes Rindfleisch mit Soße.",
"Das Schnitzel ist riesig. Es ist größer als der Teller! Murat isst alles. Selin probiert ein Stück. Sie sagt: Das ist wirklich sehr gut. Zum Nachtisch bestellen sie Kaiserschmarrn. Das ist ein süßer Pfannkuchen mit Rosinen und Zucker.",
"Nach dem Essen machen sie einen Spaziergang. Wien ist am Abend sehr schön. Die Gebäude sind beleuchtet. Sie gehen zur Oper. Heute gibt es eine Vorstellung. Viele Menschen in eleganter Kleidung gehen hinein. Selin sagt: Das nächste Mal gehen wir in die Oper!",
"Am Sonntag schlafen sie lange. Dann wollen sie sehen, wie Menschen in Wien wirklich leben. Sie fahren in einen anderen Bezirk. Es ist der zweite Bezirk. Hier gibt es keine Touristen. Hier wohnen normale Familien. Es gibt Spielplätze, Supermärkte und kleine Läden.",
"Sie gehen in einen Park. Der Park heißt Augarten. Familien machen ein Picknick. Kinder spielen Fußball. Ein alter Mann füttert die Vögel. Selin sagt: Hier ist es ruhig und grün. Hier könnten wir wohnen. Murat sagt: Ja, das gefällt mir auch.",
"Auf einer Bank sitzt eine Frau. Sie liest ein türkisches Buch. Selin fragt auf Türkisch: Entschuldigung, sind Sie aus der Türkei? Die Frau lächelt. Sie heißt Hatice. Sie wohnt seit fünfzehn Jahren in Wien. Sie ist auch Krankenschwester!",
"Selin ist begeistert. Sie fragt viel. Wie ist die Arbeit im Krankenhaus? Wie lange dauert die Anerkennung vom Diplom? Hatice erklärt alles. Sie sagt: Am Anfang braucht man viel Geduld. Man braucht gutes Deutsch. Aber es lohnt sich. Die Arbeit hier ist gut.",
"Hatice gibt Selin ihre Telefonnummer. Sie sagt: Wenn ihr nach Wien kommt, ruf mich an. Ich helfe dir gern. Selin sagt: Vielen Dank! Das ist so nett von Ihnen. Murat sagt: Siehst du? Die Wiener sind freundlich. Hatice lacht: Ich bin aber aus Kayseri!",
"Am Nachmittag fahren sie zum Naschmarkt. Das ist ein großer Markt. Es gibt Obst, Gemüse, Gewürze und viele kleine Restaurants. Es gibt auch türkische Stände mit Börek und Baklava. Murat sagt: Hier fühle ich mich wie zu Hause!",
"Dann gehen sie zur Donau. Die Donau ist ein großer Fluss. Es gibt eine lange Insel im Fluss. Sie heißt Donauinsel. Hier fahren die Leute Rad, joggen und schwimmen im Sommer. Murat und Selin gehen am Wasser spazieren. Die Sonne geht langsam unter.",
"Selin fragt: Murat, was denkst du? Können wir hier leben? Murat denkt lange nach. Dann sagt er: Die Stadt ist schön und sicher. Es gibt gute Arbeit. Aber es ist weit weg von unserer Familie. Und das Deutsch ist noch schwer.",
"Selin sagt: Ja, aber wir lernen jeden Tag. Und Istanbul ist nur zweieinhalb Stunden mit dem Flugzeug entfernt. Wir können oft nach Hause fliegen. Murat lächelt. Er sagt: Du hast recht. Lass uns mehr Deutsch lernen. Und dann sehen wir weiter.",
"Am letzten Abend sitzen sie in einem Heurigen. Ein Heuriger ist ein Gasthaus am Stadtrand. Dort trinken die Wiener jungen Wein. Es gibt Brot, Käse und Wurst. Ein Mann spielt Akkordeon. Die Atmosphäre ist fröhlich und gemütlich.",
"Am Nebentisch sitzt eine Familie. Sie feiern Geburtstag. Der Vater fragt: Woher kommen Sie? Murat sagt: Aus Istanbul. Der Vater ruft: Istanbul! Da war ich letztes Jahr. Wunderschön! Er bestellt für alle ein Glas Traubensaft. Sie trinken auf die Freundschaft.",
"Am Montagmorgen fliegen sie zurück. Im Flugzeug sieht Selin auf die Fotos. Der Dom, das Schloss, das Kaffeehaus, die Donau. Sie sagt: Was für ein schönes Wochenende. Murat sagt: Ich habe eine Idee. Ab heute sprechen wir jeden Abend eine Stunde Deutsch zusammen.",
"Selin lacht und sagt: Einverstanden! Aber dann musst du auch kochen. Murat sagt: Gut. Dann koche ich Wiener Schnitzel! Sie lachen beide. Draußen sehen sie die Wolken. Unten liegt die Donau. Selin sagt leise: Auf Wiedersehen, Wien. Bis bald. Ende."]});

BOOKS.push({id:"a1-geburtstag",lv:"A1",t:"Die Überraschung",tr:"Sürpriz",em:"🎂",c:["#bf5af2","#ff2d78"],p:[
"Es ist Montag. Lena ist im Büro. Sie trinkt Kaffee und sieht in den Kalender. Am Freitag hat ihr Freund Max Geburtstag. Er wird dreißig. Lena denkt: Dreißig ist ein besonderer Geburtstag. Ich mache eine Überraschungsparty!",
"Lena und Max wohnen zusammen in Leipzig. Sie wohnen seit zwei Jahren zusammen. Max ist Koch. Er arbeitet in einem Restaurant. Er arbeitet oft am Abend und am Wochenende. Lena ist Grafikdesignerin. Sie arbeitet in einer Agentur.",
"Die Party muss geheim sein. Max darf nichts wissen. Aber das ist nicht leicht. Max ist sehr neugierig. Er fragt immer: Was machst du? Mit wem telefonierst du? Lena muss vorsichtig sein. Sie hat einen Plan.",
"In der Mittagspause schreibt Lena eine Liste. Wer kommt zur Party? Die Eltern von Max. Seine Schwester Hannah. Seine besten Freunde Tim und Jonas. Die Kollegen aus dem Restaurant. Und natürlich ihre eigenen Freundinnen. Insgesamt sind es zwanzig Personen.",
"Wo machen wir die Party? Die Wohnung ist zu klein für zwanzig Personen. Lena ruft ihre Freundin Clara an. Clara hat ein Café. Lena fragt: Clara, kann ich am Freitagabend dein Café mieten? Clara sagt: Natürlich! Für dich mache ich das gern. Und kostenlos!",
"Am Dienstag schreibt Lena allen Gästen eine Nachricht. Sie schreibt: Überraschungsparty für Max! Freitag um acht Uhr im Café Clara. Bitte nichts sagen! Max weiß nichts! Alle antworten schnell. Alle kommen. Lena freut sich.",
"Am Dienstagabend kommt Max nach Hause. Lena sitzt mit dem Handy auf dem Sofa. Max fragt: Mit wem schreibst du? Lena wird ein bisschen rot. Sie sagt: Mit meiner Mutter. Max sagt: So lange? Lena sagt: Ja, sie hat viele Fragen. Max findet das komisch.",
"Am Mittwoch hat Lena ein Problem. Max sagt: Am Freitag habe ich frei. Wollen wir zusammen essen gehen? Nur wir zwei? Lena denkt schnell. Sie sagt: Gute Idee! Aber ich muss am Freitag bis acht arbeiten. Wir treffen uns danach. Ich zeige dir ein neues Café.",
"Max sagt: Ein neues Café? Welches? Lena sagt: Das ist eine Überraschung. Für deinen Geburtstag. Max lacht. Er sagt: Okay, ich bin gespannt! Lena denkt: Puh! Das war knapp. Er weiß nichts. Hoffentlich.",
"Am Donnerstag kauft Lena das Geschenk. Max wünscht sich schon lange ein gutes Messer. Ein japanisches Kochmesser. Lena geht in ein Fachgeschäft. Der Verkäufer zeigt ihr viele Messer. Sie sind sehr scharf und sehr teuer.",
"Lena wählt ein schönes Messer aus. Es kostet zweihundert Euro. Das ist viel Geld. Aber Max ist es wert. Der Verkäufer packt das Messer schön ein. Er sagt: Ihr Freund hat Glück. Das ist ein tolles Geschenk. Lena lächelt.",
"Am Donnerstagabend backt Lena eine Torte. Max ist im Restaurant. Er kommt erst um Mitternacht nach Hause. Lena hat Zeit. Sie backt eine Schokoladentorte. Max liebt Schokolade. Sie schreibt mit Sahne auf die Torte: Alles Gute, Max! 30!",
"Die Torte ist fertig. Aber wo kann Lena sie verstecken? Im Kühlschrank geht nicht. Max sieht sofort in den Kühlschrank. Lena hat eine Idee. Sie bringt die Torte zu ihrer Nachbarin, Frau Schulz. Frau Schulz sagt: Kein Problem. Ich passe auf die Torte auf.",
"Um Mitternacht kommt Max nach Hause. Er ist müde. Er sagt: Hier riecht es nach Schokolade. Lena sagt schnell: Ich habe eine Kerze angezündet. Eine Schokoladenkerze. Max riecht noch einmal. Er sagt: Komisch. Aber gut! Dann geht er schlafen.",
"Am Freitagmorgen ist Max Geburtstag. Lena steht früh auf. Sie macht Frühstück. Sie singt: Happy Birthday, lieber Max! Max lacht. Sie gibt ihm einen Kuss. Er fragt: Und wo ist mein Geschenk? Lena sagt: Heute Abend! Hab Geduld.",
"Am Nachmittag ist Lena im Café Clara. Sie und Clara dekorieren das Café. Sie hängen bunte Luftballons auf. Sie hängen ein großes Schild auf: Herzlichen Glückwunsch, Max! Sie stellen Kerzen auf die Tische. Das Café sieht wunderschön aus.",
"Um halb acht kommen die Gäste. Die Eltern von Max kommen zuerst. Sie haben Blumen dabei. Dann kommen Tim und Jonas. Sie bringen Musik mit. Dann kommen die Kollegen aus dem Restaurant. Sie haben ein großes Buffet gekocht. Alle sind sehr aufgeregt.",
"Um Viertel vor acht schreibt Lena Max eine Nachricht: Ich bin gleich fertig. Wir treffen uns um acht vor dem Café Clara. In der Bergstraße. Max antwortet: Okay! Bis gleich! Lena sagt zu allen: Er kommt in fünfzehn Minuten! Licht aus!",
"Das Café ist dunkel. Alle sind ganz still. Sie verstecken sich hinter den Tischen und der Theke. Tim muss lachen. Hannah sagt: Psst! Durch das Fenster sieht Lena die Straße. Es ist fünf vor acht. Da kommt Max!",
"Lena geht nach draußen. Sie sagt: Hallo, Geburtstagskind! Max sagt: Hallo! Ist das das neue Café? Es ist ja ganz dunkel. Ist es überhaupt offen? Lena sagt: Komm, wir gehen rein. Sie öffnet die Tür. Max geht hinein. Es ist ganz dunkel.",
"Plötzlich geht das Licht an. Alle springen hoch und rufen: Überraschung! Alles Gute zum Geburtstag! Max steht da. Er ist sprachlos. Er sieht seine Eltern, seine Schwester, seine Freunde und seine Kollegen. Er sagt nur: Was? Wie? Lena!",
"Max ist sehr gerührt. Er hat Tränen in den Augen. Er umarmt seine Mutter. Er umarmt Hannah. Dann umarmt er Lena ganz lange. Er flüstert: Danke. Das ist die schönste Überraschung von meinem Leben. Und ich habe nichts gemerkt!",
"Dann beginnt die Party. Tim macht Musik. Die Kollegen haben ein tolles Buffet gemacht. Es gibt Salate, kleine Pizzas, Hähnchen, Käse und Obst. Alle essen und trinken. Max sagt zu seinen Kollegen: Ihr habt ja mehr gekocht als im Restaurant!",
"Um zehn Uhr bringt Frau Schulz die Torte. Sie ist auch eingeladen. Auf der Torte brennen dreißig Kerzen. Alle singen. Max bläst die Kerzen aus. Er schafft alle dreißig auf einmal. Alle klatschen. Max fragt: Wer hat die Torte gemacht? Lena sagt: Ich.",
"Max probiert die Torte. Er ist Koch. Er weiß, was gut ist. Er sagt: Lena, die ist fantastisch! Jetzt weiß ich auch, warum es gestern nach Schokolade gerochen hat. Schokoladenkerze, ja? Alle lachen. Lena wird rot.",
"Dann gibt Lena ihm das Geschenk. Max öffnet das Paket. Er sieht das japanische Messer. Er ist sprachlos. Er sagt: Das ist das Messer, das ich mir schon so lange wünsche! Woher weißt du das? Lena sagt: Du sprichst seit einem Jahr davon!",
"Die Eltern von Max haben auch ein Geschenk. Es ist ein Gutschein für eine Reise. Eine Reise nach Italien, für zwei Personen. Max und Lena können eine Woche nach Rom fahren. Max sagt: Rom! Da wollte ich schon immer hin! Danke, Mama! Danke, Papa!",
"Die Party geht bis spät in die Nacht. Alle tanzen. Max tanzt mit seiner Mutter. Dann tanzt er mit Hannah. Dann tanzt er mit Lena. Um zwei Uhr gehen die letzten Gäste. Clara sagt: Das war die beste Party in meinem Café!",
"Max und Lena gehen zu Fuß nach Hause. Die Nacht ist warm. Die Sterne leuchten. Max nimmt Lenas Hand. Er sagt: Weißt du was? Ich hatte Angst vor dreißig. Ich dachte, dreißig ist alt. Aber heute war der beste Geburtstag von allen.",
"Lena sagt: Und nächstes Jahr? Max lacht und sagt: Nächstes Jahr mache ich die Überraschung. An deinem Geburtstag. Lena sagt: Oh nein! Du kannst nichts geheim halten! Max sagt: Wir werden sehen. Sie lachen und gehen nach Hause. Ende."]});

